window.MRBOT_DOCS=[{"id":"about","emoji":"🧭","title":{"pl":"O projekcie","ru":"О проекте","en":"About the project","uk":"Про проєкт"},"topics":[{"id":"purpose","title":{"pl":"Czym jest Mr. Robot?","ru":"Что такое Mr. Robot?","en":"What is Mr. Robot?","uk":"Що таке Mr. Robot?"},"basic":{"pl":"Mr. Robot to lokalne narzędzie przeglądarkowe do analizy raportów magazynowych: od KPI po porównywanie baz i audyt.","ru":"Mr. Robot — браузерное приложение для обработки складских отчётов: KPI, сверка баз, аудит и другие инструменты.","en":"Mr. Robot is a browser-based tool for warehouse reports, KPI analysis, stock comparisons and audits.","uk":"Mr. Robot — браузерний інструмент для складських звітів, KPI, звіряння баз і аудиту."},"tech":{"pl":"Aplikacja działa jako PWA. Interfejs i obliczenia uruchamiają się w przeglądarce; raporty nie są wysyłane do backendu aplikacji. Poszczególne moduły mają własne zasady parsowania.","ru":"Приложение работает как PWA. Интерфейс и расчёты выполняются в браузере; Excel-отчёты не отправляются на сервер приложения. У модулей отдельные правила обработки.","en":"The app runs as a PWA. UI and calculations run in the browser; input reports are not uploaded to an app backend. Each module has its own parsing rules.","uk":"Застосунок працює як PWA. Інтерфейс і розрахунки виконуються у браузері; звіти не передаються на сервер застосунку. Модулі мають власні правила обробки."},"source":"README.pl.md: Co to jest; js/app.js; sw.js","related":[{"category":"rights","topic":"license"},{"category":"obsada","topic":"overview"}]},{"id":"architecture","title":{"pl":"Jak jest zbudowana aplikacja?","ru":"Как устроено приложение?","en":"How the app is structured","uk":"Як побудований застосунок?"},"basic":{"pl":"Ekrany modułów, lokalne parsowanie Excela, obliczenia i eksport tworzą jeden przepływ danych.","ru":"Экраны модулей, локальная обработка Excel, расчёты и экспорт составляют единый рабочий процесс.","en":"Module screens, local Excel parsing, calculations and exports form the processing flow.","uk":"Екрани модулів, локальна обробка Excel, обчислення й експорт формують єдиний процес."},"tech":{"pl":"index.html ładuje interfejs; js/app.js zawiera logikę ekranów i obliczeń; js/workers/ przetwarza wybrane pliki poza głównym wątkiem; sw.js zarządza cache PWA. MR. BOT ma osobne pliki js/mrbot.js i js/mrbot-knowledge.js.","ru":"index.html загружает интерфейс; js/app.js содержит логику экранов и расчёты; js/workers/ обрабатывает часть файлов вне основного потока; sw.js управляет кешем PWA. MR. BOT реализован отдельно в js/mrbot.js и js/mrbot-knowledge.js.","en":"index.html loads the UI; js/app.js handles screens and calculations; js/workers/ parses selected files off the main thread; sw.js manages the PWA cache. MR. BOT uses js/mrbot.js and js/mrbot-knowledge.js.","uk":"index.html завантажує інтерфейс; js/app.js містить логіку екранів і розрахунків; js/workers/ обробляє частину файлів поза головним потоком; sw.js керує кешем PWA. MR. BOT має окремі файли."},"source":"index.html; js/app.js; js/workers/; sw.js","related":[]},{"id":"privacy","title":{"pl":"Dane i prywatność","ru":"Данные и приватность","en":"Data and privacy","uk":"Дані та приватність"},"basic":{"pl":"Raporty są przetwarzane lokalnie na urządzeniu. Aplikacja nie wymaga konta ani wysyłania raportów do serwera.","ru":"Отчёты обрабатываются локально. Аккаунт и загрузка отчётов на сервер приложения не требуются.","en":"Reports are processed locally; no account or report upload to an application server is required.","uk":"Звіти обробляються локально; обліковий запис і завантаження звітів на сервер не потрібні."},"tech":{"pl":"PWA pobiera kod i aktualizacje przez sieć, ale przetwarzanie plików odbywa się w przeglądarce. Przed udostępnieniem eksportu sprawdź, czy nie zawiera danych operacyjnych.","ru":"PWA получает код и обновления через интернет, но Excel обрабатывается в браузере. Перед передачей экспорта проверь, нет ли в нём рабочих данных.","en":"PWA downloads code and updates over the network, but Excel processing occurs in the browser. Review exported files before sharing operational data.","uk":"PWA завантажує код та оновлення з мережі, але Excel обробляється у браузері. Перевіряйте експорт перед передаванням."},"source":"README.pl.md: Co to jest; sw.js","related":[{"category":"rights","topic":"privacy"}]}]},{"id":"start","emoji":"🚀","title":{"pl":"Pierwsze kroki","ru":"Начало работы","en":"Getting started","uk":"Початок роботи"},"topics":[{"id":"flow","title":{"pl":"Jak pracować z raportami","ru":"Как работать с отчётами","en":"How reports work","uk":"Як працювати зі звітами"},"basic":{"pl":"Wybierz moduł → wczytaj odpowiedni plik Excel → poczekaj na przetworzenie → ustaw filtry → sprawdź wyniki → skopiuj lub wyeksportuj, jeśli moduł to obsługuje.\n\nPo ponownym uruchomieniu aplikacji sprawdź przywracanie Excel na stronie głównej → „Zapisane w przeglądarce” → „Szczegóły”.","ru":"Выбери модуль → загрузи нужный Excel → дождись обработки → настрой фильтры → изучи результаты → скопируй или экспортируй, если модуль это поддерживает.\n\nПосле повторного открытия приложения проверь восстановление Excel на главной → «Сохранено в браузере» → «Подробнее».","en":"Choose a module → load its Excel report → wait for processing → apply filters → inspect results → copy/export when available.\n\nAfter reopening the app, check restored Excel files under Home → “Saved in browser” → “Details”.","uk":"Оберіть модуль → завантажте Excel → дочекайтеся обробки → налаштуйте фільтри → перегляньте результати → скопіюйте/експортуйте, якщо доступно.\n\nПісля повторного відкриття застосунку перевір відновлення Excel на головній → «Збережено в браузері» → «Докладніше»."},"tech":{"pl":"Nie ma jednego uniwersalnego schematu Excel. Każdy moduł ma osobny parser i oczekuje konkretnych nagłówków. Wyniki mogą zależeć od zaznaczonych grup, operatorów i parametrów.","ru":"У каждого модуля собственный парсер и ожидаемые колонки. Универсального Excel-формата нет. Результаты зависят от выбранных групп, операторов и параметров.","en":"Each module has its own parser and required headers. There is no universal Excel layout. Group, operator and parameter filters can change results.","uk":"Кожен модуль має власний парсер та очікувані стовпці. Єдиного формату Excel немає. Фільтри груп, операторів і параметрів змінюють результат."},"source":"js/workers/; js/app.js","related":[{"category":"openreports","topic":"overview"},{"category":"intelligence","topic":"overview"}]}]},{"id":"kpi","emoji":"📊","title":{"pl":"KPI · Normy i pracownicy","ru":"KPI · Нормы и сотрудники","en":"KPI · Norms and employees","uk":"KPI · Норми та працівники"},"topics":[{"id":"source","title":{"pl":"Źródła KPI","ru":"Откуда берутся KPI","en":"KPI input columns","uk":"Звідки беруться KPI"},"basic":{"pl":"KPI czyta raporty Audyt, Scalanie, Rozkładanie i NADWE/VAS. Podstawowe pola to USER LOGIN, NUMBER OF ITEMS i liczba sztuk na godzinę.","ru":"KPI читает отчёты Audyt, Scalanie, Rozkładanie и NADWE/VAS. Основные поля: USER LOGIN, NUMBER OF ITEMS и производительность в штуках за час.","en":"KPI reads Audyt, Scalanie, Rozkładanie and NADWE/VAS reports. Core fields are USER LOGIN, NUMBER OF ITEMS and items per hour.","uk":"KPI читає звіти Audyt, Scalanie, Rozkładanie та NADWE/VAS. Основні поля: USER LOGIN, NUMBER OF ITEMS та одиниці за годину."},"tech":{"pl":"Parser szuka nagłówków w pierwszych 15 wierszach. Audyt odczytuje też INFO TIME i AUDIT PROCESS TIME. Scalanie ma własny wariant kolumny czasu. Rozkładanie dodatkowo odczytuje NOTICE; rekordy z NUMBER OF ITEMS = 0 są pomijane w tych trzech parserach.\n\nWorker KPI odczytuje pierwszy arkusz pliku XLSX. Rozpoznaje nagłówki w pierwszych 15 wierszach; Audyt, Scalanie i Rozkładanie wymagają sensownego dopasowania nazw kolumn. Gdy nie znajdzie pełnego układu, część pól może przyjąć wartość 0, więc brak wyników lub zera należy diagnozować po nagłówkach, a nie uznawać za brak pracy.","ru":"Парсер ищет заголовки среди первых 15 строк. Audyt дополнительно читает INFO TIME и AUDIT PROCESS TIME. У Scalanie свои варианты колонки времени. Rozkładanie читает NOTICE; строки с NUMBER OF ITEMS = 0 эти три парсера пропускают.\n\nKPI Worker читает первый лист загруженного XLSX. Заголовки ищет в первых 15 строках. Для Audyt, Scalanie и Rozkładanie важны названия столбцов; если нужные поля не сопоставлены, отдельные числовые значения могут стать 0. Нулевой результат сам по себе не доказывает отсутствие работы.","en":"Headers are searched within the first 15 rows. Audyt also reads INFO TIME and AUDIT PROCESS TIME. Scalanie accepts its own time-header variants. Rozkładanie reads NOTICE. These three parsers skip rows where NUMBER OF ITEMS = 0.\n\nThe KPI worker processes the first worksheet of the uploaded XLSX and searches the first 15 rows for headers. Audyt, Scalanie and Rozkładanie rely on matching column names. If an expected column is missing, a numeric value may be parsed as zero; zeros alone do not prove that no work was performed.","uk":"Заголовки шукаються в перших 15 рядках. Audyt також читає INFO TIME та AUDIT PROCESS TIME. Scalanie має власні назви часу. Rozkładanie читає NOTICE. Три парсери пропускають NUMBER OF ITEMS = 0.\n\nKPI Worker читає перший аркуш завантаженого XLSX і шукає заголовки серед перших 15 рядків. Audyt, Scalanie та Rozkładanie залежать від назв стовпців. Якщо потрібний стовпець не знайдено, числове значення може стати нулем; нулі самі по собі не доводять відсутності роботи."},"source":"js/workers/kpi.js: findHeaderRow, parseAudit, parseScalanie, parseRozkladanie","related":[{"category":"openreports","topic":"use"},{"category":"kpi","topic":"audit-detail"},{"category":"kpi","topic":"scalanie-detail"},{"category":"kpi","topic":"rozk-detail"}]},{"id":"rates","title":{"pl":"Norma i wydajność","ru":"Норма и производительность","en":"Norms and performance","uk":"Норма та продуктивність"},"basic":{"pl":"Wydajność pojedynczego rekordu jest odczytywana z kolumny NUMBER OF ITEMS PER HOUR. Porównanie z ustawioną normą określa, czy rekord jest w normie.","ru":"Производительность записи берётся из NUMBER OF ITEMS PER HOUR. Приложение сравнивает её с установленной нормой и определяет, выполнена ли норма.","en":"Per-record productivity comes from NUMBER OF ITEMS PER HOUR. The configured threshold decides whether the record meets the norm.","uk":"Продуктивність запису береться з NUMBER OF ITEMS PER HOUR. Порівняння з установленою нормою визначає результат."},"tech":{"pl":"Warunek filtra „W normie”: perHour ≥ normThreshold. „Poniżej”: perHour < normThreshold. Mediana sortuje wartości perHour i bierze środkową (dla parzystej liczby średnią dwóch środkowych). Uwaga: perHour jest wartością z raportu, a nie zawsze wynikiem ponownego dzielenia items/time.\n\nW statystykach „W normie” to liczba rekordów z perHour ≥ próg, a „Poniżej” z perHour < próg. Efektywność = rekordy w normie / wszystkie rekordy objęte danym podsumowaniem × 100. Nie jest to procent przepracowanych godzin ani udział unikatowych pracowników. Progi Audyt, Scalanie, Rozkładanie i NADWE/VAS zapisują się oddzielnie w lokalnych ustawieniach przeglądarki.","ru":"Фильтр «В норме»: perHour ≥ normThreshold; «Ниже»: perHour < normThreshold. Медиана: сортировка perHour, центральное значение либо среднее двух центральных. Важно: perHour берётся из исходного отчёта, а не обязательно заново вычисляется как items/time.\n\nВ статистике «В норме» означает число записей с perHour ≥ порога, «Ниже нормы» с perHour < порога. Эффективность = записи в норме / все записи выбранной статистики × 100. Это не доля отработанных часов и не обязательно доля уникальных сотрудников. Пороги Audyt, Scalanie, Rozkładanie и NADWE/VAS сохраняются раздельно в локальных настройках браузера.","en":"“Above norm” uses perHour ≥ normThreshold; “below” uses perHour < normThreshold. Median is the middle sorted perHour value (or the mean of two middle values). perHour is read from the source report rather than necessarily recomputed as items/time.\n\nIn summary statistics, “at target” counts records whose perHour ≥ threshold and “below” counts perHour < threshold. Efficiency = at-target records / all included records × 100. This is not a percentage of worked hours or necessarily a percentage of distinct employees. Audyt, Scalanie, Rozkładanie and NADWE/VAS thresholds are stored separately in local browser preferences.","uk":"«У нормі»: perHour ≥ normThreshold; «Нижче»: perHour < normThreshold. Медіана — центральне значення відсортованих perHour (або середнє двох центральних). perHour зчитується зі звіту.\n\nУ статистиці «У нормі» означає кількість записів із perHour ≥ порога, «Нижче» з perHour < порога. Ефективність = записи в нормі / усі записи вибраної статистики × 100. Це не частка відпрацьованих годин і не обов’язково частка унікальних працівників. Пороги Audyt, Scalanie, Rozkładanie і NADWE/VAS зберігаються окремо в локальних налаштуваннях браузера."},"source":"js/app.js: median, filterAndSort, calcStats; js/workers/kpi.js","related":[{"category":"intelligence","topic":"other"},{"category":"kpi","topic":"stats"},{"category":"kpi","topic":"filters"}]},{"id":"schedule","title":{"pl":"Grafik i filtry pracowników","ru":"График и фильтры сотрудников","en":"Schedule and staff filters","uk":"Графік і фільтри працівників"},"basic":{"pl":"Plik grafiku łączy login z firmą, grupą, autobusem i zmianą. Na tej podstawie można filtrować wyniki KPI.","ru":"Файл графика связывает логин с фирмой, группой, автобусом и сменой. Эти сведения используются в фильтрах KPI.","en":"The staff schedule maps logins to company, group, bus and shift for KPI filtering.","uk":"Файл графіка пов’язує логін із компанією, групою, автобусом та зміною для фільтрів KPI."},"tech":{"pl":"Parser odczytuje arkusze BRYGADZISTA, DODATKOWE, SPM, PL i UKR procesy. Szuka wiersza z PDXXXXX w kolumnie A; następnie A=login, B=firma, C=grupa, D=autobus. Mapowanie w aktualnym kodzie: A/B/1 → AB; C/D/2 → CD. Końcowy token A/B/C/D/1/2 jest usuwany z nazwy grupy przy tworzeniu pola proces.","ru":"Читаются листы BRYGADZISTA, DODATKOWE, SPM, PL, UKR procesy. Строка заголовка определяется по PDXXXXX в A; далее A=login, B=firma, C=grupa, D=autobus. Текущее соответствие в коде: A/B/1 → AB, C/D/2 → CD. При формировании proces конечный токен A/B/C/D/1/2 удаляется из названия группы.","en":"Reads sheets BRYGADZISTA, DODATKOWE, SPM, PL and UKR procesy. Header: PDXXXXX in column A; then A=login, B=company, C=group, D=bus. Current code maps A/B/1 → AB and C/D/2 → CD. A trailing A/B/C/D/1/2 token is removed when deriving process.","uk":"Читаються аркуші BRYGADZISTA, DODATKOWE, SPM, PL, UKR procesy. Заголовок PDXXXXX у A; далі A=login, B=firma, C=grupa, D=autobus. Поточне зіставлення: A/B/1 → AB; C/D/2 → CD. Кінцевий токен A/B/C/D/1/2 видаляється з proces."},"source":"js/workers/pracownicy.js: SHEETS_TO_READ, BUS_TO_SHIFT, parsePracownicySheet","related":[]},{"id":"nadwe","title":{"pl":"NADWE / VAS","ru":"NADWE / VAS","en":"NADWE / VAS","uk":"NADWE / VAS"},"basic":{"pl":"Raport zawiera osobne wartości NADWE i VAS; ten sam login może mieć dwie pozycje w normach i jeden wspólny wiersz w podsumowaniu.","ru":"В отчёте отдельные показатели NADWE и VAS; у одного логина могут быть две строки в нормах и одна объединённая строка в сводке.","en":"NADWE and VAS are separate activities; a login may have two norm records but one combined summary row.","uk":"NADWE та VAS — окремі процеси; логін може мати два записи норм і один підсумковий рядок."},"tech":{"pl":"Parser znajduje USER LOGIN w kolumnie A. Odczytuje NADWE items z B, VAS items z C, czasy z D/E i perHour z K/L (indeksy 10/11). Wiersz NADWE powstaje, gdy nadweItems > 0 lub nadwePerH > 0; analogicznie VAS. W podsumowaniu są NUMBER OF ITEMS, TOTAL TIME IN THE MASK [H] i ITEMS PER HOUR oddzielnie dla obu procesów.","ru":"Парсер ищет USER LOGIN в A. NADWE items из B, VAS items из C, время из D/E, perHour из K/L (индексы 10/11). Запись NADWE создаётся при items > 0 или perHour > 0; для VAS аналогично. Сводка показывает NUMBER OF ITEMS, TOTAL TIME IN THE MASK [H] и ITEMS PER HOUR по обоим процессам.","en":"Looks for USER LOGIN in column A. NADWE items=B, VAS items=C, times=D/E, perHour=K/L (indices 10/11). A process record is created if its items > 0 or perHour > 0. Summary columns include NUMBER OF ITEMS, TOTAL TIME IN THE MASK [H], ITEMS PER HOUR per process.","uk":"Шукає USER LOGIN у A. NADWE items=B, VAS items=C, час=D/E, perHour=K/L (індекси 10/11). Запис створюється, якщо items > 0 або perHour > 0. Підсумок показує кількість, час та продуктивність для обох процесів."},"source":"js/workers/kpi.js: parseNadweVas; js/app.js: KPI NADWE/VAS","related":[{"category":"intelligence","topic":"other"},{"category":"kpi","topic":"exports"}]},{"id":"employees","title":{"pl":"Pracownicy i szkolenia","ru":"Сотрудники и обучение","en":"Employees and training","uk":"Працівники та навчання"},"basic":{"pl":"Zakładka Pracownicy korzysta ze wspólnego Grafiku i osobnego Rejestru szkoleń. Zawiera wyszukiwanie PD, bieżące szkolenia, historię i REZYGNACJE.","ru":"Вкладка Pracownicy использует общий график сотрудников и отдельный реестр обучения. Есть поиск по PD, текущие обучения, история и REZYGNACJE.","en":"Pracownicy uses the shared employee roster and a separate training register. It includes PD search, current training, history and resignations.","uk":"Pracownicy використовує спільний графік та окремий реєстр навчання: пошук PD, поточні навчання, історію й REZYGNACJE."},"tech":{"pl":"Grafik wczytuje się raz w KPI; Rejestr szkoleń osobno. Arkusz1 pokazuje bieżące wpisy; powtórki z historii są oznaczone do usunięcia z Arkusz1. Kliknięcie PD w KPI, STOCK lub Analiza przestojów otwiera wspólną kartę osoby, jeżeli da się ją odnaleźć. Pliki przechowuje przeglądarka.\n\nKarta pracownika zawiera zakładki Grafik i Procesy. Procesy służy wyłącznie do odczytu lokalnych przydziałów z Obsada; brak wpisów nie dowodzi nieobecności pracownika.","ru":"Grafik загружается в KPI один раз, Rejestr szkoleń отдельно. Arkusz1 содержит текущие записи; совпадения с историей помечаются для удаления из Arkusz1. Нажатие на PD в KPI, STOCK и Analiza przestojów открывает общую карточку, если данные найдены. Файлы хранятся в браузере.\n\nВ карточке сотрудника есть вкладки Grafik и Procesy. Procesy только читает доступные локальные назначения Obsada; отсутствие записей не доказывает отсутствие сотрудника на работе.","en":"Upload Grafik once in KPI and Rejestr szkoleń separately. Arkusz1 has current entries; records already in history are flagged for cleanup. Click a PD in KPI, STOCK or downtime analysis to open the shared employee profile where available. Browser storage keeps source files.\n\nThe employee card includes Grafik and Procesy tabs. Procesy is read-only and shows locally available Obsada assignments; an empty history is not proof of absence.","uk":"Grafik завантажується один раз у KPI, Rejestr szkoleń окремо. Arkusz1 містить поточні записи; дублікати з історії позначаються для прибирання. PD у KPI, STOCK та аналізі простоїв відкриває спільну картку, якщо працівника знайдено.\n\nУ картці працівника є Grafik і Procesy. Procesy лише читає доступні локальні призначення Obsada; відсутність записів не доводить відсутність працівника."},"source":"index.html: employee page and shared profile; js/app.js: pracownicy, employeeOpen","related":[{"category":"kpi","topic":"processes"}]},{"id":"calendar","title":{"pl":"Grafik pracownika i okres","ru":"Календарь сотрудника и период","en":"Employee calendar and period","uk":"Календар працівника й період"},"basic":{"pl":"W karcie pracownika otwórz Grafik, aby zobaczyć dni, oznaczenia i statystyki wybranego miesiąca.","ru":"В карточке сотрудника открой Grafik: там дни, обозначения и статистика выбранного месяца.","en":"Open Grafik in an employee profile to see the days, codes and summary for the selected month.","uk":"Відкрий Grafik у картці працівника для перегляду днів, кодів та статистики місяця."},"tech":{"pl":"Kolumna M oznacza dzień 1, następne kolumny kolejne dni. Ponieważ Excel nie podaje miesiąca, wybierz Okres grafiku w Pracownicy. W=wolne, U=urlop, L4 i 1L4=chorobowe (liczone razem), NN=nieusprawiedliwiona nieobecność, NUN=potwierdzona nieobecność bez przypisywania do U/L4. Kody zmian, np. I–XII, pozostają oryginalne. Wybrane 30-dniowe miesiące ukrywają 31. dzień i ostrzegają, jeśli zawiera dane.","ru":"M это 1-е число, следующие колонки соответствуют следующим дням. В Excel нет месяца, поэтому выбери «Период графика» во вкладке Pracownicy. W=выходной, U=отпуск, L4 и 1L4=больничный (в сумме вместе), NN=отсутствие без причины, NUN=подтверждённое отсутствие без автоматического отнесения к отпуску или больничному. Коды смен остаются исходными. Для 30-дневных месяцев 31-й день скрыт с предупреждением, если там есть данные.","en":"Column M is day 1; subsequent columns are consecutive days. The workbook has no month label: set Roster period in Pracownicy. W=day off, U=leave, L4/1L4=sick leave (counted together), NN=unexcused absence, NUN=confirmed absence (not automatically treated as leave or sickness). Shift codes remain unchanged. A 30-day month hides day 31 and warns if it contains data.","uk":"Стовпець M — день 1, наступні стовпці — наступні дні. Місяць у Excel не позначений: вибери період у Pracownicy. W=вихідний, U=відпустка, L4/1L4=лікарняний (разом у статистиці), NN=відсутність без причини, NUN=підтверджена відсутність без зарахування до відпустки чи лікарняного. Коди змін зберігаються. Для 30-денного місяця 31-й день прихований із попередженням за наявності даних."},"source":"js/workers/pracownicy.js; js/app.js: employeeSchedule, pracownicySetPeriod; index.html: employee calendar","related":[{"category":"kpi","topic":"employees"},{"category":"kpi","topic":"processes"}]},{"id":"brand-alias","title":{"pl":"Marki KPI i numery PD","ru":"Бренды KPI и соответствия PD","en":"KPI brands and ID aliases","uk":"Бренди KPI та відповідності PD"},"basic":{"pl":"Filtr marek SINSAY/MOHITO działa w normach KPI. Dla loginów PM/SPM marka to MOHITO, a numer 36 zależy od dokładnego dopasowania w bazie pracowników MOHITO. Nie utożsamiaj „brak w grafiku” z nieznaną marką.","ru":"Фильтр брендов SINSAY/MOHITO работает в KPI. Логины PM/SPM относятся к MOHITO, а бренд номера 36 определяется точным совпадением с базой MOHITO. Отсутствие сотрудника в графике не означает, что бренд неизвестен.","en":"The SINSAY/MOHITO filter works in KPI norms. PM/SPM logins belong to MOHITO; the brand of a 36-number depends on an exact match in the MOHITO employee roster. Missing roster data does not mean the brand is unknown.","uk":"Фільтр брендів SINSAY/MOHITO працює в KPI. Логіни PM/SPM належать MOHITO, а бренд номера 36 визначається точним збігом у базі працівників MOHITO. Відсутність у графіку не означає невідомий бренд."},"tech":{"pl":"kpiIdentity usuwa spacje i normalizuje wielkość liter; SPD123 ma identyfikator kanoniczny PD123, a S36... przechodzi na 36... . PM/SPM z cyframi → MOHITO. Numer 36... → MOHITO tylko wtedy, gdy dokładnie ten numer jest w bazie MOHITO; w pozostałych przypadkach domyślnie SINSAY. Identyfikator źródłowy w raporcie nie jest nadpisywany. Dopasowanie osoby i filtrowanie marek to dwa odrębne mechanizmy.","ru":"kpiIdentity убирает пробелы и приводит регистр; SPD123 сопоставляется с каноническим PD123, S36... с 36... . PM/SPM с цифрами → MOHITO. Номер 36... → MOHITO только при точном наличии номера в базе MOHITO, иначе по умолчанию SINSAY. Исходный логин отчёта не переписывается. Сопоставление сотрудника и определение бренда — разные операции.","en":"kpiIdentity strips whitespace and normalizes case; SPD123 has canonical ID PD123 and S36... canonicalizes to 36... . Numeric PM/SPM logins → MOHITO. A 36... login → MOHITO only when the exact number is present in the MOHITO roster, otherwise SINSAY by default. The source report login is preserved. Employee lookup and brand classification are distinct mechanisms.","uk":"kpiIdentity видаляє пробіли та нормалізує регістр; SPD123 має канонічний PD123, а S36... переходить у 36... . PM/SPM із цифрами → MOHITO. Номер 36... → MOHITO лише за точного збігу в базі MOHITO, інакше типово SINSAY. Початковий логін звіту не змінюється. Пошук працівника й визначення бренду — різні операції."},"source":"js/app.js: KPI brand selection and employee aliases; index.html: KPI brand badges","related":[{"category":"kpi","topic":"id-alias"},{"category":"kpi","topic":"processes"},{"category":"kpi","topic":"filters"}]},{"id":"two-rosters","title":{"pl":"Dwa grafiki: SINSAY i MOHITO","ru":"Два графика: SINSAY и MOHITO","en":"Two rosters: SINSAY and MOHITO","uk":"Два графіки: SINSAY і MOHITO"},"basic":{"pl":"KPI ma osobne bazy grafików pracowników dla SINSAY i MOHITO.","ru":"В KPI две отдельные базы графиков: SINSAY и MOHITO.","en":"KPI has separate employee roster uploads for SINSAY and MOHITO.","uk":"У KPI окремі бази графіків SINSAY та MOHITO."},"tech":{"pl":"Wczytaj grafik do właściwego pola bazy pracowników. Grafik SINSAY zawiera także zakładkę REZYGNACJE, gdzie mogą figurować osoby MOHITO (rozpoznawane po lokalizacji). Zakładka Powrót do pracy nie służy do zbierania aktywnych pracowników. Skojarzenie pracownika i jego marka pozostają widoczne również przy filtrach.","ru":"Загружай каждый график в свою зону. В SINSAY есть лист REZYGNACJE: там могут быть уволенные сотрудники MOHITO, их определяют по локации. Лист Powrót do pracy не используется как список работающих. Марка сотрудника сохраняется в карточке при фильтрации.","en":"Upload each roster to its matching SINSAY/MOHITO field. SINSAY REZYGNACJE can also include resigned MOHITO employees identified by location. Powrót do pracy is not used as an active roster. Employee brand is preserved on cards and under filters.","uk":"Завантаж кожен графік у відповідне поле SINSAY/MOHITO. У SINSAY REZYGNACJE можуть бути й звільнені працівники MOHITO (за локацією). Powrót do pracy не використовується як список активних працівників. Бренд залишається в картці та під фільтрами."},"source":"js/app.js: pracownicy, pracownicyMohito; js/workers/pracownicy.js","related":[]},{"id":"id-alias","title":{"pl":"PD, PM i 36: dopasowywanie pracownika","ru":"PD, PM и 36: сопоставление сотрудника","en":"PD, PM and 36: matching employees","uk":"PD, PM та 36: зіставлення працівника"},"basic":{"pl":"Identyfikator osoby może mieć inną postać w grafiku i raporcie KPI.","ru":"Идентификатор сотрудника может отличаться между графиком и KPI-отчётом.","en":"Employee IDs can be represented differently in the roster and KPI report.","uk":"Ідентифікатор працівника може мати різний вигляд у графіку та KPI."},"tech":{"pl":"W grafiku MOHITO identyfikator PD z odpowiedniego źródła może odpowiadać PM w wynikach KPI. Identyfikatory zaczynające się od 36 są osobną grupą i nie powinny być automatycznie traktowane jak PM. Jeśli brakuje danych pracownika, sprawdź źródło grafiku, markę oraz pełny login, nie dopisuj ręcznie innej osoby.\n\nW widoku Procesy dla MOHITO możliwe jest dopasowanie PM/SPM do odpowiedniego PD; nie oznacza to zmiany wszystkich loginów PD na MOHITO. Wielkość liter i zbędne spacje nie wpływają na porównanie. Źródłowe godziny pozostają bez zmian.","ru":"Для MOHITO идентификатор PD из графика может соответствовать PM в KPI. Логины, начинающиеся с 36, относятся к отдельной группе, их нельзя автоматически считать PM. Если карточка не нашла сотрудника, проверь марку, исходный график и полный логин.\n\nВо вкладке Procesy для MOHITO возможна связка PM/SPM с соответствующим PD; это не превращает все PD в MOHITO. При сравнении игнорируются регистр и лишние пробелы. Исходные часы не переписываются.","en":"In MOHITO, a PD identifier in the roster may correspond to a PM identifier in KPI. IDs beginning with 36 are separate and must not be treated as PM automatically. If a card lacks employee details, check brand, roster source and full login.\n\nFor MOHITO, Procesy can match PM/SPM with the corresponding PD alias; it does not reclassify all PD as MOHITO. Case and extra spaces are ignored. Source hour records are unchanged.","uk":"У MOHITO ідентифікатор PD у графіку може відповідати PM у KPI. Логіни з 36 належать до окремої групи, їх не слід автоматично вважати PM. Якщо картка не знайшла дані, перевір бренд, графік і повний логін.\n\nДля MOHITO у Procesy можна зіставити PM/SPM з відповідним PD, але не всі PD стають MOHITO. Регістр і зайві пробіли ігноруються. Початкові погодинні записи не змінюються."},"source":"js/app.js: employee identity normalization, brand resolution","related":[{"category":"kpi","topic":"processes"}]},{"id":"employee-cards","title":{"pl":"Karty pracowników, szkolenia i powroty","ru":"Карточки сотрудников, обучение и возвращение","en":"Employee cards, training and returning workers","uk":"Картки працівників, навчання та повернення"},"basic":{"pl":"Kliknięcie identyfikatora pracownika w KPI otwiera jego kartę z dostępnymi danymi i szkoleniami. Dostępne są również zakładki Grafik i Procesy.","ru":"Нажатие на логин в KPI открывает карточку сотрудника с данными и обучением. Также доступны вкладки Grafik и Procesy.","en":"Select an employee ID in KPI to open the card with available profile and training details. Grafik and Procesy tabs are also available.","uk":"Натисни логін у KPI, щоб відкрити картку з даними та навчанням. Також доступні вкладки Grafik і Procesy."},"tech":{"pl":"Karta łączy dostępne dane grafiku, historię szkoleń z Rejestr szkoleń oraz wpisy REZYGNACJE. Osoba mogła odejść i wrócić: w takim przypadku aktualny grafik jest ważniejszy niż sam dawny wpis o odejściu. Dla osoby niewystępującej w aktywnym grafiku pokazuj tylko dane rzeczywiście dostępne w archiwum; nie zgaduj zmiany.","ru":"Карточка объединяет график, Rejestr szkoleń и REZYGNACJE. Сотрудник мог уволиться и вернуться: тогда актуальный график важнее старой записи об увольнении. Для сотрудника без текущего графика показываются только известные данные; смену нельзя угадывать.","en":"Cards combine available roster, training register and REZYGNACJE history. Workers may resign and return; the current roster should take precedence over an old resignation. For workers without an active roster, show only fields available in the archive and do not invent a shift.","uk":"Картка поєднує графік, реєстр навчань та REZYGNACJE. Працівник міг звільнитися та повернутися; актуальний графік важливіший за старий запис. Якщо активного графіка немає, показуй лише відомі дані без вигаданої зміни."},"source":"js/app.js: employee card, training register, resignation records","related":[{"category":"kpi","topic":"processes"}]},{"id":"processes","title":{"pl":"Procesy pracownika · przydziały i kalendarz","ru":"Procesy сотрудника · назначения и календарь","en":"Employee Procesy · assignments and calendar","uk":"Procesy працівника · призначення й календар"},"basic":{"pl":"Procesy pokazuje ostatni, obecny i kolejny przydział oraz godzinowe przedziały z nazwą procesu. Można przechodzić po dniach i wybierać dzień w kalendarzu.","ru":"Procesy показывает предыдущее, текущее и следующее назначение, интервалы с названием процесса. Можно листать дни и переходить через календарь.","en":"Procesy shows previous, current and next assignments plus process-labelled time intervals. Browse dates and choose a calendar day.","uk":"Procesy показує попереднє, поточне й наступне призначення та часові інтервали процесів. Переглядай дні й обирай календарну дату."},"tech":{"pl":"Sąsiadujące godzinne sloty tego samego procesu i zmiany łączą się w jeden przedział. Dzień po północy może pokazywać fragment zmiany rozpoczętej poprzedniego dnia z odpowiednią adnotacją. Znaczniki planned / current / elapsed wynikają z zegara, a nie z potwierdzenia obecności. Widok niczego nie zapisuje w Obsada.","ru":"Соседние часы одного процесса в одной смене объединяются в интервал. После полуночи может отображаться часть смены прошлого дня с пометкой. planned / current / elapsed рассчитываются по текущему времени и не доказывают присутствие. Просмотр не записывает данные в Obsada.","en":"Adjacent hourly slots with the same process and shift merge into one interval. After midnight a segment from the previous day’s shift can appear with an annotation. planned / current / elapsed are clock-based, not proof of attendance. This view does not write to Obsada.","uk":"Суміжні години того самого процесу й зміни об’єднуються в інтервал. Після півночі може бути частина зміни попереднього дня з позначкою. planned / current / elapsed визначаються часом, не підтвердженням присутності. Цей екран не змінює Obsada."},"related":[{"category":"obsada","topic":"planning"},{"category":"obsada","topic":"automatic"},{"category":"kpi","topic":"calendar"}],"sources":["js/employee-processes.js","index.html"]},{"id":"audit-detail","title":{"pl":"Audyt KPI · pola i INFO","ru":"KPI Audyt · показатели и INFO","en":"KPI Audit · metrics and INFO","uk":"KPI Audyt · показники та INFO"},"basic":{"pl":"Raport Audyt pokazuje liczbę sztuk, czas procesu, wydajność i dwa dodatkowe pola: INFO TIME oraz AUDIT PROCESS TIME.","ru":"В KPI Audyt отображаются количество товаров, время процесса, производительность и два дополнительных показателя: INFO TIME и AUDIT PROCESS TIME.","en":"KPI Audit includes items, process time, items per hour, plus INFO TIME and AUDIT PROCESS TIME.","uk":"KPI Audyt показує кількість одиниць, час процесу, продуктивність та додаткові INFO TIME й AUDIT PROCESS TIME."},"tech":{"pl":"Używany jest pierwszy arkusz XLSX. Worker wyszukuje USER LOGIN, NUMBER OF ITEMS, NUMBER OF ITEMS PER HOUR oraz warianty TOTAL TIME IN THE PROCESS (A+I), INFO TIME (A+I) i AUDIT PROCESS TIME. Wiersze z NUMBER OF ITEMS równym 0 są pomijane. INFO TIME i AUDIT PROCESS TIME są wartościami z raportu; KPI nie odtwarza ich niezależnie. Status normy porównuje NUMBER OF ITEMS PER HOUR z aktualnym progiem Audyt. Eksport Audyt Norms zachowuje obydwie kolumny czasu szczegółowego.","ru":"Используется первый лист XLSX. Worker ищет USER LOGIN, NUMBER OF ITEMS, NUMBER OF ITEMS PER HOUR, варианты TOTAL TIME IN THE PROCESS (A+I), INFO TIME (A+I) и AUDIT PROCESS TIME. Строки с NUMBER OF ITEMS = 0 пропускаются. INFO TIME и AUDIT PROCESS TIME считываются из отчёта, а не вычисляются ботом. Статус нормы сравнивает NUMBER OF ITEMS PER HOUR с порогом Audyt. В экспорте Audit Norms оба дополнительных столбца сохраняются.","en":"The worker reads the first XLSX sheet, matching USER LOGIN, NUMBER OF ITEMS, NUMBER OF ITEMS PER HOUR, TOTAL TIME IN THE PROCESS (A+I) variants, INFO TIME (A+I), and AUDIT PROCESS TIME. Rows with NUMBER OF ITEMS = 0 are skipped. The two detailed time fields are read from the source rather than independently reconstructed. At-target status compares source per-hour with the Audyt threshold. Audit Norms export includes both detailed time fields.","uk":"Worker читає перший аркуш XLSX і шукає USER LOGIN, NUMBER OF ITEMS, NUMBER OF ITEMS PER HOUR, варіанти TOTAL TIME IN THE PROCESS (A+I), INFO TIME (A+I) та AUDIT PROCESS TIME. Рядки з NUMBER OF ITEMS = 0 пропускаються. Додаткові часові поля беруться зі звіту, а не обчислюються ботом. Статус норми порівнює per-hour із порогом Audyt. Експорт Audit Norms містить обидва часові поля."},"related":[{"category":"kpi","topic":"source"},{"category":"kpi","topic":"rates"},{"category":"kpi","topic":"exports"}],"sources":["js/workers/kpi.js: parseAudit","js/app.js: kpiExportAudit, calcStats"]},{"id":"scalanie-detail","title":{"pl":"Scalanie KPI · dane i norma","ru":"KPI Scalanie · данные и норма","en":"KPI Scalanie · source and target","uk":"KPI Scalanie · дані та норма"},"basic":{"pl":"KPI Scalanie analizuje osobny raport Pick/Scalanie i porównuje źródłowe sztuki na godzinę z progiem dla Scalanie.","ru":"KPI Scalanie использует отдельный отчёт Pick/Scalanie и сравнивает исходную производительность с собственной нормой Scalanie.","en":"KPI Scalanie analyzes its separate Pick/Scalanie report and compares source items per hour against the Scalanie threshold.","uk":"KPI Scalanie аналізує окремий звіт Pick/Scalanie та порівнює вихідні одиниці за годину з власним порогом Scalanie."},"tech":{"pl":"Worker szuka USER LOGIN, NUMBER OF ITEMS, NUMBER OF ITEMS PER HOUR i wariantów TOTAL TIME IN PROCESS / TOTAL TIME IN THE PROCESS. Rekord z zerową liczbą sztuk jest pomijany. INFO TIME i AUDIT PROCESS TIME są ustawiane na 0, bo nie są metrykami tego parsera. Wydajność pochodzi bezpośrednio z NUMBER OF ITEMS PER HOUR, nie jest przeliczana z zaokrąglonego czasu. Filtry marek, zmian, agencji i procesów wpływają na listę i statystyki Scalanie.","ru":"Worker ищет USER LOGIN, NUMBER OF ITEMS, NUMBER OF ITEMS PER HOUR и варианты TOTAL TIME IN PROCESS / TOTAL TIME IN THE PROCESS. Записи с нулевым количеством пропускаются. INFO TIME и AUDIT PROCESS TIME здесь не рассчитываются и имеют значение 0. Производительность берётся из NUMBER OF ITEMS PER HOUR, а не из округлённого времени. Фильтры бренда, смены, агентства и процесса влияют на результаты и статистику Scalanie.","en":"The worker matches USER LOGIN, NUMBER OF ITEMS, NUMBER OF ITEMS PER HOUR and TOTAL TIME IN PROCESS / TOTAL TIME IN THE PROCESS variants. Zero-item rows are omitted. INFO TIME and AUDIT PROCESS TIME default to 0 because this parser does not extract them. Performance is the source per-hour value, not recomputed from rounded time. Brand, shift, agency and process filters determine the shown Scalanie results and summaries.","uk":"Worker шукає USER LOGIN, NUMBER OF ITEMS, NUMBER OF ITEMS PER HOUR та варіанти TOTAL TIME IN PROCESS / TOTAL TIME IN THE PROCESS. Рядки з нульовою кількістю пропускаються. INFO TIME і AUDIT PROCESS TIME у цьому парсері мають 0. Продуктивність береться з NUMBER OF ITEMS PER HOUR, а не рахується за округленим часом. Фільтри бренду, зміни, агенції й процесу впливають на результати Scalanie."},"related":[{"category":"kpi","topic":"source"},{"category":"kpi","topic":"rates"},{"category":"kpi","topic":"filters"}],"sources":["js/workers/kpi.js: parseScalanie","js/app.js: kpiScalanieFilteredByGroup, kpiExportScalanie"]},{"id":"rozk-detail","title":{"pl":"Rozkładanie KPI · NOTICE i rodzaje","ru":"KPI Rozkładanie · NOTICE и типы","en":"KPI Rozkładanie · NOTICE types","uk":"KPI Rozkładanie · NOTICE і типи"},"basic":{"pl":"W Rozkładanie o tym, czy wiersz trafi do wyników, decyduje m.in. wartość NOTICE: SCAL RSORT, NADWE RSORT lub B2B RETURNS RSORT.","ru":"В Rozkładanie попадание строки в результаты зависит в том числе от NOTICE: SCAL RSORT, NADWE RSORT или B2B RETURNS RSORT.","en":"In Rozkładanie, NOTICE influences whether a row is included: SCAL RSORT, NADWE RSORT, or B2B RETURNS RSORT.","uk":"У Rozkładanie потрапляння рядка до результатів залежить, зокрема, від NOTICE: SCAL RSORT, NADWE RSORT або B2B RETURNS RSORT."},"tech":{"pl":"Worker normalizuje wielkość liter, spacje, podkreślenia i myślniki w NOTICE. SCAL RSORT → rodzaj SCAL (wewnętrznie null), NADWE RSORT → RSORT, B2B RETURNS RSORT → Zwroty. Inne NOTICE są pomijane, tak samo rekordy z NUMBER OF ITEMS = 0. Selektor rodzajów SCAL/RSORT/Zwroty filtruje wyniki. W RAPORCIE ZBIORCZYM KPI sekcja ROZKŁADANIE obejmuje wyłącznie rodzaj SCAL; pozostałe rodzaje nie są w niej automatycznie sumowane.","ru":"Worker нормализует регистр, пробелы, подчёркивания и дефисы в NOTICE. SCAL RSORT → тип SCAL (внутри null), NADWE RSORT → RSORT, B2B RETURNS RSORT → Zwroty. Другие NOTICE игнорируются, как и строки с NUMBER OF ITEMS = 0. Фильтр SCAL/RSORT/Zwroty влияет на показанные результаты. В общем RAPORT ZBIORCZY KPI секция ROZKŁADANIE содержит только SCAL, а не все три типа. Это важно при сравнении выгрузок.","en":"The worker normalizes case, spaces, underscores and hyphens in NOTICE. SCAL RSORT → SCAL type (stored as null), NADWE RSORT → RSORT, B2B RETURNS RSORT → Zwroty. Other NOTICE values and NUMBER OF ITEMS = 0 rows are excluded. The SCAL/RSORT/Zwroty selector filters results. In the KPI aggregate report, the ROZKŁADANIE section includes SCAL only, not all three types; this explains differences between exports.","uk":"Worker нормалізує регістр, пробіли, підкреслення та дефіси у NOTICE. SCAL RSORT → SCAL (внутрішньо null), NADWE RSORT → RSORT, B2B RETURNS RSORT → Zwroty. Інші NOTICE й рядки з NUMBER OF ITEMS = 0 ігноруються. Перемикач SCAL/RSORT/Zwroty фільтрує результати. У зведеному RAPORT ZBIORCZY KPI секція ROZKŁADANIE охоплює лише SCAL, а не всі три види."},"related":[{"category":"kpi","topic":"source"},{"category":"kpi","topic":"filters"},{"category":"kpi","topic":"exports"}],"sources":["js/workers/kpi.js: detectRodzaj, parseRozkladanie","js/app.js: kpiRozkFilteredByGroup, kpiExportGlobalXlsx"]},{"id":"filters","title":{"pl":"Filtry KPI · zmiany, procesy i marki","ru":"Фильтры KPI · смены, процессы и бренды","en":"KPI filters · shifts, processes and brands","uk":"Фільтри KPI · зміни, процеси й бренди"},"basic":{"pl":"Filtry ograniczają widoczne rekordy i powiązane statystyki. Najpierw sprawdź markę, zmianę, agencję/proces, rodzaj Rozkładanie oraz status normy.","ru":"Фильтры ограничивают видимые записи и связанные показатели. При пропаже результатов проверь бренд, смену, агентство/процесс, тип Rozkładanie и статус нормы.","en":"Filters narrow displayed records and their related statistics. Check brand, shift, agency/process, Rozkładanie type and at-target status when results disappear.","uk":"Фільтри обмежують показані записи й пов’язану статистику. Якщо результатів немає, перевір бренд, зміну, агенцію/процес, тип Rozkładanie та статус норми."},"tech":{"pl":"Status W normie: perHour ≥ próg; Poniżej: perHour < próg. Filtry zmian korzystają z przypisanej zmiany; rekord bez shift może wypaść przy wyborze tylko części zmian. Agencja i proces pochodzą z dopasowanej bazy pracowników (brak danych bywa opisany „Brak w grafiku”). Wybór marki jest niezależny od dopasowania danych kadrowych. W Rozkładanie dodatkowo filtruj SCAL/RSORT/Zwroty. Sortowanie zmienia kolejność, nie samo obliczenie. W licznikach i rankingach używane są rekordy już ograniczone odpowiednimi filtrami.","ru":"«В норме»: perHour ≥ порога, «Ниже»: perHour < порога. Фильтр смен работает по определённой смене; если у записи смена не определена, выбор части смен может скрыть её. Агентство и процесс приходят из сопоставленного графика (при отсутствии данных может показываться «Brak w grafiku»). Фильтр бренда работает независимо от успешности поиска карточки. Для Rozkładanie есть отдельный SCAL/RSORT/Zwroty. Сортировка меняет порядок, но не формулу. Статистика и рейтинги используют записи с применёнными фильтрами.","en":"At target: perHour ≥ threshold; below: perHour < threshold. Shift filtering uses the assigned shift; a row without a known shift may disappear when only some shifts are selected. Agency and process come from the matched employee roster (missing values may display as “Brak w grafiku”). Brand selection does not require a successful employee-card match. Rozkładanie also has SCAL/RSORT/Zwroty filtering. Sorting changes order, not the formula. Summaries and rankings use the appropriately filtered record sets.","uk":"«У нормі»: perHour ≥ порога, «Нижче»: perHour < порога. Фільтр змін використовує визначену зміну; запис без неї може зникнути, якщо вибрано лише частину змін. Агенція й процес надходять із графіка працівників (відсутні дані можуть показуватися як «Brak w grafiku»). Бренд визначається незалежно від картки працівника. У Rozkładanie є додатковий фільтр SCAL/RSORT/Zwroty. Сортування змінює порядок, а не формулу. Статистика й рейтинги враховують відповідно відфільтровані записи."},"related":[{"category":"kpi","topic":"brand-alias"},{"category":"kpi","topic":"rates"},{"category":"kpi","topic":"stats"},{"category":"kpi","topic":"rozk-detail"}],"sources":["js/app.js: filterByGroup, filterByAttr, kpiFilterBrand, filterAndSort, kpiRozkFilteredByGroup"]},{"id":"stats","title":{"pl":"Statystyki KPI · średnia, mediana i TOP","ru":"Статистика KPI · среднее, медиана и TOP","en":"KPI statistics · mean, median and TOP","uk":"Статистика KPI · середнє, медіана і TOP"},"basic":{"pl":"Statystyki liczą rekordy spełniające normę, średnią i medianę wydajności, sumy sztuk/czasu oraz rankingi TOP według wydajności i liczby sztuk.","ru":"Статистика считает записи в норме, среднюю и медианную производительность, сумму товаров/времени и TOP-рейтинги по производительности или количеству.","en":"KPI statistics calculate at-target records, average/median performance, item/time totals and TOP rankings by performance or item count.","uk":"Статистика KPI рахує записи в нормі, середню й медіану продуктивності, загальні кількість/час і TOP-рейтинги за швидкістю або кількістю."},"tech":{"pl":"calcStats: avg = suma wartości perHour / liczba rekordów; mediana = środkowy perHour po sortowaniu (dla parzystej liczby średnia dwóch środkowych); totalItems = suma items, totalTime = suma time. Efektywność = liczba rekordów z perHour ≥ norma / liczba rekordów × 100. TOP według normy sortuje perHour malejąco, TOP według sztuk sortuje items. Wybrana wielkość TOP dotyczy liczby rekordów, nie zawsze unikatowych osób. Osobne podsumowania NADWE i VAS są liczone po odfiltrowaniu ich rodzaju.","ru":"calcStats: средняя = сумма perHour / количество записей; медиана = центральное perHour после сортировки (при чётном количестве среднее двух центральных); totalItems и totalTime = суммы количества и времени. Эффективность = число записей с perHour ≥ нормы / число записей × 100. TOP по производительности сортируется по perHour, TOP по количеству по items. Рейтинг строится по записям, не обязательно по уникальным людям. NADWE и VAS получают отдельные сводки после фильтрации типа.","en":"calcStats: average = sum(perHour) / record count; median = the middle sorted perHour (or mean of the two middle values); totalItems and totalTime sum source items/time. Efficiency = records with perHour ≥ target / all included records × 100. The performance TOP ranks perHour, the item TOP ranks items. These are record rankings, not guaranteed unique-person rankings. NADWE and VAS summaries are calculated separately after splitting their types.","uk":"calcStats: середнє = сума perHour / кількість записів; медіана = центральне perHour після сортування (для парного числа середнє двох центральних); totalItems і totalTime = суми кількості та часу. Ефективність = записи з perHour ≥ норми / усі записи × 100. TOP продуктивності сортує за perHour, TOP кількості за items. Це рейтинг записів, не обов’язково унікальних людей. NADWE і VAS підсумовуються окремо за типом."},"related":[{"category":"kpi","topic":"rates"},{"category":"kpi","topic":"filters"},{"category":"kpi","topic":"exports"}],"sources":["js/app.js: calcStats, calcTopByNorm, calcTopByItems, median"]},{"id":"exports","title":{"pl":"Eksport KPI · raporty i zakres","ru":"Экспорт KPI · форматы и состав","en":"KPI exports · content and scope","uk":"Експорт KPI · склад і обсяг"},"basic":{"pl":"KPI ma eksporty dla Audyt, Scalanie, Rozkładanie, NADWE/VAS oraz raport zbiorczy. Nie wszystkie eksporty używają identycznego zestawu filtrów i typów.","ru":"В KPI есть выгрузки Audyt, Scalanie, Rozkładanie, NADWE/VAS и общий отчёт. Они отличаются набором столбцов, применёнными фильтрами и включёнными типами.","en":"KPI offers separate Audyt, Scalanie, Rozkładanie, NADWE/VAS exports plus an aggregate report. Their columns, applied filters and included types differ.","uk":"KPI має окремі експорти Audyt, Scalanie, Rozkładanie, NADWE/VAS та зведений звіт. Вони різняться стовпцями, фільтрами й типами записів."},"tech":{"pl":"Audyt / Scalanie / Rozkładanie eksportują aktualnie filtrowane i sortowane rekordy ze statusem oraz normą. Audyt dodaje INFO TIME i AUDIT PROCESS TIME; Rozkładanie dodaje RODZAJ. NADWE/VAS tworzy arkusz z jedną linią na login, kolumnami NADWE i VAS dla sztuk, czasu i wydajności. Raport zbiorczy wykorzystuje odpowiednie rekordy po filtrach grup/zmian/agencji/procesów/marek, ale nie jest tym samym co tabela po filtrze statusu; sekcja ROZKŁADANIE uwzględnia tylko SCAL. Sprawdź wybrany typ raportu przed porównywaniem sum.","ru":"В отдельных Excel-экспортах Audyt / Scalanie / Rozkładanie используются текущие отфильтрованные и отсортированные записи с нормой и статусом. Audyt добавляет INFO TIME и AUDIT PROCESS TIME, Rozkładanie добавляет RODZAJ. NADWE/VAS формирует одну строку на логин с парными столбцами NADWE и VAS для количества, времени и производительности. Общий отчёт использует записи после фильтров смен, брендов, агентств и процессов, но не обязательно повторяет фильтр статуса табличного списка; в секции ROZKŁADANIE только SCAL. При расхождении итогов сначала сравни область выгрузки.","en":"Individual Audyt / Scalanie / Rozkładanie XLSX exports use the currently filtered and sorted rows with norm/status. Audyt adds INFO TIME and AUDIT PROCESS TIME; Rozkładanie adds RODZAJ. NADWE/VAS produces one row per login with paired NADWE and VAS columns for items, time and per-hour. The aggregate report uses the group/shift/agency/process/brand-filtered records, but does not necessarily mirror the table status filter; its ROZKŁADANIE section contains SCAL only. Compare scope before comparing totals.","uk":"Окремі експорти Audyt / Scalanie / Rozkładanie використовують поточні відфільтровані й відсортовані записи зі статусом і нормою. Audyt додає INFO TIME та AUDIT PROCESS TIME, Rozkładanie додає RODZAJ. NADWE/VAS формує один рядок на логін із парами стовпців NADWE і VAS для кількості, часу й продуктивності. Зведений звіт бере записи після фільтрів змін, брендів, агенцій та процесів, але не обов’язково повторює фільтр статусу таблиці; у ROZKŁADANIE лише SCAL. Порівнюй однакові набори записів."},"related":[{"category":"kpi","topic":"source"},{"category":"kpi","topic":"rozk-detail"},{"category":"kpi","topic":"nadwe"},{"category":"kpi","topic":"stats"}],"sources":["js/app.js: kpiExportAudit, kpiExportScalanie, kpiExportRozk, kpiExportNv, kpiExportGlobalXlsx"]}]},{"id":"rs","emoji":"📦","title":{"pl":"RS · Tote Finder","ru":"RS · Tote Finder","en":"RS · Tote Finder","uk":"RS · Tote Finder"},"topics":[{"id":"mp","title":{"pl":"Baza MP: jakie kolumny?","ru":"База MP: какие колонки?","en":"MP database columns","uk":"База MP: які стовпці?"},"basic":{"pl":"MP dostarcza lokalizacje, EAN, ilości, ABC oraz opis techniczny produktu.","ru":"MP даёт локации, EAN, количества, ABC и техническое описание товара.","en":"MP supplies locations, EAN, quantities, ABC and technical descriptions.","uk":"MP надає локації, EAN, кількість, ABC і технічний опис."},"tech":{"pl":"Parser rozpoznaje m.in. LOCATION, LOCATION TYPE, LOCK_DESC, EAN, ABC, NO OF ITEMS, QTY AVAILABLE, QTY RESERVED i TECHNICAL DESCRIPTION. Rekord bez EAN jest pomijany. Ilości są konwertowane na liczby; brakujące QTY AVAILABLE / RESERVED pozostają null, a nie automatycznie zerem.","ru":"Парсер читает LOCATION, LOCATION TYPE, LOCK_DESC, EAN, ABC, NO OF ITEMS, QTY AVAILABLE, QTY RESERVED и TECHNICAL DESCRIPTION. Строка без EAN пропускается. Количества преобразуются в числа; отсутствующие QTY AVAILABLE / RESERVED остаются null, не нулём.","en":"Reads LOCATION, LOCATION TYPE, LOCK_DESC, EAN, ABC, NO OF ITEMS, QTY AVAILABLE, QTY RESERVED and TECHNICAL DESCRIPTION. Rows without EAN are skipped. Missing available/reserved quantities stay null rather than defaulting to zero.","uk":"Читає LOCATION, LOCATION TYPE, LOCK_DESC, EAN, ABC, NO OF ITEMS, QTY AVAILABLE, QTY RESERVED і TECHNICAL DESCRIPTION. Рядки без EAN пропускаються. Відсутні available/reserved залишаються null."},"source":"js/workers/tote.js: parseMP","related":[{"category":"rs","topic":"mp-eligibility"},{"category":"rs","topic":"lookup"}]},{"id":"rs","title":{"pl":"Baza RS: jakie kolumny?","ru":"База RS: какие колонки?","en":"RS database columns","uk":"База RS: які стовпці?"},"basic":{"pl":"RS dostarcza SKU code, Shelf type, Shelf code, Shelf bin i Inventory qty do wyszukiwania lokalizacji.","ru":"RS содержит SKU code, Shelf type, Shelf code, Shelf bin и Inventory qty для поиска локаций.","en":"RS supplies SKU code, Shelf type, Shelf code, Shelf bin and Inventory qty for location lookup.","uk":"RS містить SKU code, Shelf type, Shelf code, Shelf bin та Inventory qty для пошуку локацій."},"tech":{"pl":"Worker szuka arkusza z rozpoznawalnymi nagłówkami RS, przeglądając pierwsze 10 wierszy każdego arkusza. Wybiera pierwszy pasujący arkusz (niekoniecznie pierwszy w pliku). SKU code staje się kluczem EAN, Shelf bin jest pełną lokalizacją, Inventory qty liczbą. Wiersze bez SKU code są pomijane. Dla dużych arkuszy RS dostępna jest ścieżka strumieniowa; jeśli nie ma zgodnego arkusza, wyświetlany jest błąd.","ru":"Worker проверяет первые 10 строк каждого листа Excel и выбирает первый лист с узнаваемыми столбцами RS, а не обязательно первый лист книги. SKU code используется как EAN, Shelf bin как полная локация, Inventory qty как количество. Строки без SKU code пропускаются. Для очень больших RS доступна потоковая обработка; если подходящий лист не найден, показывается ошибка.","en":"The worker checks the first 10 rows of each workbook sheet and selects the first sheet with recognizable RS headings, not necessarily the first sheet. SKU code becomes EAN; Shelf bin is the full location; Inventory qty is the quantity. Blank SKU codes are skipped. Very large RS sheets can use a streaming path; a missing compatible sheet raises an error.","uk":"Worker перевіряє перші 10 рядків кожного аркуша Excel і вибирає перший із відповідними заголовками RS, не обов’язково перший аркуш книги. SKU code стає ключем EAN, Shelf bin є повною локацією, Inventory qty кількістю. Рядки без SKU code пропускаються. Для великих RS є потокова обробка; відсутність потрібного аркуша спричиняє помилку."},"source":"js/workers/tote.js: parseRS","related":[{"category":"rs","topic":"multi-tote"},{"category":"rs","topic":"manual-lookup"}]},{"id":"lookup","title":{"pl":"MP → RS: dopasowanie","ru":"MP → RS: сопоставление","en":"MP → RS matching","uk":"MP → RS: зіставлення"},"basic":{"pl":"Narzędzie zestawia EAN z bazy MP z kodami SKU bazy RS i pokazuje pasujące lokalizacje TOTE.","ru":"Инструмент сопоставляет EAN из MP с SKU code из RS и показывает подходящие TOTE-локации.","en":"Matches MP EAN to RS SKU code and presents candidate TOTE locations.","uk":"Зіставляє EAN з MP із SKU code в RS та показує можливі TOTE-локації."},"tech":{"pl":"Wejście MP i RS jest parsowane osobno. Kluczem porównania jest kod produktu (EAN/SKU code). Przy wyborze lokalizacji aplikacja uwzględnia własne ustawienia (np. strategię ilości, multi-tote i typ półki). Wynik zależy od załadowanych baz i aktywnych filtrów; nie jest osobną inwentaryzacją.\n\nW MP → RS wybierany jest tote o dolnej medianie Inventory qty po zastosowaniu filtrów; ręczny wybór strategii median/minimum jest dostępny tylko w wyszukiwaniu EAN. Zobacz też osobne instrukcje o kwalifikowaniu MP i statusach wyników.","ru":"MP и RS разбираются отдельно. Ключ сопоставления — код товара (EAN/SKU code). При выборе локации учитываются настройки количества, multi-tote и тип полки. Результат зависит от загруженных баз и фильтров; это не самостоятельная инвентаризация.\n\nВ MP → RS после фильтров выбирается TOTE с нижней медианой Inventory qty. Переключение «медиана/минимум» доступно только в ручном поиске EAN. Дополнительные правила допуска MP и статусы результата описаны в связанных статьях.","en":"MP and RS are parsed separately. Matching uses the product code (EAN/SKU code). Candidate selection is affected by quantity strategy, multi-tote handling and shelf-type settings. Results depend on the loaded databases and filters.\n\nMP → RS picks a TOTE at the lower median Inventory qty after filtering. The median/minimum switch exists only in manual EAN lookup. See the linked articles for MP eligibility and result statuses.","uk":"MP і RS обробляються окремо. Ключ зіставлення — код товару EAN/SKU code. Вибір залежить від стратегії кількості, multi-tote, типу полиці та фільтрів.\n\nУ MP → RS після фільтрів вибирається TOTE з нижньою медіаною Inventory qty. Перемикач медіана/мінімум є лише в ручному пошуку EAN. У пов’язаних статтях описано допуск MP та статуси результатів."},"source":"js/workers/tote.js: parseMP, parseRS; js/app.js: RS matching","related":[{"category":"openreports","topic":"overview"},{"category":"rs","topic":"mp-eligibility"},{"category":"rs","topic":"result-status"},{"category":"rs","topic":"manual-lookup"},{"category":"rs","topic":"exports"}]},{"id":"shared-mp","title":{"pl":"Wspólna Baza MP w MP i RS","ru":"Общая Baza MP для MP и RS","en":"Shared MP base across MP and RS","uk":"Спільна Baza MP для MP та RS"},"basic":{"pl":"Baza MP jest współdzielonym źródłem danych dla Scalanie, Konsolidacja oraz narzędzi RS.","ru":"Baza MP общая для Scalanie, Konsolidacja и инструментов RS.","en":"The MP workbook is a shared input for Scalanie, Konsolidacja and RS tools.","uk":"Baza MP є спільним джерелом для Scalanie, Konsolidacja та інструментів RS."},"tech":{"pl":"Wczytaj ECM_STOCK_MP_and_on_the_floor ręcznie lub przez OpenReports. W Bridge możesz wskazać obszar MP/MP1/MP2/MP3 oraz markę; do zapytania trafiają wzorce MP%/MP1%/MP2%/MP3%. Sprawdź, czy wybrano właściwą markę i lokalizację. Nie należy osobno dublować bazy w RS, jeśli wspólna baza już jest wczytana.","ru":"Загрузи ECM_STOCK_MP_and_on_the_floor вручную или через OpenReports. В Bridge можно выбрать MP/MP1/MP2/MP3 и бренд; в отчёт передаются маски MP%/MP1%/MP2%/MP3%. Проверь бренд и локацию. Если общая база уже загружена, отдельный дубликат для RS не требуется.","en":"Upload ECM_STOCK_MP_and_on_the_floor manually or via Bridge. Choose MP/MP1/MP2/MP3 and brand in the Bridge panel; the report receives MP%/MP1%/MP2%/MP3% filters. Check the chosen brand and area. The same base is reused across MP and RS.","uk":"Завантаж ECM_STOCK_MP_and_on_the_floor вручну або через Bridge. Вибери MP/MP1/MP2/MP3 та бренд; до звіту передаються MP%/MP1%/MP2%/MP3%. Перевір бренд і зону. Та сама база використовується в MP та RS."},"source":"js/app.js: toteMp; extension/openreports-bridge/content.js","related":[{"category":"rs","topic":"mp-eligibility"}]},{"id":"scalanie-geek","title":{"pl":"Scalanie Geek: grupowanie tote","ru":"Scalanie Geek: объединение tote","en":"Scalanie Geek: tote grouping","uk":"Scalanie Geek: групування tote"},"basic":{"pl":"Osobny moduł RS do analizy łączenia SKU w tote, niezależny od MP Scalanie.","ru":"Отдельный модуль RS для группировки SKU в tote, не путать с MP Scalanie.","en":"A separate RS module for grouping SKU into totes, distinct from MP Scalanie.","uk":"Окремий модуль RS для групування SKU в tote, не плутати з MP Scalanie."},"tech":{"pl":"Scalanie Geek grupuje wszystkie wiersze aktualnej bazy RS według SKU code. Dla każdego SKU liczy liczbę rekordów tote, sumę Inventory qty, maksymalną ilość w pojedynczym rekordzie oraz liczbę/sumę rekordów z qty ≤ ustawiony próg (domyślnie 3). Opcjonalny filtr maksymalnej ilości pokazuje SKU z maximum ≥ ustawiona wartość (domyślnie 10); nie ogranicza wejściowych wierszy tote. Wyszukiwanie SKU, sortowanie, zaznaczanie, kopiowanie i eksport XLSX działają na aktualnej liście; gdy zaznaczono rekordy, eksportuje się tylko zaznaczone. To inne narzędzie niż MP Scalanie.","ru":"Scalanie Geek группирует все записи загруженной RS по SKU code. Для каждого SKU считает число записей TOTE, сумму Inventory qty, максимальное количество в одной записи и число/сумму записей с qty ≤ выбранного порога (по умолчанию 3). Дополнительный фильтр по максимуму оставляет SKU с maximum ≥ заданного значения (по умолчанию 10), но не исключает отдельные TOTE из группировки. Есть поиск SKU, сортировка, отметки строк, копирование и XLSX: при наличии отметок выгружаются только отмеченные строки. Это не MP Scalanie.","en":"Scalanie Geek groups every current RS record by SKU code. Per SKU it counts TOTE records, sums Inventory qty, finds the maximum single-record quantity, and counts/sums records with qty ≤ the chosen threshold (default 3). An optional maximum filter retains SKUs whose maximum ≥ the chosen value (default 10); it does not remove individual TOTE rows before aggregation. SKU search, sorting, selection, copy and XLSX export operate on the visible list; when rows are selected, only selected rows are exported. This is separate from MP Scalanie.","uk":"Scalanie Geek групує всі рядки поточної RS за SKU code. Для кожного SKU рахує кількість записів TOTE, суму Inventory qty, максимум в одному записі та кількість/суму записів з qty ≤ встановленого порога (типово 3). Додатковий фільтр максимального значення залишає SKU з maximum ≥ обраного числа (типово 10), не відкидаючи окремі TOTE перед агрегуванням. Пошук SKU, сортування, позначення, копіювання й XLSX працюють зі списком; за наявності позначених рядків експортуються лише вони. Це не MP Scalanie."},"source":"js/app.js: Scalanie Geek; js/changelog.js","related":[{"category":"rs","topic":"scalanie-results"},{"category":"rs","topic":"exports"}]},{"id":"large-rs","title":{"pl":"Duża Baza RS i pasek postępu","ru":"Большая Baza RS и прогресс","en":"Large RS workbooks and progress","uk":"Велика Baza RS і прогрес"},"basic":{"pl":"Duże pliki Inventory balance export by sku bin mogą być odczytywane strumieniowo.","ru":"Большие файлы Inventory balance export by sku bin читаются потоково.","en":"Large Inventory balance export by sku bin files support streamed reading.","uk":"Великі файли Inventory balance export by sku bin читаються потоково."},"tech":{"pl":"Dla dużych plików RS procent pokazuje udział przetworzonego XML w etapach odczytu, a nie upływ czasu. Po wczytaniu sprawdź liczbę rekordów. Jeśli plik ma inny układ kolumn, aplikacja powinna zgłosić błąd, zamiast zgadywać dane. Wyniki operacji RS nadal zależą od filtrów i reguł modułu.","ru":"Для больших RS процент показывает фактически обработанную долю XML, а не оставшееся время. После загрузки проверь количество строк. Если столбцы не соответствуют отчёту, приложение должно сообщить об ошибке вместо угадывания данных. Итог поиска RS зависит от фильтров модуля.","en":"For large RS workbooks the percentage reflects processed XML, not elapsed time. After import verify the row count. A wrong column layout should produce an error rather than guessed data. RS results still depend on the module filters.","uk":"Для великих RS процент показує оброблену частку XML, а не час до завершення. Перевір кількість записів. Помилкова структура колонок має спричиняти помилку, а не здогад даних. Результати RS залежать від фільтрів."},"source":"js/workers/tote.js; js/app.js: toteProcessFile","related":[{"category":"rs","topic":"rs"},{"category":"rs","topic":"scalanie-results"}]},{"id":"mp-eligibility","title":{"pl":"MP → RS · które EAN są dopuszczone?","ru":"MP → RS · какие EAN допускаются?","en":"MP → RS · eligible EANs","uk":"MP → RS · які EAN допускаються?"},"basic":{"pl":"Do głównego wyszukiwania trafiają tylko EAN występujące w dokładnie jednym rekordzie MP, bez dostępnych pól rezerwacji i zgodne z filtrami.","ru":"Главный поиск рассматривает только EAN с ровно одной записью MP, без заполненных полей резервирования и с подходящими фильтрами.","en":"The main match only considers EANs with exactly one MP row, no populated reservation fields and matching MP filters.","uk":"Основний пошук бере лише EAN з рівно одним рядком MP, без заповнених полів резервування та відповідно до фільтрів."},"tech":{"pl":"Grupowanie po EAN odbywa się przed wyborem. EAN z 2 lub większą liczbą rekordów MP nie trafia do wyszukiwania, nawet jeśli jeden z nich odpowiada filtrom. Funkcja hasReservation odrzuca rekord, jeżeli QTY AVAILABLE lub QTY RESERVED ma wartość różną od null, także 0. Licznik „rejected” dotyczy takich rekordów z rezerwacją. Następnie stosowane są zakres NO OF ITEMS, LOCATION TYPE, ABC i LOCK_DESC. Puste listy wybranych typów nie ograniczają filtrowania. Wartości „missing” powstają później w fazie RS i nie są liczbą wszystkich EAN nieznalezionych w pliku MP.","ru":"Сначала строки MP группируются по EAN. Если один EAN встречается в MP дважды или чаще, он не участвует в основном поиске, даже если одна запись подходит под фильтры. `hasReservation` исключает строку, если `QTY AVAILABLE` или `QTY RESERVED` не равно null, в том числе когда там 0. Такие случаи попадают в rejected. Затем применяются диапазон `NO OF ITEMS`, LOCATION TYPE, ABC и LOCK_DESC. Пустой список выбранных типов не ограничивает поиск. Счётчик missing появляется на этапе RS и не означает все отсутствующие EAN в базе MP.","en":"Rows are grouped by EAN before any MP filtering. An EAN appearing in two or more MP rows is excluded, even if one row would pass the filters. `hasReservation` rejects a record whenever QTY AVAILABLE or QTY RESERVED is not null, including a numeric zero. Those cases increment rejected. Next come NO OF ITEMS range, LOCATION TYPE, ABC and LOCK_DESC filters. An empty selected-option list does not constrain that dimension. The missing counter is calculated during RS matching, not across all MP EANs.","uk":"Спочатку записи MP групуються за EAN. Якщо EAN зустрічається у двох або більше рядках MP, він не бере участі в пошуку, навіть якщо один рядок підходить за фільтрами. `hasReservation` виключає рядок, коли QTY AVAILABLE або QTY RESERVED не дорівнює null, зокрема при 0. Такі рядки збільшують rejected. Далі діють діапазон NO OF ITEMS, LOCATION TYPE, ABC та LOCK_DESC. Порожній список вибраних значень не обмежує відповідний фільтр. Missing рахується під час RS-пошуку, а не для всіх EAN MP."},"related":[{"category":"rs","topic":"lookup"},{"category":"rs","topic":"mp"},{"category":"rs","topic":"result-status"}],"source":"js/app.js: toteRunSearch, hasReservation, toteBuildOptions"},{"id":"result-status","title":{"pl":"MP → RS · wyniki i braki","ru":"MP → RS · найдено и отсутствует","en":"MP → RS · results and missing","uk":"MP → RS · знайдено і відсутнє"},"basic":{"pl":"Licznik kwalifikowanych EAN, znalezionych i brakujących zależy od etapów MP i RS. Wybrany tote nie musi być najtańszym ani mieć największej ilości.","ru":"Количество допустимых EAN, найденных и отсутствующих рассчитывается на разных этапах MP и RS. Выбранный TOTE не обязательно с минимальным или максимальным количеством.","en":"Eligible, found and missing counters represent different MP and RS stages. The selected TOTE does not necessarily have the lowest or highest quantity.","uk":"Допущені, знайдені та відсутні EAN рахуються на різних етапах MP і RS. Вибраний TOTE не обов’язково має мінімальну чи максимальну кількість."},"tech":{"pl":"mpUnique = liczba EAN zakwalifikowanych po filtrach MP; found = liczba z wybranym tote; missing = kwalifikowane EAN bez dopuszczalnego wyniku RS, również po filtrach rodzaju i multi-tote. rejected = EAN odrzucone przez dostępne pola rezerwacji przy warunku pojedynczego rekordu MP (pozostałe wykluczone przez filtry nie zwiększają rejected). Zgodne wpisy RS muszą być typu zaczynającego się od „pop tote”. Wybór to dolna mediana po posortowaniu qty rosnąco: np. 2, 5, 9, 20 → 5. Gdy wybór ogranicza się do 2 x 2 lub plain, wynik może być missing mimo istnienia innego rodzaju pop tote.","ru":"mpUnique = число EAN, прошедших фильтры MP; found = количество с выбранным TOTE; missing = допущенные EAN без подходящего результата RS, в том числе после фильтров типа и multi-tote. rejected = EAN, исключённые из-за наличия полей резервирования среди EAN с единственной записью MP; остальные исключённые фильтрами не увеличивают rejected. Подходящие строки RS должны иметь Shelf type, начинающийся с «pop tote». Выбирается **нижняя медиана** после сортировки qty: для 2, 5, 9, 20 это 5. При фильтре plain/2 x 2 EAN может оказаться missing, даже если другой тип TOTE существует.","en":"mpUnique counts MP-eligible EANs; found counts those assigned a TOTE; missing counts eligible EANs with no qualifying RS result, including after TOTE type and multi-TOTE filters. rejected counts the single-row MP EANs rejected due to present reservation fields; other filter exclusions do not increase rejected. Eligible RS rows have Shelf type starting with “pop tote”. The choice is the **lower median** of sorted quantities: 2, 5, 9, 20 → 5. A plain/2 x 2 filter can yield missing even if another type of TOTE exists.","uk":"mpUnique = кількість EAN після допуску MP; found = EAN з вибраним TOTE; missing = допущені EAN без відповідного RS-результату, зокрема після фільтрів типу й multi-tote. rejected = EAN з одним рядком MP, виключені через наявні поля резервування; інші MP-фільтри не збільшують rejected. Придатні рядки RS мають Shelf type, що починається з «pop tote». Вибирається **нижня медіана** за qty: для 2, 5, 9, 20 це 5. Фільтр plain/2 x 2 може дати missing, хоч існує інший TOTE."},"related":[{"category":"rs","topic":"mp-eligibility"},{"category":"rs","topic":"multi-tote"},{"category":"rs","topic":"exports"}],"source":"js/app.js: toteRunSearch, pickMedianByQty, isPopTote"},{"id":"manual-lookup","title":{"pl":"Ręczne szukanie EAN · strategia","ru":"Ручной поиск EAN · стратегия","en":"Manual EAN search · strategy","uk":"Ручний пошук EAN · стратегія"},"basic":{"pl":"Wpisz EAN rozdzielone spacją, przecinkiem, średnikiem lub nową linią. Wystarczy baza RS; baza MP nie jest wymagana.","ru":"Введи EAN через пробел, запятую, точку с запятой или новую строку. Нужна только база RS, MP не требуется.","en":"Paste EAN separated by whitespace, comma or semicolon. Only RS is required, not MP.","uk":"Введи EAN через пробіл, кому, крапку з комою або новий рядок. Потрібна лише RS, а не MP."},"tech":{"pl":"Duplikaty EAN są usuwane przed wyszukiwaniem. Brane są tylko wiersze RS typu pop tote; filtry plain/2 x 2 i multi-tote działają przed wyborem. Strategia „median” wybiera dolną medianę Inventory qty (dla 2,5,9,20 wybierze 5); „min” wybiera najmniejszą ilość. „missing” = brak pop tote dla SKU; „filtered” = pop tote istniał, ale wszystkie odpadły przez ustawienia rodzaju/multi-tote. Eksport Manual_SKU_Tote_Result.xlsx i kopiowanie nie wymagają MP.","ru":"Повторяющиеся EAN удаляются до поиска. Учитываются только строки RS с Shelf type «pop tote»; фильтры plain/2 x 2 и multi-tote применяются до выбора. Стратегия median выбирает нижнюю медиану Inventory qty (2, 5, 9, 20 → 5), min выбирает минимум. missing означает отсутствие pop tote у SKU, filtered означает, что pop tote найден, но все варианты исключены фильтрами. Для экспорта Manual_SKU_Tote_Result.xlsx и копирования MP не нужен.","en":"Duplicate EANs are removed before searching. Only RS rows whose Shelf type starts with “pop tote” count; plain/2 x 2 and multi-TOTE filters apply first. Strategy median selects the lower median Inventory qty (2, 5, 9, 20 → 5); min picks the minimum. missing means no pop tote exists for that SKU; filtered means pop totes exist but all are removed by the selected filters. Manual_SKU_Tote_Result.xlsx export and copy need no MP input.","uk":"Повторні EAN прибираються перед пошуком. Враховуються лише RS-рядки типу «pop tote»; фільтри plain/2 x 2 і multi-tote працюють перед вибором. Стратегія median бере нижню медіану Inventory qty (2, 5, 9, 20 → 5), min бере мінімум. missing означає відсутність pop tote для SKU, filtered означає, що pop tote був, але всі варіанти відкинули фільтри. Для експорту Manual_SKU_Tote_Result.xlsx і копіювання MP не потрібна."},"related":[{"category":"rs","topic":"multi-tote"},{"category":"rs","topic":"exports"},{"category":"rs","topic":"rs"}],"source":"js/app.js: parseEanList, toteRunManualSearch, pickToteByStrategy"},{"id":"multi-tote","title":{"pl":"Pop tote · plain, 2 x 2 i multi-tote","ru":"Pop tote · plain, 2 x 2 и multi-tote","en":"Pop tote · plain, 2 x 2 and multi-TOTE","uk":"Pop tote · plain, 2 x 2 і multi-tote"},"basic":{"pl":"Filtry rodzaju dotyczą Shelf type; multi-tote dotyczy kilku różnych EAN w tym samym Shelf bin.","ru":"Фильтры типа используют Shelf type, а multi-tote означает несколько разных EAN в одном Shelf bin.","en":"TOTE type comes from Shelf type; multi-TOTE means several distinct EAN codes at the same Shelf bin.","uk":"Фільтри типу використовують Shelf type, а multi-tote означає декілька різних EAN в одному Shelf bin."},"tech":{"pl":"Pop tote to Shelf type zaczynający się (bez rozróżnienia wielkości liter) od „pop tote”. 2 x 2 jest rozpoznawane po podciągu „2 x 2”; plain to pozostałe pop tote. Multi-tote: dla jednego pełnego Shelf bin istnieje więcej niż jeden różny EAN. Nie oznacza to „wiele tote dla EAN” i nie zależy od liczby wierszy. Opcje all/yes/no ograniczają listę RS na podstawie tych wielo-EAN-owych lokalizacji.","ru":"Pop tote определяется по Shelf type, начинающемуся с «pop tote» без учёта регистра. 2 x 2 определяется наличием подстроки «2 x 2», plain означает остальные pop tote. Multi-tote: в одном полном Shelf bin встречаются **два или больше разных EAN**. Это не «много TOTE одного EAN» и не просто несколько строк. Фильтры all/yes/no отбирают RS-локации по этому признаку.","en":"Pop tote means a Shelf type beginning with “pop tote” (case-insensitive). 2 x 2 is detected by the substring “2 x 2”; plain is any other pop tote. Multi-TOTE means one full Shelf bin contains **more than one distinct EAN**. It does not mean one EAN appears in several totes, nor that a bin has multiple rows. The all/yes/no filters restrict eligible RS locations by this property.","uk":"Pop tote визначається Shelf type, що починається з «pop tote» без урахування регістру. 2 x 2 визначається підрядком «2 x 2», plain означає решту pop tote. Multi-tote: в одному повному Shelf bin містяться **два чи більше різних EAN**. Це не декілька TOTE одного EAN і не просто кілька рядків. Фільтри all/yes/no обмежують RS-локації за цією ознакою."},"related":[{"category":"rs","topic":"lookup"},{"category":"rs","topic":"manual-lookup"},{"category":"rs","topic":"rs"}],"source":"js/app.js: isPopTote, is2x2, toteRsMultiToteShelfBins, toteRunSearch"},{"id":"scalanie-results","title":{"pl":"Scalanie Geek · progi, zaznaczenia, eksport","ru":"Scalanie Geek · пороги и экспорт","en":"Scalanie Geek · thresholds and export","uk":"Scalanie Geek · пороги й експорт"},"basic":{"pl":"Wyniki Scalanie Geek liczone są po SKU z aktualnego RS, a nie przez łączenie baz MP/RS.","ru":"Scalanie Geek рассчитывает показатели SKU из загруженной RS, без сопоставления с MP.","en":"Scalanie Geek summarizes SKUs from current RS rows; it does not match MP against RS.","uk":"Scalanie Geek підсумовує SKU з поточної RS без зіставлення MP і RS."},"tech":{"pl":"Liczba tote to liczba wierszy danego SKU, nie liczba unikatowych Shelf bin; suma i maksimum używają Inventory qty. Próg małych ilości (domyślnie 3) liczy wiersze z qty ≤ próg i sumuje ich ilości. Opcjonalny próg maksimum (domyślnie 10) pozostawia tylko SKU z max qty ≥ próg. Po analizie można wyszukać SKU, sortować dowolną kolumnę, zaznaczyć wiersze. Kopiowanie i eksport Scalanie_Geek_SKU_Analysis.xlsx uwzględniają zaznaczone wiersze, a bez zaznaczenia wszystkie aktualnie widoczne. Kolejna baza RS resetuje wcześniejszą analizę.","ru":"Liczba tote означает **количество строк RS данного SKU**, а не число уникальных Shelf bin. Общая сумма и максимум рассчитываются по Inventory qty. Порог малых количеств (по умолчанию 3) подсчитывает строки с qty ≤ порога и сумму их qty. Необязательный фильтр максимума (по умолчанию 10) оставляет SKU с max qty ≥ порога. После анализа доступны поиск, сортировка, отметка строк. Копирование и Scalanie_Geek_SKU_Analysis.xlsx используют отмеченные строки, а если отметок нет, все видимые. Новая загрузка RS сбрасывает предыдущий анализ.","en":"“Liczba tote” counts **RS rows per SKU**, not distinct Shelf bin locations. Total and maximum use Inventory qty. The small-quantity threshold (default 3) counts rows whose qty ≤ threshold and sums their qty. An optional max threshold (default 10) keeps SKUs with max qty ≥ threshold. After analysis use SKU search, sorting and row selection. Copy and Scalanie_Geek_SKU_Analysis.xlsx include selected rows, or all currently visible rows if none are selected. Loading a different RS resets the previous analysis.","uk":"Liczba tote означає **кількість рядків RS для SKU**, не унікальних Shelf bin. Сума й максимум беруть Inventory qty. Поріг малих кількостей (типово 3) рахує рядки з qty ≤ порога та їх суму. Необов’язковий фільтр максимуму (типово 10) залишає SKU з max qty ≥ порога. Після аналізу доступні пошук SKU, сортування та позначення рядків. Копіювання й Scalanie_Geek_SKU_Analysis.xlsx містять позначені рядки або всі видимі, якщо немає позначених. Нова RS скидає аналіз."},"related":[{"category":"rs","topic":"scalanie-geek"},{"category":"rs","topic":"exports"},{"category":"rs","topic":"large-rs"}],"source":"js/app.js: rsScalGeekRun, rsScalGeekRows, rsScalGeekExport, rsScalGeekCopy"},{"id":"exports","title":{"pl":"RS · eksport i kopiowanie","ru":"RS · экспорт и копирование","en":"RS · exports and copy","uk":"RS · експорт і копіювання"},"basic":{"pl":"Główne MP → RS, ręczne EAN i Scalanie Geek mają osobne pliki XLSX oraz inny zakres danych.","ru":"Главный MP → RS, ручной EAN и Scalanie Geek выгружают разные XLSX с разными столбцами.","en":"MP → RS, manual EAN search and Scalanie Geek export different XLSX workbooks with different columns.","uk":"MP → RS, ручний EAN і Scalanie Geek вивантажують окремі XLSX з різними стовпцями."},"tech":{"pl":"MP → RS: MP_RS_Tote_Result.xlsx ma EAN (SKU), Polka (MP), Qty (MP), TOTE (RS), Inventory Qty (RS). Ręczne EAN: Manual_SKU_Tote_Result.xlsx ma EAN, TOTE i Inventory Qty; dodatkowo można skopiować te wyniki jako TSV z nagłówkiem. Scalanie Geek: Scalanie_Geek_SKU_Analysis.xlsx ma sześć kolumn podsumowania SKU; zaznaczone wiersze ograniczają eksport/kopiowanie. W wynikach TOTE nazwa Shelf bin dostaje końcowy przecinek przy eksporcie/kopiowaniu, zgodnie z bieżącym kodem. Nie zastępuj jednego pliku drugim przy porównywaniu.","ru":"MP → RS экспортирует MP_RS_Tote_Result.xlsx со столбцами EAN (SKU), Polka (MP), Qty (MP), TOTE (RS), Inventory Qty (RS). Ручной поиск EAN экспортирует Manual_SKU_Tote_Result.xlsx со столбцами EAN, TOTE, Inventory Qty и поддерживает копирование TSV с заголовком. Scalanie Geek экспортирует Scalanie_Geek_SKU_Analysis.xlsx с шестью показателями SKU; если строки отмечены, копируются и выгружаются только они. В результатах TOTE при экспорте/копировании к Shelf bin добавляется запятая по текущей логике. Не сравнивай разные файлы, не учитывая их назначение.","en":"MP → RS exports MP_RS_Tote_Result.xlsx with EAN (SKU), Polka (MP), Qty (MP), TOTE (RS), Inventory Qty (RS). Manual EAN exports Manual_SKU_Tote_Result.xlsx with EAN, TOTE and Inventory Qty, and supports copying TSV with headings. Scalanie Geek exports Scalanie_Geek_SKU_Analysis.xlsx containing six per-SKU metrics; selected rows limit export/copy. TOTE results append a comma to Shelf bin in export/copy as implemented. These three exports cover different scopes, so compare like with like.","uk":"MP → RS експортує MP_RS_Tote_Result.xlsx зі стовпцями EAN (SKU), Polka (MP), Qty (MP), TOTE (RS), Inventory Qty (RS). Ручний EAN експортує Manual_SKU_Tote_Result.xlsx з EAN, TOTE, Inventory Qty та підтримує копіювання TSV із заголовками. Scalanie Geek експортує Scalanie_Geek_SKU_Analysis.xlsx із шістьма показниками SKU; позначення рядків обмежує експорт/копіювання. У TOTE-результатах до Shelf bin при експорті/копіюванні додається кома за поточним кодом. Ці файли мають різне призначення."},"related":[{"category":"rs","topic":"lookup"},{"category":"rs","topic":"manual-lookup"},{"category":"rs","topic":"scalanie-results"}],"source":"js/app.js: toteExportExcel, toteExportManualExcel, toteCopyManualToClipboard, rsScalGeekExport, rsScalGeekCopy"}]},{"id":"ret","emoji":"📋","title":{"pl":"AUDYT GEEK","ru":"AUDYT GEEK","en":"AUDYT GEEK","uk":"AUDYT GEEK"},"topics":[{"id":"overview","title":{"pl":"AUDYT GEEK · tryby i dane","ru":"AUDYT GEEK · режимы и данные","en":"AUDYT GEEK · modes and input","uk":"AUDYT GEEK · режими та дані"},"basic":{"pl":"AUDYT GEEK obsługuje zwykłe grupy GEEK oraz AUDYT RET w tym samym pliku Stocktake order. Oba korzystają z tych samych filtrów, ale liczą inne wskaźniki: GEEK przede wszystkim wiersze, RET unikatowe toty i przegródki.","ru":"AUDYT GEEK обрабатывает обычные группы GEEK и AUDYT RET из файла Stocktake order. Фильтры общие, но показатели разные: GEEK преимущественно считает строки пересчёта, RET — уникальные тоты и ячейки.","en":"AUDYT GEEK processes standard GEEK groups and AUDYT RET from the same Stocktake order workbook. Filters are shared, but the counters differ: GEEK mainly counts stocktake rows; RET counts distinct totes and bins.","uk":"AUDYT GEEK обробляє звичайні групи GEEK та AUDYT RET з одного файлу Stocktake order. Фільтри спільні, але показники різні: GEEK переважно рахує рядки перерахунку, RET — унікальні тоти й комірки."},"tech":{"pl":"Po wczytaniu wybierz grupy utworzone z pierwszych dwóch słów Stocktake name oraz operatorów, jeśli są dostępni. Tryb podsumowania RET w Tabeli 1 pojawia się tylko wtedy, gdy zaznaczono co najmniej jedną grupę i wszystkie zaznaczone mają nazwę AUDYT RET (bez rozróżniania wielkości liter). Przy jednoczesnym wyborze grup GEEK i RET Tabela 1 wykorzystuje standardowy sposób liczenia, natomiast Tabela 2 prezentuje grupy według ich własnych zasad. Wybór filtrów nie zmienia źródłowego pliku.","ru":"После загрузки выбери группы по первым двум словам Stocktake name и при наличии фильтра — операторов. Сводка RET в таблице 1 включается лишь тогда, когда выбрана хотя бы одна группа и все выбранные группы называются AUDYT RET (без учёта регистра). Если одновременно выбраны GEEK и RET, таблица 1 использует обычные счётчики GEEK, а таблица 2 показывает группы по соответствующим правилам. Фильтры не меняют исходный Excel.","en":"After loading, select groups based on the first two words of Stocktake name and operators when available. Table 1 switches to RET counters only if at least one group is selected and every selected group is named AUDYT RET (case-insensitive). When GEEK and RET groups are selected together, Table 1 uses standard GEEK-style counters, while Table 2 reports the groups with their corresponding rules. Filtering does not edit the source workbook.","uk":"Після завантаження обери групи за першими двома словами Stocktake name та операторів, якщо вони доступні. Таблиця 1 переходить до показників RET лише коли вибрано принаймні одну групу і всі вони мають назву AUDYT RET (без урахування регістру). При спільному виборі GEEK і RET таблиця 1 використовує звичайні лічильники GEEK, а таблиця 2 показує групи за відповідними правилами. Фільтри не змінюють Excel."},"source":"js/app.js: geekCompute, geekPrefix, geekListOptions, geekRetMode, geekT1, geekGroups; js/workers/geek.js","related":[{"category":"ret","topic":"geek"},{"category":"ret","topic":"input"},{"category":"ret","topic":"tot"},{"category":"rs","topic":"lookup"},{"category":"ret","topic":"filters"},{"category":"ret","topic":"file-errors"}]},{"id":"geek","title":{"pl":"Tryb GEEK · standardowe wskaźniki","ru":"Режим GEEK · основные показатели","en":"GEEK mode · standard metrics","uk":"Режим GEEK · основні показники"},"basic":{"pl":"W zwykłym GEEK Tabela 1 liczy wiersze przeliczenia (nie unikatowe toty): poprawne, błędne, kategorie niezgodności, odsetek i sumę sztuk. Tabela 2 podaje podsumowanie według Stocktake name.","ru":"В обычном GEEK таблица 1 считает строки пересчёта, а не уникальные тоты: правильные, ошибочные, категории ошибок, процент и сумму штук. Таблица 2 группирует результаты по Stocktake name.","en":"In standard GEEK, Table 1 counts stocktake rows, not unique totes: correct and incorrect rows, exception categories, error rate and item quantity. Table 2 groups results by Stocktake name.","uk":"У звичайному GEEK таблиця 1 рахує рядки перерахунку, а не унікальні тоти: правильні, помилкові, категорії помилок, відсоток і суму штук. Таблиця 2 групує результати за Stocktake name."},"tech":{"pl":"Do sum trafiają wybrane wiersze z niepustym Shelf bin. Exception=NO zwiększa „Toty poprawne”, YES — „Total toty błędne”. „Total toty przeliczone” = liczba wierszy; „Odsetek błędnych” = liczba wierszy YES / wszystkie wybrane wiersze × 100% (0% przy pustym wyniku). „Sztuk przeliczone” = suma Stocktake qty. Braki, nadwyżki, przepełnienie i wady są zliczane według początku Exception reason; nie wymagają jednoczesnego YES. W jednym wierszu poprawne i błędne mogą nie obejmować wartości Exception innych niż YES/NO.","ru":"В показатели входят выбранные строки с непустым Shelf bin. Exception=NO увеличивает «Toty poprawne», YES — «Total toty błędne». «Total toty przeliczone» = число строк; «Odsetek błędnych» = строки YES / все выбранные строки × 100% (0% при пустой выборке). «Sztuk przeliczone» = сумма Stocktake qty. Категории недостачи, излишков, лишнего SKU и повреждений определяются по началу Exception reason; для их подсчёта отдельная проверка YES не требуется. Если Exception отличается от YES/NO, строка всё равно входит в общий итог.","en":"Selected rows with a non-empty Shelf bin contribute to counts. Exception=NO increments Toty poprawne; YES increments Total toty błędne. Total toty przeliczone is the row count; Odsetek błędnych is YES rows / all selected rows × 100% (0% when empty). Sztuk przeliczone sums Stocktake qty. Shortage, surplus, extra SKU and damage categories use the start of Exception reason; a YES check is not additionally required for Table 1 categories. Other Exception values still contribute to the total row count.","uk":"У показники входять вибрані рядки з непорожнім Shelf bin. Exception=NO збільшує Toty poprawne, YES — Total toty błędne. Total toty przeliczone = кількість рядків; Odsetek błędnych = рядки YES / усі вибрані рядки × 100% (0% за відсутності рядків). Sztuk przeliczone = сума Stocktake qty. Категорії нестач, надлишків, зайвих SKU й пошкоджень визначаються за початком Exception reason без додаткової вимоги YES. Інші значення Exception також входять до загальної кількості рядків."},"source":"js/app.js: geekT1, geekPct, geekCategory, geekCompute","related":[{"category":"ret","topic":"overview"},{"category":"ret","topic":"input"},{"category":"ret","topic":"tot"},{"category":"ret","topic":"geek-groups"},{"category":"ret","topic":"filters"},{"category":"ret","topic":"copy"}]},{"id":"input","title":{"pl":"Tryb RET · plik i filtry","ru":"Режим RET · файл и фильтры","en":"RET mode · file and filters","uk":"Режим RET · файл і фільтри"},"basic":{"pl":"Audyt Geek odczytuje Stocktake order. Do obliczeń RET używa Shelf bin, Stocktake qty, Exception, Exception reason, Stocktake name, SKU code oraz opcjonalnie Operator.","ru":"Audyt Geek читает Stocktake order. Для RET используются Shelf bin, Stocktake qty, Exception, Exception reason, Stocktake name, SKU code и, если есть, Operator.","en":"Audyt Geek reads Stocktake order. RET uses Shelf bin, Stocktake qty, Exception, Exception reason, Stocktake name, SKU code and optional Operator.","uk":"Audyt Geek читає Stocktake order. RET використовує Shelf bin, Stocktake qty, Exception, Exception reason, Stocktake name, SKU code та, за наявності, Operator."},"tech":{"pl":"Worker wybiera arkusz zawierający Shelf bin; preferuje też Stocktake qty i Stocktake name. Nagłówki muszą być w pierwszym wierszu wybranego arkusza. Puste Shelf bin są pomijane. Tryb RET identyfikuje grupę o nazwie AUDYT RET wyprowadzonej z dwóch pierwszych słów Stocktake name. Obliczenia używają tylko wybranych grup i operatorów.","ru":"Worker выбирает лист с Shelf bin, предпочитая также Stocktake qty и Stocktake name. Заголовки должны быть в первой строке выбранного листа. Пустые Shelf bin пропускаются. RET определяется по первым двум словам Stocktake name: AUDYT RET. Расчёты учитывают выбранные группы и операторов.","en":"Worker selects a sheet containing Shelf bin, preferring Stocktake qty and Stocktake name too. Headers must be in row 1 of the selected sheet. Blank Shelf bin rows are ignored. RET is identified by the first two words of Stocktake name: AUDYT RET. Group and operator selections apply before calculations.","uk":"Worker обирає аркуш із Shelf bin, віддаючи перевагу Stocktake qty і Stocktake name. Заголовки мають бути в першому рядку. Порожні Shelf bin пропускаються. RET визначається першими двома словами Stocktake name: AUDYT RET. Фільтри груп та операторів діють до розрахунку."},"source":"js/workers/geek.js; js/app.js: geekCompute, geekPrefix, geekGroups","related":[{"category":"ret","topic":"file-errors"},{"category":"ret","topic":"compartments"}]},{"id":"tot","title":{"pl":"TOTY PRZELICZONE i POPRAWNE","ru":"TOTY PRZELICZONE и POPRAWNE","en":"Counted and correct totes","uk":"Пораховані та правильні тоти"},"basic":{"pl":"TOTY PRZELICZONE liczy unikalne toty; TOTY POPRAWNE odejmuje od nich toty z błędem Exception = YES.","ru":"TOTY PRZELICZONE считает уникальные тоты; TOTY POPRAWNE вычитает тоты с Exception = YES.","en":"TOTY PRZELICZONE counts unique totes; TOTY POPRAWNE subtracts totes with Exception = YES.","uk":"TOTY PRZELICZONE рахує унікальні тоти; TOTY POPRAWNE віднімає тоти з Exception = YES."},"tech":{"pl":"Klucz totu = pierwsze 10 znaków Shelf bin (jeżeli krótszy, cały Shelf bin). TOTY PRZELICZONE = liczba unikalnych kluczy. Błędny tot = klucz z co najmniej jednym wierszem Exception = YES. TOTY POPRAWNE = TOTY PRZELICZONE − liczba błędnych totów. SUMA NIEPOPRAWNYCH TOTÓW = liczba błędnych totów.","ru":"Ключ тота = первые 10 символов Shelf bin (если короче, всё значение). TOTY PRZELICZONE = число уникальных ключей. Ошибочный тот = хотя бы одна строка с Exception = YES. TOTY POPRAWNE = всего тотов − ошибочные. SUMA NIEPOPRAWNYCH TOTÓW = число ошибочных тотов.","en":"Tote key = first 10 characters of Shelf bin (or all if shorter). TOTY PRZELICZONE = unique keys. A tote is bad if any row with that key has Exception = YES. TOTY POPRAWNE = counted totes − bad totes. SUMA NIEPOPRAWNYCH TOTÓW = bad tote count.","uk":"Ключ тота — перші 10 символів Shelf bin (або весь, якщо коротший). TOTY PRZELICZONE — унікальні ключі. Тот помилковий, якщо хоча б один рядок має Exception = YES. TOTY POPRAWNE = усі − помилкові. SUMA NIEPOPRAWNYCH TOTÓW = кількість помилкових тотів."},"source":"js/app.js: geekRetCalc, geekT1","related":[]},{"id":"compartments","title":{"pl":"PRZEGRÓDKI PRZELICZONE","ru":"PRZEGRÓDKI PRZELICZONE","en":"Counted compartments","uk":"Пораховані комірки"},"basic":{"pl":"PRZEGRÓDKI PRZELICZONE to liczba unikatowych pełnych Shelf bin w zaznaczonych wierszach RET. W aktualnym kodzie NIE ma warunku Stocktake qty > 0.","ru":"PRZEGRÓDKI PRZELICZONE — число уникальных полных Shelf bin среди выбранных строк RET. В текущем коде НЕТ условия Stocktake qty > 0.","en":"PRZEGRÓDKI PRZELICZONE is the number of distinct full Shelf bin values in selected RET rows. The current implementation does NOT require Stocktake qty > 0.","uk":"PRZEGRÓDKI PRZELICZONE — кількість унікальних повних Shelf bin серед вибраних рядків RET. Поточний код НЕ вимагає Stocktake qty > 0."},"tech":{"pl":"geekT1 i geekRetCalc dodają każdy pełny Shelf bin do Set (po wybraniu grup i operatorów). Każda niepusta lokalizacja liczona jest raz niezależnie od Stocktake qty, także gdy qty = 0. Przykład: A/2 z qty 0, A/2 z qty 3, B/0 z qty 0 → 2 przegródki. Nie myl z SZTUKI PRZELICZONE (suma ilości).","ru":"geekT1 и geekRetCalc добавляют каждый полный Shelf bin в Set после применения фильтров группы и оператора. Каждая непустая локация учитывается один раз независимо от Stocktake qty, включая qty = 0. Пример: A/2 с qty 0, A/2 с qty 3, B/0 с qty 0 → 2 ячейки. Это не то же самое, что SZTUKI PRZELICZONE (сумма количества).","en":"geekT1 and geekRetCalc add each full Shelf bin to a Set after group and operator filters. Every non-empty location counts once regardless of Stocktake qty, including qty = 0. Example: A/2 with qty 0, A/2 with qty 3, B/0 with qty 0 → 2 bins. This differs from SZTUKI PRZELICZONE, which sums quantities.","uk":"geekT1 і geekRetCalc додають кожен повний Shelf bin до Set після фільтрів групи й оператора. Кожна непорожня локація враховується один раз незалежно від Stocktake qty, включно з qty = 0. Приклад: A/2 із qty 0, A/2 із qty 3, B/0 із qty 0 → 2 комірки. Це не SZTUKI PRZELICZONE (сума кількостей)."},"source":"js/app.js: geekT1, geekRetCalc","related":[]},{"id":"pieces","title":{"pl":"SZTUKI PRZELICZONE","ru":"SZTUKI PRZELICZONE","en":"Counted items","uk":"Пораховані одиниці"},"basic":{"pl":"To suma wartości Stocktake qty ze wszystkich wybranych wierszy RET.","ru":"Это сумма Stocktake qty всех выбранных строк RET.","en":"This is the sum of Stocktake qty across all selected RET rows.","uk":"Це сума Stocktake qty усіх обраних рядків RET."},"tech":{"pl":"W kodzie: sztuk += r.qty dla każdego wiersza z wybranej grupy i operatora. W przeciwieństwie do PRZEGRÓDKI PRZELICZONE nie ma warunku qty > 0 ani usuwania duplikatów. Przykład: 3 + 0 + 2 = 5.","ru":"В коде: sztuk += r.qty для каждой строки выбранной группы и оператора. В отличие от PRZEGRÓDKI PRZELICZONE здесь нет условия qty > 0 и удаления дублей. Пример: 3 + 0 + 2 = 5.","en":"Code sums r.qty over each selected row. Unlike counted compartments, there is no qty > 0 filter or deduplication. Example: 3 + 0 + 2 = 5.","uk":"Код додає r.qty для кожного вибраного рядка. На відміну від комірок, немає фільтра qty > 0 чи видалення дублікатів. Приклад: 3 + 0 + 2 = 5."},"source":"js/app.js: geekRetCalc","related":[]},{"id":"mixed","title":{"pl":"POMIESZANYCH SZT.","ru":"POMIESZANYCH SZT.","en":"Mixed items count","uk":"Кількість змішаних одиниць"},"basic":{"pl":"Dodaj dodatnie Stocktake qty ze wszystkich wybranych wierszy RET z niepustym Exception reason. Nie usuwaj duplikatów Shelf bin ani SKU code.","ru":"Складываем положительные Stocktake qty всех выбранных строк RET с заполненным Exception reason. Дубликаты Shelf bin и SKU code не удаляем.","en":"Sum positive Stocktake qty from selected RET rows where Exception reason is not blank. Do not deduplicate Shelf bin or SKU code.","uk":"Додаємо додатні Stocktake qty з обраних рядків RET, де Exception reason заповнено. Дублікати Shelf bin і SKU code не видаляємо."},"tech":{"pl":"Formuła: Σ max(0, Stocktake qty) dla wierszy z trim(Exception reason) ≠ pusty. Wiersz z qty = 0 nie zwiększa sumy. Przykład: reason=tak/qty=3, tak/0, pusty/7, tak/2 → 3+0+2=5. UWAGA: ta metryka nie ogranicza się do lokalizacji z duplikatami, choć TOTY Z POMESZANYMI ART. liczy takie grupy osobno.","ru":"Формула: Σ max(0, Stocktake qty) по строкам с непустым trim(Exception reason). qty=0 не увеличивает сумму. Пример: reason заполнен/3, заполнен/0, пустой/7, заполнен/2 → 3+0+2=5. ВАЖНО: здесь не требуется повторяющаяся локация, хотя TOTY Z POMESZANYMI ART. считает группы отдельно.","en":"Formula: Σ max(0, Stocktake qty) over rows with nonblank trimmed Exception reason. Example: reason present/3, present/0, blank/7, present/2 → 5. IMPORTANT: duplicates are not required for this metric, unlike the separately calculated mixed-tote count.","uk":"Формула: Σ max(0, Stocktake qty) для рядків із непорожнім trim(Exception reason). Приклад: причина є/3, є/0, порожня/7, є/2 → 5. ВАЖЛИВО: дублікати не обов’язкові для цього показника, на відміну від кількості змішаних тотів."},"source":"js/app.js: geekRetDetails (v3.6.19)","related":[]},{"id":"mixedtotes","title":{"pl":"TOTY Z POMESZANYMI ART.","ru":"TOTY Z POMESZANYMI ART.","en":"Totes with mixed articles","uk":"Тоти зі змішаними товарами"},"basic":{"pl":"Liczba grup błędów, w których powtarza się lokalizacja nadrzędna Shelf bin.","ru":"Число групп ошибочных строк с повторяющейся родительской локацией Shelf bin.","en":"Number of error-row groups sharing the same parent Shelf bin location.","uk":"Кількість груп помилкових рядків зі спільною батьківською локацією Shelf bin."},"tech":{"pl":"Tylko wiersze z niepustym Exception reason. Z każdego Shelf bin usuwa się dwa końcowe znaki. Wiersze grupuje się po pozostałej części; grupa z ≥ 2 wierszami daje 1 do mixedTots. Te wiersze nie przechodzą już do indywidualnych kategorii NADWE/BRAK/EXTRA/WADA. Przykład: ABCF1A i ABCF2A → klucz ABCF → 1.","ru":"Только строки с заполненным Exception reason. У Shelf bin отрезаются два последних символа. Группы по полученному префиксу с ≥ 2 строками дают по 1 в mixedTots. Эти строки исключаются из отдельных категорий NADWE/BRAK/EXTRA/WADA. Пример: ABCF1A и ABCF2A → ABCF → 1.","en":"Only rows with nonblank Exception reason. Remove the final two characters from Shelf bin and group by the remainder. Each group with ≥ 2 rows contributes 1 mixed tote; those rows are excluded from separate surplus/shortage/extra/damage categories. Example: ABCF1A + ABCF2A → ABCF → 1.","uk":"Лише рядки з непорожнім Exception reason. Від Shelf bin відрізають два останні символи та групують за рештою. Група з ≥ 2 рядками дає 1 змішаний тот; ці рядки виключаються з окремих категорій помилок."},"source":"js/app.js: geekRetDetails","related":[]},{"id":"bad","title":{"pl":"PRZEGRÓDKI NIE POPRAWNE i odsetek","ru":"Неправильные ячейки и процент ошибок","en":"Bad compartments and error rate","uk":"Неправильні комірки та відсоток"},"basic":{"pl":"Błędne przegródki to unikalne Shelf bin z Exception = YES. Odsetek błędów odnosi liczbę błędnych totów do wszystkich przeliczonych totów.","ru":"Неправильные ячейки — уникальные Shelf bin с Exception = YES. Процент ошибок — доля неправильных тотов среди всех пересчитанных.","en":"Bad compartments are distinct Shelf bin with Exception = YES. Error rate divides bad totes by counted totes.","uk":"Неправильні комірки — унікальні Shelf bin з Exception = YES. Відсоток помилок — частка помилкових тотів серед усіх."},"tech":{"pl":"PRZEGRÓDKI NIE POPRAWNE = Set(Shelf bin, gdzie Exception = YES).size; nie ma filtra qty > 0. ODSETEK BŁĘDÓW = SUMA NIEPOPRAWNYCH TOTÓW / TOTY PRZELICZONE × 100%; gdy mianownik = 0, wynik 0%. Przykład: 2 błędne toty / 8 przeliczonych = 25,00%.","ru":"PRZEGRÓDKI NIE POPRAWNE = число уникальных Shelf bin с Exception = YES; фильтра qty > 0 нет. ODSETEK BŁĘDÓW = SUMA NIEPOPRAWNYCH TOTÓW / TOTY PRZELICZONE × 100%; при нулевом знаменателе 0%. Пример: 2/8 = 25,00%.","en":"Bad compartments = number of distinct Shelf bin where Exception = YES; no qty > 0 requirement. Error rate = SUMA NIEPOPRAWNYCH TOTÓW / TOTY PRZELICZONE × 100%, or 0% if denominator is zero. Example: 2/8 = 25%.","uk":"Неправильні комірки = унікальні Shelf bin з Exception = YES, без умови qty > 0. Відсоток = SUMA NIEPOPRAWNYCH TOTÓW / TOTY PRZELICZONE × 100%; при знаменнику 0 — 0%. Приклад: 2/8 = 25%."},"source":"js/app.js: geekRetCalc, geekPct","related":[]},{"id":"reasons","title":{"pl":"NADWE / BRAK / EXTRA / WADA","ru":"NADWE / BRAK / EXTRA / WADA","en":"Surplus, shortage, extra, damage","uk":"Надлишки, нестачі, пошкодження"},"basic":{"pl":"Pozostałe kategorie błędów wynikają z tekstu Exception reason; nie są liczone na podstawie samego Stocktake qty.","ru":"Остальные категории ошибок определяются по Exception reason, а не просто по Stocktake qty.","en":"Other error categories are classified from Exception reason rather than simply Stocktake qty.","uk":"Інші категорії помилок визначаються через Exception reason, а не лише Stocktake qty."},"tech":{"pl":"Parser klasyfikuje prefiksy Exception reason do surplus, Shortage, Extra sku i Major damage. Ilość sztuk pobiera z liczby po ostatnim znaku „-” w tekście powodu (geekReasonQty), jeśli zapis jest liczbowy. W grupach mieszanych (powtarzający się klucz Shelf bin bez 2 znaków) kategorie indywidualne są pomijane. Pola BRAK METKI w RET są obecnie stałymi zerami.","ru":"Парсер распознаёт префиксы Exception reason: surplus, Shortage, Extra sku, Major damage. Количество для этих категорий берётся из числа после последнего «-» в причине (geekReasonQty), если оно корректно. Строки смешанных групп исключаются из индивидуальных категорий. BRAK METKI в RET сейчас всегда 0.","en":"Exception reason prefixes map to surplus, Shortage, Extra sku and Major damage. Their item quantity is parsed from the numeric suffix after the last “-” (geekReasonQty). Rows in mixed parent-location groups are excluded from individual categories. RET “missing label” fields currently remain hard-coded zero.","uk":"Префікси Exception reason визначають surplus, Shortage, Extra sku, Major damage. Кількість береться з числа після останнього «-» (geekReasonQty). Рядки змішаних груп не потрапляють до окремих категорій. BRAK METKI у RET наразі дорівнює нулю."},"source":"js/app.js: geekCategory, geekReasonQty, geekRetDetails, geekGroups","related":[{"category":"intelligence","topic":"other"}]},{"id":"copy","title":{"pl":"Tabela 1, Tabela 2 i Kopiuj","ru":"Таблицы 1/2 и копирование","en":"RET tables and copy","uk":"Таблиці 1/2 та копіювання"},"basic":{"pl":"Tabela 1 pokazuje sumaryczne wskaźniki wybranego trybu, Tabela 2 pokazuje podział na grupy. Kopiowanie całej tabeli, samych wartości lub konkretnej grupy działa lokalnie.","ru":"Таблица 1 показывает итоговые показатели выбранного режима, таблица 2 — результаты по группам. Можно копировать таблицу, только значения или определённую группу, всё локально.","en":"Table 1 shows summary counters for the selected mode; Table 2 provides group results. You can copy a table, values only or a specific group locally.","uk":"Таблиця 1 показує підсумкові показники обраного режиму, таблиця 2 — результати за групами. Можна копіювати таблицю, лише значення або окрему групу локально."},"tech":{"pl":"geekCopyT1 kopiuje pary „Metryka/Wartość”, a geekCopyT1Values wartości: w RET poziomo, rozdzielone tabulatorami; w zwykłym GEEK pionowo, rozdzielone nowymi liniami. geekCopyT2 kopiuje wszystkie grupy ze źródłowego wyniku, nie tylko widoczne po wyszukaniu nazwy grupy. geekCopyGroup kopiuje pojedynczą grupę; dla RET z włączonym trybem RET kopiuje same wartości poziomo. Skopiowane wartości można wkleić do Excela.","ru":"geekCopyT1 копирует пары «Метрика/Значение», а geekCopyT1Values — только значения: в RET горизонтально с табуляцией, в обычном GEEK вертикально по строкам. geekCopyT2 копирует все группы из рассчитанного результата, а не только видимые после текстового поиска. geekCopyGroup копирует одну группу; для RET при активном режиме RET — горизонтальный ряд значений. Результат можно вставить в Excel.","en":"geekCopyT1 copies Metric/Value pairs. geekCopyT1Values copies values only: horizontally tab-separated in RET, vertically newline-separated in standard GEEK. geekCopyT2 copies all computed groups, not just groups visible after the text search. geekCopyGroup copies one group; for RET while RET mode is active it copies a horizontal values-only row. Values can be pasted into Excel.","uk":"geekCopyT1 копіює пари «Метрика/Значення», а geekCopyT1Values — лише значення: у RET горизонтально через табуляцію, у звичайному GEEK вертикально по рядках. geekCopyT2 копіює всі обчислені групи, а не лише видимі після текстового пошуку. geekCopyGroup копіює окрему групу; для RET в активному режимі RET — горизонтальний ряд значень. Результат можна вставити до Excel."},"source":"js/app.js: geekT1Rows, geekCopyT1Values, geekCopyGroup","related":[{"category":"intelligence","topic":"other"},{"category":"ret","topic":"geek-groups"},{"category":"ret","topic":"filters"}]},{"id":"geek-groups","title":{"pl":"GEEK · Tabela 2 i kategorie","ru":"GEEK · таблица 2 и категории","en":"GEEK · Table 2 and categories","uk":"GEEK · таблиця 2 та категорії"},"basic":{"pl":"Tabela 2 pokazuje wyniki według pierwszych dwóch słów Stocktake name. Dla każdej grupy liczy przeliczone i błędne wiersze oraz kategorie błędów z EAN.","ru":"Таблица 2 группирует записи по первым двум словам Stocktake name, считает общее число строк, ошибки и категории с EAN.","en":"Table 2 groups rows by the first two words of Stocktake name, including row counts, errors and exception categories with EAN lists.","uk":"Таблиця 2 групує рядки за першими двома словами Stocktake name, показує кількість рядків, помилки й категорії з EAN."},"tech":{"pl":"Dla standardowych grup g.total = liczba wierszy, g.bledne = wiersze z Exception=YES. Kategoria pojawia się tylko dla wiersza YES i rozpoznanej przyczyny. Liczba „totów” przy kategorii w Tabeli 2 to liczba takich wierszy; sztuki pochodzą z liczby po ostatnim „-” w Exception reason, a nie ze Stocktake qty. Lista EAN pochodzi z SKU code i może zawierać powtórzenia. Kategorie: Shortage, Surplus, Extra sku, Major damage.","ru":"Для обычной группы g.total = количество строк, g.bledne = строки с Exception=YES. В категорию таблицы 2 строка попадает только при YES и распознанном Exception reason. Число «totów» рядом с категорией фактически считает такие строки; количество szt. берётся из числа после последнего «-» в Exception reason, а не из Stocktake qty. EAN берутся из SKU code, повторы возможны. Категории: Shortage, Surplus, Extra sku, Major damage.","en":"For a standard group, g.total counts rows and g.bledne counts Exception=YES rows. A Table 2 category increments only when both YES and a recognized reason are present. The value labeled “totów” for a category is a row count, while its piece count comes from the number after the last hyphen in Exception reason, not from Stocktake qty. SKU code supplies EAN lists, including possible duplicates. Categories: Shortage, Surplus, Extra sku, Major damage.","uk":"Для звичайної групи g.total = кількість рядків, g.bledne = рядки з Exception=YES. Категорія таблиці 2 збільшується лише за YES і розпізнаної причини. Значення «totów» біля категорії фактично рахує такі рядки; кількість szt. береться з числа після останнього «-» у Exception reason, а не зі Stocktake qty. EAN надходять із SKU code, повтори можливі. Категорії: Shortage, Surplus, Extra sku, Major damage."},"source":"js/app.js: geekGroups, geekGroupText, geekCategory, geekReasonQty, geekCompute","related":[{"category":"ret","topic":"geek"},{"category":"ret","topic":"reasons"}]},{"id":"filters","title":{"pl":"Filtry grup i operatorów","ru":"Фильтры групп и операторов","en":"Group and operator filters","uk":"Фільтри груп та операторів"},"basic":{"pl":"Zaznaczenia grup i operatorów wpływają na obliczenia obu tabel. Pole wyszukiwania nazw grup działa wyłącznie na widoczność kart wyników Tabeli 2.","ru":"Галочки групп и операторов влияют на расчёты обеих таблиц. Поиск по названию группы лишь скрывает или показывает карточки в таблице 2.","en":"Group and operator checkboxes affect the calculations in both tables. The group-name search only changes which Table 2 result cards are visible.","uk":"Позначки груп та операторів впливають на розрахунки обох таблиць. Пошук за назвою групи лише змінює видимість карток таблиці 2."},"tech":{"pl":"Po wczytaniu wszystkie grupy i operatorzy są zaznaczeni. Dostępni operatorzy są pobierani z kolumny Operator; jeśli jej nie ma, kod może użyć kolumny o indeksie 15 przy wystarczającej liczbie kolumn. Jeśli nie ma rozpoznanego operatora, filtr nie jest wyświetlany. Wybór innych grup zmienia listę liczników dla operatorów. Pole wyszukiwania nazw grup to filtr wyświetlania i nie zmienia wyników ani zestawu kopiowanego przyciskiem całej Tabeli 2. Użyj zaznaczeń grup, aby zmienić wyniki.","ru":"После загрузки все группы и операторы отмечены. Операторы берутся из столбца Operator; если его нет, код может использовать колонку с индексом 15 при достаточном числе столбцов. Если оператор не распознан, фильтр не показывается. Выбор групп меняет счётчики доступных операторов. Текстовый поиск названия группы меняет только видимость карточек, не пересчитывает цифры и не ограничивает копирование всей таблицы 2. Для изменения расчёта используй галочки групп.","en":"All groups and operators are selected after loading. Operators come from the Operator column; if it is missing and enough columns exist, the code may fall back to column index 15. Without a recognized operator, the filter does not appear. Selecting groups changes operator counts. Text search of group names changes visibility only: it does not recalculate figures or limit Copy Table 2. Use group checkboxes to change calculations.","uk":"Після завантаження всі групи та оператори позначені. Оператори надходять зі стовпця Operator; якщо його немає, код може використати стовпець з індексом 15 за достатньої кількості стовпців. Без розпізнаного оператора фільтр не відображається. Вибір груп змінює лічильники операторів. Текстовий пошук змінює лише видимість карток, а не показники й не обмежує копіювання всієї таблиці 2. Для зміни розрахунку використовуй позначки груп."},"source":"js/app.js: geekListOptions, geekOpOptions, geekGroupsFiltered, geekResetFilters, geekCopyT2","related":[{"category":"ret","topic":"overview"},{"category":"ret","topic":"copy"}]},{"id":"file-errors","title":{"pl":"Plik Stocktake order · wymagane kolumny","ru":"Stocktake order · обязательные столбцы","en":"Stocktake order · required columns","uk":"Stocktake order · обов’язкові стовпці"},"basic":{"pl":"Jeśli Tabela 1 lub 2 nie wyświetla wyników, sprawdź nagłówki, zaznaczenia grup i operatorów oraz zawartość Shelf bin.","ru":"Если таблица 1 или 2 пуста, проверь заголовки, галочки групп и операторов и значения Shelf bin.","en":"If Table 1 or 2 has no results, check column headers, group/operator selections and Shelf bin values.","uk":"Якщо таблиця 1 чи 2 порожня, перевір заголовки, вибір груп та операторів і значення Shelf bin."},"tech":{"pl":"Worker szuka arkusza zawierającego Shelf bin w pierwszym wierszu; preferuje też arkusze z Stocktake qty i Stocktake name. Tabela 1 wymaga Shelf bin, Stocktake qty, Exception, Exception reason. Tabela 2 wymaga Shelf bin, Exception, Exception reason, Stocktake name, SKU code. Puste Shelf bin są pomijane. Analiza odczytuje .xlsx, .xls i .xlsm. Nie poprawia nagłówków ani formatu źródłowego pliku automatycznie. Gdy brakuje kolumn właściwych tylko dla jednej tabeli, druga może nadal działać.","ru":"Worker ищет лист, у которого Shelf bin находится в первой строке заголовков, и предпочитает листы со Stocktake qty и Stocktake name. Для таблицы 1 нужны Shelf bin, Stocktake qty, Exception, Exception reason. Для таблицы 2: Shelf bin, Exception, Exception reason, Stocktake name, SKU code. Строки с пустым Shelf bin пропускаются. Поддержаны .xlsx, .xls, .xlsm. Названия столбцов и исходный Excel автоматически не исправляются. Если отсутствуют поля только одной таблицы, другая может продолжать работать.","en":"The worker finds a worksheet with Shelf bin in its first header row and prefers sheets with Stocktake qty and Stocktake name. Table 1 requires Shelf bin, Stocktake qty, Exception, Exception reason; Table 2 requires Shelf bin, Exception, Exception reason, Stocktake name, SKU code. Rows with blank Shelf bin are skipped. The reader accepts .xlsx, .xls and .xlsm. It does not automatically fix source headers or workbook formatting. If columns required by only one table are missing, the other table may still work.","uk":"Worker шукає аркуш зі Shelf bin у першому рядку заголовків і віддає перевагу аркушам зі Stocktake qty та Stocktake name. Для таблиці 1 потрібні Shelf bin, Stocktake qty, Exception, Exception reason; для таблиці 2 — Shelf bin, Exception, Exception reason, Stocktake name, SKU code. Рядки з порожнім Shelf bin пропускаються. Підтримуються .xlsx, .xls і .xlsm. Заголовки й вихідний Excel автоматично не виправляються. Якщо бракує колонок лише однієї таблиці, інша може працювати."},"source":"js/workers/geek.js: GEEK_WORKER_CODE; js/app.js: geekCompute, geekOnFile","related":[{"category":"ret","topic":"input"},{"category":"system","topic":"errors"}]}]},{"id":"mp","emoji":"🗃️","title":{"pl":"MP · narzędzia","ru":"MP · инструменты","en":"MP · tools","uk":"MP · інструменти"},"topics":[{"id":"audit","title":{"pl":"AL AUDYT i FORMATKA59","ru":"AL AUDYT и FORMATKA59","en":"AL AUDYT and FORMATKA59","uk":"AL AUDYT та FORMATKA59"},"basic":{"pl":"Moduł MP analizuje pliki audytu i przygotowuje wyniki dla AL AUDYT i FORMATKA59.","ru":"Модуль MP обрабатывает аудиторские Excel-файлы для AL AUDYT и FORMATKA59.","en":"MP parses audit Excel files for AL AUDYT and FORMATKA59 outputs.","uk":"MP обробляє Excel-файли аудиту для AL AUDYT та FORMATKA59."},"tech":{"pl":"Parser audytu szuka w pierwszych 10 wierszach nagłówków Location, Incident i Info (gdy nie znajdzie, przyjmuje drugi wiersz). Kolumny dopasowuje po nazwie, najpierw dokładnie, potem częściowo. FORMATKA59 ma osobny parser. Szczegółowe liczniki należy sprawdzać w widoku danego raportu, bo nie są wspólnym algorytmem dla wszystkich narzędzi MP.","ru":"Парсер аудита ищет Location, Incident, Info среди первых 10 строк (если не находит, берёт вторую). Названия колонок сопоставляются точно, затем частично. FORMATKA59 имеет отдельный парсер. Подробные формулы этих отчётов не следует смешивать: они различаются по режимам.","en":"Audit parser scans the first 10 rows for Location, Incident and Info (falls back to row 2). Headers are matched exactly, then partially. FORMATKA59 has a separate parser. Detailed counts differ by report; there is no shared formula for every MP tool.","uk":"Парсер аудиту шукає Location, Incident та Info у перших 10 рядках (інакше другий). Заголовки зіставляються точно, потім частково. FORMATKA59 має окремий парсер; формули відрізняються за звітами."},"source":"js/workers/audyt.js: findAuditHeaderRow, parseAudyt, parseFormatka59","related":[{"category":"intelligence","topic":"al"},{"category":"intelligence","topic":"formatka"},{"category":"openreports","topic":"use"}]},{"id":"stock","title":{"pl":"STOCK i GODZINYMDT","ru":"STOCK и GODZINYMDT","en":"STOCK and GODZINYMDT","uk":"STOCK та GODZINYMDT"},"basic":{"pl":"STOCK porządkuje dane magazynowe według lokalizacji i czasu. GODZINYMDT analizuje raport MDT i związane z nim lokalizacje.","ru":"STOCK обрабатывает складские локации и время, GODZINYMDT — отчёты MDT и соответствующие локации.","en":"STOCK organizes warehouse locations/time; GODZINYMDT processes MDT reports and related locations.","uk":"STOCK обробляє локації й час, GODZINYMDT — звіти MDT та відповідні локації."},"tech":{"pl":"To dwa oddzielne workery: js/workers/stock.js i js/workers/mdt.js. Każdy czyta własny format raportu; wynik zależy od danych wejściowych i filtrów. Nie należy używać kolumn z Audyt Geek jako zamiennika dla tych raportów.","ru":"Это два отдельных обработчика: js/workers/stock.js и js/workers/mdt.js. У каждого свой формат Excel и фильтры. Колонки Audyt Geek не являются универсальным форматом для этих модулей.","en":"Separate workers: js/workers/stock.js and js/workers/mdt.js. Each reads its own report layout and applies its module-specific logic. Audyt Geek columns are not interchangeable with these inputs.","uk":"Окремі обробники: js/workers/stock.js та js/workers/mdt.js. Кожен має власний формат Excel і правила. Стовпці Audyt Geek не є заміною."},"source":"js/workers/stock.js; js/workers/mdt.js","related":[{"category":"intelligence","topic":"mdt"},{"category":"openreports","topic":"use"},{"category":"intelligence","topic":"stock"}]},{"id":"scalanie","title":{"pl":"Scalanie i Konsolidacja","ru":"Scalanie и Konsolidacja","en":"Scalanie and consolidation","uk":"Scalanie та консолідація"},"basic":{"pl":"Scalanie pomaga wybrać lokalizacje i przygotować dane do dalszej pracy; Konsolidacja wskazuje kandydatów do połączenia.","ru":"Scalanie помогает отбирать локации и готовить данные для дальнейшей работы; Konsolidacja ищет кандидатов на объединение.","en":"Scalanie selects locations for follow-up; Konsolidacja identifies consolidation candidates.","uk":"Scalanie обирає локації для подальшої роботи; Konsolidacja визначає кандидатів на об’єднання."},"tech":{"pl":"Wyniki Scalanie można filtrować i zaznaczać. Zaznaczenie lokalizacji jest uwzględniane w Kopiuj i eksporcie CSV. Szczegółowe reguły wyboru zależą od ustawień typu półki, ABC i zakresu SKU; nie ma jednej stałej liczby wynikowej.","ru":"В Scalanie можно фильтровать и отмечать локации; выбор учитывается при копировании и CSV-экспорте. Условия зависят от типа полки, ABC и диапазона SKU. Единой формулы для всех результатов нет.","en":"Scalanie results support filtering and selecting locations. The selection is respected by Copy and CSV export. Rules depend on shelf type, ABC and SKU range settings; there is no single fixed result formula.","uk":"У Scalanie можна фільтрувати й вибирати локації; вибір враховується при копіюванні та CSV-експорті. Умови залежать від типу полиці, ABC та діапазону SKU."},"source":"js/app.js: MP Scalanie; README.pl.md","related":[{"category":"intelligence","topic":"kons"}]},{"id":"brand-modes","title":{"pl":"Tryby SINSAY / MOHITO w audycie MP","ru":"Режимы SINSAY / MOHITO в MP Audyt","en":"SINSAY / MOHITO modes in MP audits","uk":"Режими SINSAY / MOHITO в MP Audyt"},"basic":{"pl":"W MP → Audyt wybierz markę, aby ustawić zakres lokalizacji bez zmiany sposobu liczenia wyników.","ru":"В MP → Audyt выбери бренд, чтобы задать набор локаций без изменения формул.","en":"Choose a brand in MP → Audyt to define locations without changing calculation formulas.","uk":"У MP → Audyt вибери бренд для визначення локацій без зміни формул."},"tech":{"pl":"SINSAY pomija MP1 i MP3. MOHITO pomija MP2 i pozwala wybrać MP1, MP3 lub oba typy. Dotyczy AL_AUDYT, GODZINY_MDT i STOCK, również ręcznego wyboru lokalizacji. FORMATKA_59 nadal bierze tylko MP2. Zmiana trybu czyści poprzedni wynik.","ru":"SINSAY исключает MP1 и MP3. MOHITO исключает MP2 и позволяет выбрать MP1, MP3 или оба. Работает в AL_AUDYT, GODZINY_MDT, STOCK, включая ручной выбор локаций. FORMATKA_59 по-прежнему только MP2. Переключение режима сбрасывает предыдущий результат.","en":"SINSAY excludes MP1 and MP3. MOHITO excludes MP2 and offers MP1, MP3 or both. This applies to AL_AUDYT, GODZINY_MDT and STOCK, including manual location selection. FORMATKA_59 stays MP2-only. Changing modes clears previous results.","uk":"SINSAY виключає MP1 і MP3. MOHITO виключає MP2 та дозволяє вибрати MP1, MP3 або обидва. Це діє в AL_AUDYT, GODZINY_MDT й STOCK, включно з ручним вибором. FORMATKA_59 лишається тільки для MP2. Зміна режиму скидає попередній результат."},"source":"js/app.js: MP brand/location filters; js/workers/audyt.js","related":[]},{"id":"location-multi","title":{"pl":"Typ lokalizacji w Scalanie i Konsolidacja","ru":"Типы локаций в Scalanie и Konsolidacja","en":"Location types in Scalanie and Konsolidacja","uk":"Типи локацій у Scalanie та Konsolidacja"},"basic":{"pl":"W Scalanie i Konsolidacja możesz wybierać MP1, MP2 i MP3 niezależnie lub łącznie.","ru":"В Scalanie и Konsolidacja можно выбрать MP1, MP2 и MP3 по одному или вместе.","en":"In Scalanie and Konsolidacja you can select MP1, MP2 and MP3 individually or together.","uk":"У Scalanie й Konsolidacja можна вибирати MP1, MP2 і MP3 окремо чи разом."},"tech":{"pl":"Zaznaczony typ ma fioletowe tło i znacznik wyboru, niezaznaczony jest neutralny. Wyniki i eksport uwzględniają tylko wybrane typy; zmiana wyboru usuwa poprzedni wynik. Domyślnie wszystkie trzy typy są zaznaczone.","ru":"Выбранный тип фиолетовый с галочкой; невыбранный нейтрален. Результаты и экспорт учитывают только выбранные типы; изменение выбора очищает старые результаты. По умолчанию выбраны все три.","en":"Selected types are purple with a check mark; unselected types are neutral. Results and export use selected types only; changing selection clears old results. All three are selected by default.","uk":"Вибраний тип фіолетовий із позначкою; невибраний нейтральний. Результати й експорт враховують лише вибрані типи; зміна вибору очищує старі результати. Типово вибрано всі три."},"source":"index.html: MP location types; js/app.js: Scalanie/Konsolidacja location selection","related":[]},{"id":"technical-description","title":{"pl":"Scalanie: filtr TECHNICAL DESCRIPTION","ru":"Scalanie: фильтр TECHNICAL DESCRIPTION","en":"Scalanie: TECHNICAL DESCRIPTION filter","uk":"Scalanie: фільтр TECHNICAL DESCRIPTION"},"basic":{"pl":"Wyszukaj fragment nazwy produktu, wyklucz niechciane warianty i zachowaj wykluczenia podczas kolejnego wyszukiwania.","ru":"Ищи фрагмент описания товара, исключай ненужные варианты и сохраняй исключения при новом поиске.","en":"Search product-description fragments, exclude unwanted variants, and keep exclusions across searches.","uk":"Шукай фрагмент опису товару, виключай непотрібні варіанти й зберігай виключення між пошуками."},"tech":{"pl":"Przykład: wpisz „Kurtka”, przejrzyj warianty TECHNICAL DESCRIPTION i wyklucz określone rozmiary/typy, nie usuwając pozostałych. Filtr jest dostępny przed analizą oraz do doprecyzowania Wyniki; bez automatycznego uzupełniania liczby lokalizacji. Wybór lokalizacji nadal wpływa na Kopiuj i CSV.","ru":"Пример: введи «Kurtka», исключи отдельные варианты TECHNICAL DESCRIPTION, остальные оставь. Исключения можно сохранять между поисками, фильтровать до анализа и уточнять в Wyniki. Автодобора до фиксированного числа локаций нет. Выбор локаций влияет на копирование и CSV.","en":"Example: search for “Kurtka”, exclude specific TECHNICAL DESCRIPTION variants and keep the rest. Exclusions persist across searches; filtering can be applied before analysis and refined in Wyniki. There is no automatic refill to a target location count. Selected locations drive Copy and CSV.","uk":"Наприклад, введи «Kurtka», виключи окремі варіанти TECHNICAL DESCRIPTION, решту залиш. Виключення зберігаються між пошуками; є фільтр до аналізу й уточнення в Wyniki. Автодобору до фіксованої кількості немає. Вибір впливає на копіювання й CSV."},"source":"js/app.js: MP Scalanie TECHNICAL DESCRIPTION; js/changelog.js: v3.13.0","related":[]},{"id":"mp-consolidation","title":{"pl":"Konsolidacja: wynik, EAN i lokalizacje","ru":"Konsolidacja: EAN и локации","en":"Konsolidacja: EAN and locations","uk":"Konsolidacja: EAN і локації"},"basic":{"pl":"Konsolidacja pokazuje kandydatów do połączenia na podstawie wspólnej bazy MP i ustawionych warunków.","ru":"Konsolidacja ищет кандидатов для объединения по общей базе MP и выбранным условиям.","en":"Konsolidacja identifies consolidation candidates from the shared MP base and selected conditions.","uk":"Konsolidacja визначає кандидатів на об’єднання за спільною базою MP та вибраними умовами."},"tech":{"pl":"Na kartach wyniku ważne są EAN, TECHNICAL DESCRIPTION, suma oraz lista lokalizacji z ilościami. Możesz wybrać zakres MP1/MP2/MP3. Zmiany wyglądu kart nie zmieniają przeliczeń; sprawdź filtry przed użyciem wyniku.","ru":"На карточках результата показаны EAN, TECHNICAL DESCRIPTION, количество и локации с остатками. Можно выбирать MP1/MP2/MP3. Изменение внешнего вида карточек не изменяет расчёты; перед использованием результата проверь фильтры.","en":"Result cards show EAN, TECHNICAL DESCRIPTION, quantity and locations with their amounts. Select MP1/MP2/MP3 areas as needed. Card layout does not alter calculations; verify filters before using results.","uk":"Картки результатів показують EAN, TECHNICAL DESCRIPTION, кількість та локації із залишками. Можна обрати MP1/MP2/MP3. Оформлення карток не змінює розрахунків; перевір фільтри."},"source":"js/app.js: MP Konsolidacja; js/changelog.js","related":[]},{"id":"mp-progress","title":{"pl":"Baza MP: postęp odczytu dużych XLSX","ru":"Baza MP: прогресс больших Excel","en":"Baza MP: large Excel progress","uk":"Baza MP: прогрес великих Excel"},"basic":{"pl":"Duża Baza MP korzysta z odczytu strumieniowego, a wskaźnik pokazuje faktycznie przetwarzane dane.","ru":"Для большой Baza MP используется потоковое чтение и настоящий прогресс данных.","en":"Large MP workbooks use streamed reading with measured processing progress.","uk":"Велика Baza MP використовує потокове читання та вимірюваний прогрес."},"tech":{"pl":"Procent pokazuje postęp przetwarzania danych, nie przewidywany czas zakończenia. Mniejsze XLSX mogą używać zwykłego odczytu SheetJS i pokazywać etapy pracy. Wczytanie MP nie zmienia reguł Scalanie, Konsolidacja ani RS.","ru":"Процент отражает обработанную часть данных, а не оставшееся время. Небольшие XLSX могут обрабатываться обычным SheetJS с поэтапным прогрессом. Загрузка MP сама по себе не меняет алгоритмы Scalanie, Konsolidacja или RS.","en":"The percentage tracks processed data rather than time remaining. Smaller XLSX files may use regular SheetJS with stage-based progress. Changing the file-reading method does not change the Scalanie, Konsolidacja or RS business rules.","uk":"Процент відображає оброблені дані, а не час до завершення. Невеликі XLSX можуть читатися звичайним SheetJS з етапним прогресом. Зміна читання не змінює правила Scalanie, Konsolidacja чи RS."},"source":"js/workers/tote.js; js/app.js: toteProcessFile","related":[]},{"id":"stock-mdt-bridge","title":{"pl":"STOCK i GODZINY MDT: raporty oraz przejście do Kreseczki","ru":"STOCK и GODZINY MDT: отчёты и Kreseczki","en":"STOCK and GODZINY MDT: reports and barcode shortcut","uk":"STOCK та GODZINY MDT: звіти й Kreseczki"},"basic":{"pl":"STOCK i GODZINY MDT korzystają z osobnych raportów. Z obu modułów można otworzyć Kreseczki i wrócić do poprzedniej karty.","ru":"STOCK и GODZINY MDT используют разные отчёты. Из обоих модулей можно открыть Kreseczki и вернуться к прежней вкладке.","en":"STOCK and GODZINY MDT use different report inputs. Both provide a shortcut to Kreseczki with a return to the previous tab.","uk":"STOCK і GODZINY MDT працюють з різними звітами. З обох модулів можна перейти до Kreseczki та повернутися назад."},"tech":{"pl":"Wczytaj raport przeznaczony dla wybranego modułu i wykonaj analizę. Skrót Kreseczki pozwala przygotować kod kreskowy bez utraty wybranej karty. Instrukcje pobierania raportów znajdziesz w OpenReports Bridge.","ru":"Загрузи отчёт нужного модуля и выполни анализ. Быстрый переход в Kreseczki позволяет создать штрихкод и вернуться в исходную вкладку. Инструкция по загрузке отчётов находится в OpenReports Bridge.","en":"Load the matching report and run the analysis. The Kreseczki shortcut opens barcode generation with a return to the source tab. Report retrieval is documented under OpenReports Bridge.","uk":"Завантаж звіт потрібного модуля й виконай аналіз. Перехід до Kreseczki дозволяє створити штрихкод і повернутися до вкладки. Отримання звітів описане в OpenReports Bridge."},"source":"extension/openreports-bridge/content.js; js/app.js: STOCK, GODZINY MDT","related":[{"category":"openreports","topic":"use"},{"category":"intelligence","topic":"mdt"}]}]},{"id":"inne","emoji":"🛠️","title":{"pl":"Inne · narzędzia","ru":"Inne · инструменты","en":"Other tools","uk":"Інші інструменти"},"topics":[{"id":"downtime","title":{"pl":"Przestoje: źródło i obliczenia","ru":"Простои: данные и расчёты","en":"Downtime input and calculations","uk":"Простої: дані та обчислення"},"basic":{"pl":"AnalizaPrzestojów czyta daty/czasy i USER ID z raportu, a następnie wyszukuje przerwy pomiędzy zdarzeniami.","ru":"Анализ простоев читает дату/время и USER ID из отчёта, затем ищет промежутки между событиями.","en":"Downtime analysis reads timestamps and USER ID and looks for gaps between events.","uk":"Аналіз простоїв читає час та USER ID і шукає проміжки між подіями."},"tech":{"pl":"Worker czyta pierwszy arkusz, zaczynając od trzeciego wiersza (indeks 2). Kolumna A = data/czas, B = USER ID, D = process. Data może być datą Excela, liczbą seryjną lub tekstem. Obliczenia przerw są wykonywane później w aplikacji, z wybranym progiem; sam worker nie wylicza minut przestoju.","ru":"Worker читает первый лист начиная с третьей строки (индекс 2). A = дата/время, B = USER ID, D = process. Дата может быть объектом Date, числом Excel или текстом. Интервалы вычисляются позже в приложении с выбранным порогом; сам worker минуты не считает.","en":"Worker reads the first sheet from row 3 (index 2): A=timestamp, B=USER ID, D=process. Date may be an Excel serial, Date object or text. Gap duration is calculated later in the app with the chosen threshold; the worker itself does not calculate downtime minutes.","uk":"Worker читає перший аркуш із третього рядка (індекс 2): A=час, B=USER ID, D=process. Дата може бути числом Excel, Date або текстом. Тривалість пауз обчислюється пізніше з обраним порогом."},"source":"js/workers/przestoje.js; js/app.js: Przestoje","related":[{"category":"intelligence","topic":"other"}]},{"id":"artltt","title":{"pl":"ARTLTT: generowanie CSV","ru":"ARTLTT: создание CSV","en":"ARTLTT CSV generation","uk":"ARTLTT: створення CSV"},"basic":{"pl":"W ARTLTT wklejasz nazwy produktów, a narzędzie przygotowuje plik CSV dla procesu LTT.","ru":"В ARTLTT вставляешь названия товаров, инструмент готовит CSV для LTT.","en":"Paste product names into ARTLTT to generate an LTT CSV.","uk":"Вставте назви товарів в ARTLTT, щоб створити CSV для LTT."},"tech":{"pl":"To narzędzie działa lokalnie w przeglądarce. Nie wymaga łączenia się z serwerem. Sprawdź wynikowy CSV przed użyciem w zewnętrznym systemie; jest to plik wynikowy, a nie automatyczne wysłanie danych.","ru":"Инструмент работает локально в браузере, без сервера. Перед использованием проверь полученный CSV. Это создание файла, а не автоматическая отправка данных в другую систему.","en":"Runs locally in the browser without a server. Verify the generated CSV before downstream use; generation does not automatically submit data to another system.","uk":"Працює локально в браузері без сервера. Перевіряйте CSV перед використанням; створення файлу не означає автоматичне надсилання."},"source":"js/app.js: ARTLTT; README.pl.md","related":[]},{"id":"barcode","title":{"pl":"Kreseczki: Code 128","ru":"Kreseczki: Code 128","en":"Kreseczki: Code 128","uk":"Kreseczki: Code 128"},"basic":{"pl":"Kreseczki tworzy kod kreskowy Code 128 z wpisanego tekstu lub cyfr, pokazuje podgląd i pozwala wydrukować.","ru":"Kreseczki создаёт штрихкод Code 128 из текста или цифр, показывает предпросмотр и позволяет печатать.","en":"Kreseczki generates a Code 128 barcode from text/numbers, previews it and supports printing.","uk":"Kreseczki створює штрихкод Code 128 із тексту/цифр, показує попередній перегляд та дозволяє друк."},"tech":{"pl":"Generator korzysta z lokalnego skryptu js/code128.js. Akcje w interfejsie to Drukuj i Wyczyść. W obecnym interfejsie nie ma osobnych przycisków pobierania PNG/SVG. Działanie nie wymaga internetu po zainstalowaniu PWA.","ru":"Генератор использует локальный js/code128.js. Кнопки: Drukuj и Wyczyść. Отдельных кнопок PNG/SVG в текущем интерфейсе нет. После установки PWA интернет не нужен.","en":"Uses the local js/code128.js implementation. UI actions are Print and Clear. There are no separate PNG/SVG download buttons in the current interface. Works offline after PWA installation.","uk":"Використовує локальний js/code128.js. Кнопки: Drukuj та Wyczyść. Окремих кнопок PNG/SVG немає. Працює офлайн після встановлення PWA."},"source":"js/code128.js; js/app.js; README.pl.md","related":[]}]},{"id":"system","emoji":"⚙️","title":{"pl":"Pliki, eksport i offline","ru":"Файлы, экспорт и офлайн","en":"Files, export & offline","uk":"Файли, експорт і офлайн"},"topics":[{"id":"offline","title":{"pl":"Offline i aktualizacje PWA","ru":"Офлайн и обновления PWA","en":"Offline and PWA updates","uk":"Офлайн та оновлення PWA"},"basic":{"pl":"Po pierwszym poprawnym wczytaniu aplikacja może pracować offline. Aktualizacja jest dostarczana przez Service Worker.","ru":"После первой успешной загрузки приложение может работать офлайн. Обновления доставляет Service Worker.","en":"After initial successful loading, the app can work offline. Service Worker handles updates.","uk":"Після першого успішного завантаження застосунок може працювати офлайн. Оновлення забезпечує Service Worker."},"tech":{"pl":"sw.js zawiera listę PRECACHE_URLS obejmującą kod, style, biblioteki, workery i MR. BOT. Przy instalacji nowej wersji zasoby są pobierane do wersjonowanego cache. Jeśli instalacja zasobów się nie powiedzie, nowy cache nie powinien zastępować działającego. Dostęp do aktualizacji wymaga połączenia z internetem.","ru":"sw.js содержит PRECACHE_URLS с кодом, стилями, библиотеками, воркерами и MR. BOT. Новая версия загружается в версионированный кеш. При неудачной загрузке ресурсов новый кеш не должен заменять рабочий. Для получения обновлений нужен интернет.","en":"sw.js precaches code, styles, libraries, workers and MR. BOT in a versioned cache. An incomplete new cache should not replace a working installation. Internet access is required to receive new releases.","uk":"sw.js кешує код, стилі, бібліотеки, воркери та MR. BOT у версійному кеші. Неповне оновлення не повинно замінювати робочу версію. Для оновлень потрібен інтернет."},"source":"sw.js: CACHE_REVISION, PRECACHE_URLS","related":[]},{"id":"errors","title":{"pl":"Gdy Excel nie daje wyników","ru":"Если Excel не даёт результатов","en":"When Excel produces no results","uk":"Якщо Excel не дає результатів"},"basic":{"pl":"Sprawdź, czy to plik właściwego modułu, czy ma oczekiwane kolumny i czy filtry nie ukrywają wszystkich wierszy.","ru":"Проверь, тот ли это Excel-файл, есть ли нужные колонки и не скрыли ли фильтры все строки.","en":"Check that the Excel file matches the module, has the expected columns and is not fully excluded by filters.","uk":"Перевірте, чи Excel відповідає модулю, має потрібні стовпці та чи фільтри не приховали всі рядки."},"tech":{"pl":"Audyt Geek oczekuje Shelf bin, Exception i Exception reason; do pełnego Tryb RET także Stocktake name i SKU code, a Stocktake qty jest potrzebne do liczników ilości. KPI używa USER LOGIN, NUMBER OF ITEMS i kolumn czasu/wydajności. Różne moduły szukają nagłówków w różnych wierszach. Nie zmieniaj nagłówków ręcznie bez sprawdzenia schematu.","ru":"Audyt Geek требует Shelf bin, Exception, Exception reason; для полного RET также Stocktake name, SKU code, а Stocktake qty нужен для количественных показателей. KPI использует USER LOGIN, NUMBER OF ITEMS и время/производительность. Разные модули ищут заголовки в разных строках. Не переименовывай их наугад.","en":"Audyt Geek expects Shelf bin, Exception, Exception reason; full RET also requires Stocktake name and SKU code, while Stocktake qty is needed for quantity metrics. KPI expects USER LOGIN, NUMBER OF ITEMS and time/rate fields. Header row detection differs by module.","uk":"Audyt Geek очікує Shelf bin, Exception, Exception reason; повний RET також Stocktake name і SKU code, а Stocktake qty потрібен для кількостей. KPI очікує USER LOGIN, NUMBER OF ITEMS та час/продуктивність. Рядок заголовків відрізняється за модулем."},"source":"js/app.js: geekCompute; js/workers/kpi.js; js/workers/geek.js","related":[{"category":"openreports","topic":"troubleshoot"}]},{"id":"export","title":{"pl":"Kopiuj, CSV i Excel","ru":"Копирование, CSV и Excel","en":"Copy, CSV and Excel","uk":"Копіювання, CSV та Excel"},"basic":{"pl":"Kopiuj wysyła wyniki do schowka, CSV tworzy plik tekstowy, a eksport XLSX przygotowuje arkusz. Dostępne opcje zależą od modułu.","ru":"Копирование отправляет данные в буфер, CSV создаёт текстовый файл, XLSX — таблицу. Доступность зависит от модуля.","en":"Copy writes to clipboard, CSV creates a text file and XLSX export produces a workbook. Availability varies by module.","uk":"Копіювання переносить у буфер, CSV створює текстовий файл, XLSX — книгу. Опції залежать від модуля."},"tech":{"pl":"W RET kopiowanie Tabeli 1 i 2 daje wartości oddzielone tabulatorami. W MP Scalanie zaznaczenie lokalizacji wpływa na Kopiuj i CSV. KPI ma własny eksport XLSX z oznaczeniami norm. Eksport nie zmienia danych wejściowych ani pliku źródłowego.","ru":"В RET Таблицы 1 и 2 копируются с разделителями-табуляциями. В MP Scalanie выбор локаций влияет на копирование и CSV. KPI имеет XLSX-экспорт с выделением норм. Экспорт не изменяет исходный Excel.","en":"RET Tables 1/2 use tab-separated copy. MP Scalanie selection affects Copy and CSV. KPI provides XLSX exports with norm indicators. Export does not modify the source workbook.","uk":"У RET Таблиці 1/2 копіюються через табуляцію. В MP Scalanie вибір локацій впливає на копіювання й CSV. KPI має XLSX-експорт з індикаторами норм. Експорт не змінює джерело."},"source":"js/app.js: geekCopyT1Values, geekCopyGroup, kpiExportGlobalXlsx; README.pl.md","related":[]},{"id":"saved-files","title":{"pl":"Menedżer zapisanych plików","ru":"Менеджер сохранённых файлов","en":"Saved files manager","uk":"Менеджер збережених файлів"},"basic":{"pl":"Na stronie głównej, pod kafelkami modułów, znajdziesz panel „Zapisane w przeglądarce”. To miejsce do sprawdzania, jakie pliki Excel są zachowane na tym urządzeniu. Naciśnij „Szczegóły”, aby rozwinąć listę.","ru":"На главной странице под модулями находится блок «Сохранено в браузере». Здесь видно, какие Excel сохранены на этом устройстве. Нажми «Подробнее», чтобы раскрыть список.","en":"On the home page, below the module cards, find “Saved in browser”. It shows which Excel files are saved on this device. Select “Details” to expand the list.","uk":"На головній сторінці під модулями є блок «Збережено в браузері». Тут видно, які файли Excel збережено на цьому пристрої. Натисни «Докладніше», щоб розкрити список."},"tech":{"pl":"Panel pokazuje liczbę zapisanych plików, gotowych i oczekujących na odtworzenie oraz sumę znanych rozmiarów. Każdy wpis zawiera moduł, nazwę pliku, datę zapisania, rozmiar (jeżeli jest znany), status i przycisk „Usuń”. Data „Dodano” pochodzi z chwili zapisu pliku w przeglądarce. Ponowne wczytanie pliku w tym samym module nadpisuje ten zapis i aktualizuje datę: to niekoniecznie pierwsza data w historii pliku. Starsze wpisy bez daty pokażą „Data niedostępna”. Dane są lokalne: inna przeglądarka lub inne urządzenie nie udostępnia tej samej listy. Większość plików jest przechowywana w IndexedDB (magazyny files i fileMeta), natomiast Grafik pracowników w localStorage.","ru":"Панель показывает количество сохранённых, готовых и ожидающих файлов, а также суммарный известный размер. У каждого файла указаны модуль, название, дата сохранения, размер (если известен), статус и кнопка «Удалить». Дата «Добавлен» берётся из момента сохранения в браузере. Если повторно загрузить файл для того же модуля, запись заменится и дата обновится: это не обязательно дата самой первой загрузки за всё время. Для старых записей без даты появится «Дата неизвестна». Данные локальные: другой браузер или устройство не увидит этот список. Основные Excel хранятся в IndexedDB (files и fileMeta), а Grafik pracowników отдельно в localStorage.","en":"The panel displays the number of saved, ready and queued files plus their combined known size. Every entry shows its module, filename, saved date, size (if available), status and a Remove button. The “Added” date is the browser save timestamp. Reloading a file into the same module replaces the entry and updates this date; it is not necessarily the first-ever import date. Older entries without a date show “Date unavailable”. Files are local to this browser and device. Most workbooks are stored in IndexedDB (files and fileMeta); Grafik pracowników uses localStorage separately.","uk":"Панель показує кількість збережених, готових і тих, що очікують, файлів, а також їхній сумарний відомий розмір. Для кожного файлу вказано модуль, назву, дату збереження, розмір (якщо відомий), статус і кнопку «Видалити». Дата «Додано» означає час збереження в браузері. Повторне завантаження файлу до того самого модуля замінює запис та оновлює дату: це не обов’язково найперша дата в історії. Старі записи без дати відображають «Дата недоступна». Дані локальні для цього браузера й пристрою. Більшість Excel зберігається в IndexedDB (files і fileMeta), а Grafik pracowników окремо в localStorage."},"source":"index.html: mr-memory-panel; js/app.js: mrMemoryItems, mrFilePut, MR_FILES_STORE, MR_META_STORE, pracownicySave","related":[]},{"id":"restore-queue","title":{"pl":"Kolejka przywracania i statusy","ru":"Очередь восстановления и статусы","en":"Restore queue and statuses","uk":"Черга відновлення та статуси"},"basic":{"pl":"Po uruchomieniu aplikacja odtwarza zapisane pliki Excel po kolei, aby nie przeciążać komputera. „W kolejce” oznacza oczekiwanie, „Wczytywanie” oznacza przetwarzanie, a „Gotowe” oznacza zakończone wczytanie.","ru":"При открытии приложения сохранённые Excel восстанавливаются по одному, чтобы не перегружать компьютер. «В очереди» значит, что файл ждёт, «Загрузка» означает обработку, «Готово» означает завершённое восстановление.","en":"At startup, saved Excel workbooks are restored one at a time to reduce peak load. “Queued” means waiting, “Loading” means being processed, and “Ready” means that restoration has finished.","uk":"Під час запуску збережені Excel відновлюються по черзі, щоб зменшити навантаження. «У черзі» означає очікування, «Завантаження» — обробку, а «Готово» — завершення відновлення."},"tech":{"pl":"Najpierw aplikacja odczytuje listę kluczy i małe metadane z IndexedDB, a dopiero potem pobiera właściwy plik, gdy nadejdzie jego kolej. W panelu widać aktywny moduł, postęp, pozycje oczekujące oraz błędy. „Błąd” wskazuje nieudane przywrócenie; „Wstrzymane” może oznaczać przerwaną kolejkę po zbyt długim przetwarzaniu. „Na komputerze” oznacza plik zachowany, ale pominięty przez tryb mobilny. Taki wpis nie jest usunięty. Grafik pracowników jest przechowywany osobno i ma inną ścieżkę odtwarzania. Nie interpretuj „Gotowe” jako potwierdzenia poprawności danych w raporcie: sprawdź wynik w module.","ru":"Сначала читаются только ключи и небольшие метаданные из IndexedDB. Сам Excel извлекается тогда, когда до него дошла очередь. Панель показывает обрабатываемый модуль, прогресс, ожидающие файлы и ошибки. «Ошибка» означает неудачное восстановление, «Остановлено» может означать, что очередь прервана после слишком долгой обработки. «Только на компьютере» означает, что файл сохранён, но пропущен в мобильном режиме; он не удалён. Grafik pracowników хранится отдельно и восстанавливается другим способом. «Готово» не гарантирует правильности самих данных отчёта: результат стоит проверить в модуле.","en":"The app first reads only file keys and lightweight IndexedDB metadata. The actual workbook is retrieved only when its turn starts. The panel displays the current module, progress, waiting entries and errors. “Error” means restoration failed; “Paused” may indicate that a long-running load stopped the queue. “Desktop only” means the saved file is skipped in mobile mode, not deleted. Grafik pracowników has a separate restoration path. “Ready” confirms loading, not the correctness of the report values: verify the module output.","uk":"Спочатку програма читає лише ключі та невеликі метадані з IndexedDB, а сам Excel отримує тільки тоді, коли настає його черга. Панель показує активний модуль, прогрес, очікування й помилки. «Помилка» означає невдале відновлення; «Призупинено» може означати зупинку черги після надто тривалої обробки. «Лише на комп’ютері» означає, що файл збережений, але пропущений у мобільному режимі, а не видалений. Grafik pracowników відновлюється окремо. «Готово» підтверджує завантаження, але не правильність значень звіту: перевір результат у модулі."},"source":"js/app.js: mrRestoreFiles, mrStoredKeys, mrStoredOne, mrRestoreStats, mrRestoreStatus","related":[]},{"id":"remove-saved","title":{"pl":"Usuwanie plików i czyszczenie pamięci","ru":"Удаление файлов и очистка памяти","en":"Remove files and clear memory","uk":"Видалення файлів та очищення пам’яті"},"basic":{"pl":"Aby usunąć pojedynczy zapisany Excel: strona główna → „Zapisane w przeglądarce” → „Szczegóły” → „Usuń” przy wybranym pliku → potwierdź. „Wyczyść pamięć” usuwa wszystkie zapamiętane pliki, nie tylko jeden.","ru":"Чтобы удалить один сохранённый Excel: главная → «Сохранено в браузере» → «Подробнее» → «Удалить» у нужного файла → подтверди. Кнопка «Очистить память» предназначена для удаления всех сохранённых файлов.","en":"To remove one saved Excel: Home → “Saved in browser” → “Details” → “Remove” next to the file → confirm. “Clear memory” removes every saved file, not just one.","uk":"Щоб видалити один збережений Excel: головна → «Збережено в браузері» → «Докладніше» → «Видалити» біля файлу → підтвердь. «Очистити пам’ять» видаляє всі збережені файли."},"tech":{"pl":"Usunięcie pojedynczego wpisu kasuje plik i jego metadane w IndexedDB oraz resetuje dane powiązanego modułu; inne pliki pozostają bez zmian. Usuwanie w trakcie wczytywania/przetwarzania jest zablokowane. Grafik pracowników jest usuwany z jego osobnego magazynu localStorage. „Wyczyść pamięć” usuwa wszystkie zapamiętane pliki i czyści wczytane dane modułów. Operacji nie można cofnąć: w razie potrzeby ponownie wczytaj oryginalny Excel. Jeżeli chcesz tylko ukryć listę, użyj „Ukryj”, a nie przycisku usuwania.","ru":"Удаление отдельной записи убирает Excel и его метаданные из IndexedDB и сбрасывает данные соответствующего модуля; остальные сохранённые файлы остаются. Во время загрузки или обработки удаление блокируется. Grafik pracowników удаляется из отдельного localStorage. «Очистить память» удаляет все сохранённые файлы и очищает загруженные данные модулей. Отменить удаление нельзя: потребуется заново загрузить исходный Excel. Чтобы просто свернуть список, нажми «Скрыть», а не кнопку удаления.","en":"Removing an entry deletes its workbook and metadata from IndexedDB and resets the related module data; other saved workbooks remain. Removal is disabled while that file is loading or being processed. Grafik pracowników is removed from its separate localStorage record. “Clear memory” removes all saved files and loaded module data. There is no undo: reimport the original Excel if needed. To simply collapse the list, choose “Hide” rather than Remove.","uk":"Видалення одного запису прибирає Excel і метадані з IndexedDB та скидає дані відповідного модуля; інші файли залишаються. Під час завантаження або обробки видалення заблоковане. Grafik pracowników видаляється з окремого localStorage. «Очистити пам’ять» видаляє всі збережені файли й очищує завантажені дані модулів. Скасувати видалення не можна: за потреби завантаж вихідний Excel знову. Щоб лише згорнути список, натисни «Приховати», а не кнопку видалення."},"source":"index.html: mrMemoryRemove, mrClearAllSaved; js/app.js: MR_MEMORY_RESET, mrMemoryRemove, mrClearAllSaved, pracownicyReset","related":[]},{"id":"progress-truth","title":{"pl":"Co oznacza procent wczytywania?","ru":"Что означает процент загрузки?","en":"What does the upload percentage mean?","uk":"Що означає відсоток завантаження?"},"basic":{"pl":"Wskaźnik odróżnia postęp mierzalnego przetwarzania od etapów wczytywania.","ru":"Индикатор различает измеренный прогресс обработки и условные этапы загрузки.","en":"The indicator combines measured processing progress and stage-based reading status.","uk":"Індикатор розрізняє вимірюваний прогрес і етапи читання."},"tech":{"pl":"W dużych MP i RS procent odzwierciedla przetworzony XML. W KPI, STOCK, audytach, przestojach i grafikach pracowników część postępu jest liczona z przetworzonych wierszy, lecz sam odczyt SheetJS może chwilę trwać bez aktualizacji. GODZINY MDT i Geek nadal korzystają z etapów pracy. Animowana smuga sygnalizuje aktywność, a nie gwarantuje konkretnego czasu.","ru":"Для больших MP и RS процент основан на обработанном XML. В KPI, STOCK, аудитах, простоях и графиках часть процента считается по строкам, но целостное чтение SheetJS может задерживать обновление. GODZINY MDT и Geek пока используют этапы. Бегущая подсветка означает активность, но не обещает время завершения.","en":"For large MP/RS files the percentage reflects processed XML. KPI, STOCK, audits, downtime and rosters measure row-processing portions, while SheetJS may pause during workbook reading. GODZINY MDT and Geek still report stages. The animated stripe indicates activity, not time remaining.","uk":"Для великих MP і RS процент відображає оброблений XML. KPI, STOCK, аудити, простої та графіки вимірюють частину обробки за рядками, але SheetJS може затримувати оновлення. GODZINY MDT та Geek показують етапи. Анімація означає активність, а не час до кінця."},"source":"js/workers/tote.js; js/workers/kpi.js; js/workers/stock.js; js/app.js","related":[]},{"id":"saved-inputs","title":{"pl":"Zapisane pliki, data wczytania i przywracanie","ru":"Сохранённые файлы и дата загрузки","en":"Saved files and import dates","uk":"Збережені файли й дата завантаження"},"basic":{"pl":"Mr. Robot może zapamiętywać załadowane pliki w pamięci lokalnej przeglądarki.","ru":"Mr. Robot может хранить загруженные файлы локально в браузере.","en":"Mr. Robot can retain uploaded files in browser-local storage.","uk":"Mr. Robot може зберігати завантажені файли в браузері."},"tech":{"pl":"Menadżer zapisanych plików pokazuje ostatnio wczytane źródła oraz daty i pozwala usunąć wybrane pozycje. Po ponownym uruchomieniu przywrócenie dużych raportów może chwilę potrwać. Usunięcie danych przeglądarki może też usunąć zapisane pliki; nie traktuj tego magazynu jako kopii zapasowej.","ru":"Менеджер сохранённых файлов показывает загрузки и даты, позволяет удалять отдельные источники. После перезапуска восстановление больших Excel может занять время. Очистка данных браузера может удалить сохранённые файлы, поэтому это не резервная копия.","en":"The saved-files manager shows retained sources and import dates and supports individual removal. Restoring large files after restart may take time. Clearing browser storage can delete saved inputs, so this is not a backup system.","uk":"Менеджер збережених файлів показує джерела й дати та дозволяє видаляти окремі позиції. Після перезапуску відновлення великих Excel може тривати довше. Очищення даних браузера може видалити файли; це не резервна копія."},"source":"js/app.js: saved files manager, restoration queue","related":[]}]},{"id":"assistant","emoji":"🤖","title":{"pl":"MR. BOT","ru":"MR. BOT","en":"MR. BOT","uk":"MR. BOT"},"topics":[{"id":"character","title":{"pl":"Postać i animacje","ru":"Персонаж и анимации","en":"Character and animations","uk":"Персонаж та анімації"},"basic":{"pl":"MR. BOT to animowany asystent wbudowany w aplikację. Reaguje na zdarzenia i ma własne stany ruchu.","ru":"MR. BOT — анимированный помощник внутри приложения. Он реагирует на события и меняет движения.","en":"MR. BOT is an animated assistant embedded in the app. It reacts to events and has different motion states.","uk":"MR. BOT — анімований помічник у застосунку. Реагує на події та змінює рухи."},"tech":{"pl":"js/mrbot.js steruje panelem i reakcjami. Silnik MRBotAvatar rysuje postać na canvas, obsługuje m.in. idle, think, success, error i sleep. Animacje nie zmieniają danych operacyjnych.","ru":"js/mrbot.js управляет панелью и реакциями. MRBotAvatar рисует персонажа на canvas, поддерживает idle, think, success, error, sleep и другие состояния. Анимации не влияют на рабочие данные.","en":"js/mrbot.js controls the panel and reactions. MRBotAvatar draws the character on canvas with states including idle, think, success, error and sleep. Animations do not alter operational data.","uk":"js/mrbot.js керує панеллю та реакціями. MRBotAvatar малює персонажа на canvas зі станами idle, think, success, error, sleep. Анімації не змінюють робочі дані."},"source":"js/mrbot.js: MRBotAvatar, petMood, mrbot:task","related":[]},{"id":"knowledge","title":{"pl":"Rozmowy i baza wiedzy","ru":"Диалоги и база знаний","en":"Dialogue and knowledge base","uk":"Діалоги та база знань"},"basic":{"pl":"Asystent udziela gotowych odpowiedzi offline. Szczegółowa dokumentacja pozwala przechodzić od modułu do konkretnego algorytmu.","ru":"Помощник отвечает по подготовленным офлайн-сценариям. В подробной документации можно перейти от модуля к конкретному алгоритму.","en":"The assistant uses prepared offline responses. Detailed documentation leads from a module to a specific algorithm.","uk":"Помічник відповідає за підготовленими офлайн-сценаріями. Документація веде від модуля до конкретного алгоритму."},"tech":{"pl":"Dialogi zapisano w js/mrbot-dialogue-data.js, artykuły w js/mrbot-knowledge.js. Nie jest to model AI: nie analizuje dowolnych pytań ani sam nie tworzy nowych reguł. Teksty wymagają aktualizacji, gdy zmienia się kod.\n\nSmart Context sprawdza otwartą kartę i etap pracy: brak raportu, wczytywanie, gotowy plik lub zakończoną analizę. Podpowiada właściwą instrukcję, Intelligence i OpenReports Bridge bez zmiany danych. Podpowiedzi pojawiają się tylko po otwarciu MR. BOT.","ru":"Диалоги находятся в js/mrbot-dialogue-data.js, статьи в js/mrbot-knowledge.js. Это не нейросеть: помощник не понимает произвольные вопросы и не создаёт новые правила. После изменений кода знания нужно обновлять.\n\nSmart Context определяет открытую вкладку и этап работы: нет отчёта, загрузка, файл готов или анализ выполнен. Предлагает нужную инструкцию, Intelligence и OpenReports Bridge, не изменяя данные. Подсказки появляются только при открытии MR. BOT.","en":"Dialogues live in js/mrbot-dialogue-data.js; articles live in js/mrbot-knowledge.js. This is not an AI model and cannot infer arbitrary new rules. Documentation must be updated when calculations change.\n\nSmart Context reads the active tab and workflow stage: no report, loading, file ready or analysis complete. It links to the relevant guide, Intelligence and OpenReports Bridge without changing data. Hints appear only when MR. BOT is opened.","uk":"Діалоги містяться у js/mrbot-dialogue-data.js, статті у js/mrbot-knowledge.js. Це не модель ШІ, вона не створює нових правил. Документацію треба оновлювати разом із кодом.\n\nSmart Context визначає відкриту вкладку та етап роботи: немає звіту, завантаження, файл готовий або аналіз завершено. Пропонує відповідну інструкцію, Intelligence і OpenReports Bridge без зміни даних. Підказки з’являються лише під час відкриття MR. BOT."},"source":"js/mrbot-dialogue-data.js; js/mrbot-knowledge.js; js/mrbot.js","related":[{"category":"intelligence","topic":"overview"},{"category":"obsada","topic":"overview"},{"category":"kpi","topic":"processes"}]}]},{"id":"intelligence","emoji":"✧","title":{"pl":"Intelligence","ru":"Intelligence","en":"Intelligence","uk":"Intelligence"},"featured":true,"topics":[{"id":"overview","title":{"pl":"Jak korzystać z Intelligence","ru":"Как пользоваться Intelligence","en":"How to use Intelligence","uk":"Як користуватися Intelligence"},"basic":{"pl":"Intelligence pokazuje, skąd wzięły się wyniki, i ułatwia badanie danych źródłowych. Szczegóły zależą od modułu.","ru":"Intelligence объясняет результаты и помогает исследовать исходные записи. Возможности зависят от модуля.","en":"Intelligence explains results and helps examine source records. Capabilities depend on the module.","uk":"Intelligence пояснює результати й допомагає досліджувати вихідні записи. Можливості залежать від модуля."},"tech":{"pl":"Wczytaj raport, wykonaj analizę, a następnie kliknij ✧ Intelligence lub obsługiwany wskaźnik. Przejdź do rozdziału modułu poniżej. Intelligence nie zmienia obliczeń, wyboru lokalizacji ani eksportu.","ru":"Загрузи отчёт, выполни анализ и нажми ✧ Intelligence или поддерживаемый показатель. Затем выбери нужный модуль в этой документации. Intelligence не меняет расчёты, выбор локаций или экспорт.","en":"Upload the report, run analysis, then open ✧ Intelligence or a supported metric. Choose the relevant module topic below. Intelligence does not change calculations, location selection or exports.","uk":"Завантаж звіт, запусти аналіз і відкрий ✧ Intelligence чи підтримуваний показник. Далі обери тему модуля. Intelligence не змінює обчислення, вибір локацій або експорт."},"source":"js/mrbot-intelligence.js; js/app.js","related":[]},{"id":"al","title":{"pl":"AL_AUDYT · audytorzy i przeliczenia","ru":"AL_AUDYT · аудиторы и пересчёты","en":"AL_AUDYT · auditors and recounts","uk":"AL_AUDYT · аудитори й перерахунки"},"basic":{"pl":"Poznaj kategorie, strefy, audytorów User ID i historię kolejnych przeliczeń.","ru":"Исследуй категории, зоны, аудиторов User ID и историю повторных пересчётов.","en":"Explore categories, zones, User ID auditors and recount history.","uk":"Досліджуй категорії, зони, аудиторів User ID та історію перерахунків."},"tech":{"pl":"Po analizie otwórz ✧ Intelligence. Obliczenia pozwalają prześledzić wyniki i grupy INFO do wierszy Excel. W Analityce wybieraj kategorie, strefy lub audytorów; widoczni są także audytorzy z zerową liczbą rozbieżności. Po wyborze audytora lista problemów pokazuje tylko jego Shortage/Surplus. Kliknij EAN, aby obejrzeć produkt, lokalizację, ilości i przeliczenia.","ru":"После анализа открой ✧ Intelligence. «Расчёты» позволяют проследить итоги и группы INFO до строк Excel. В «Аналитике» выбирай категории, зоны или аудиторов; аудиторы с нулём расхождений остаются видимыми. После выбора аудитора список проблем содержит только его Shortage/Surplus. Нажми EAN для подробностей товара, локации, количеств и пересчётов.","en":"After analysis, open ✧ Intelligence. Calculations trace totals and INFO groups to Excel source rows. Analytics groups by category, zone and auditor, including auditors with zero discrepancies. Selecting an auditor shows only their Shortage/Surplus records. Select an EAN for the item, location, quantities and recount details.","uk":"Після аналізу відкрий ✧ Intelligence. «Обчислення» ведуть від підсумків та INFO до рядків Excel. «Аналітика» групує категорії, зони й аудиторів, зокрема без розбіжностей. Обраний аудитор показує лише свої Shortage/Surplus. Натисни EAN для товару, локації, кількостей і перерахунків."},"source":"js/app.js","related":[]},{"id":"formatka","title":{"pl":"FORMATKA_59 · źródła wyników","ru":"FORMATKA_59 · происхождение показателей","en":"FORMATKA_59 · calculation sources","uk":"FORMATKA_59 · походження показників"},"basic":{"pl":"Wyjaśnienia wyników FORMATKA_59 na podstawie wierszy źródłowych MP2.","ru":"Разбор показателей FORMATKA_59 по исходным строкам MP2.","en":"Explain FORMATKA_59 metrics from MP2 source records.","uk":"Пояснення показників FORMATKA_59 за вихідними рядками MP2."},"tech":{"pl":"Sprawdzaj wartości z kolumn I/J/K, status Incident i to, czy dany wiersz wszedł do wyniku. Panel pokazuje przyczyny uwzględnienia lub wykluczenia oraz pozwala porównać liczby z raportem.","ru":"Смотри значения I/J/K, статус Incident и участие каждой строки в расчёте. Панель показывает причины включения и исключения и помогает сверить данные с отчётом.","en":"Inspect columns I/J/K, Incident status and source-row inclusion. See reasons for inclusion or exclusion, then reconcile figures with the report.","uk":"Переглядай колонки I/J/K, статус Incident та врахування рядків. Панель показує причини включення або виключення й допомагає звірити підсумки."},"source":"js/app.js","related":[]},{"id":"mdt","title":{"pl":"GODZINY MDT · operatorzy i lokalizacje 1/1","ru":"GODZINY MDT · операторы и локации 1/1","en":"GODZINY MDT · operators and 1/1 locations","uk":"GODZINY MDT · оператори та локації 1/1"},"basic":{"pl":"Badanie pracy osób odkładających towar: kto, co, gdzie i w jakiej ilości rozłożył.","ru":"Исследование размещения: кто, что, куда и в каком количестве разложил.","en":"Inspect warehouse placements: who put which items where, and how many.","uk":"Дослідження розміщень: хто, що, куди та в якій кількості розклав."},"tech":{"pl":"LOGIN oznacza zapisany identyfikator operatora, QUANTITY ilość rozłożoną, a STOCK aktualny stan lokalizacji. W Intelligence otwórz listę operatorów, profil z zakładkami Przegląd / Rozmieszczenia / Obserwacje oraz szczegóły EAN i wierszy źródłowych. Link z profilu prowadzi do istniejącej karty pracownika KPI (jeśli wczytano dane); po zamknięciu wrócisz do tego samego miejsca. Zgodność ilości sama w sobie nie potwierdza jednego operatora: liczba różnych LOGIN jest weryfikowana osobno. SINSAY wyklucza MP1 i MP3, MOHITO zachowuje swoje ustawienia.","ru":"LOGIN показывает оператора, QUANTITY количество размещённого товара, STOCK актуальное заполнение локации. В Intelligence открывай список операторов, профиль с вкладками «Обзор / Размещения / Наблюдения», EAN и исходные строки. Из профиля можно открыть существующую карточку KPI, если загружена база сотрудников, и вернуться к тому же месту после закрытия. Совпадение количеств само по себе не доказывает одного оператора: разные LOGIN проверяются отдельно. SINSAY исключает MP1 и MP3, MOHITO использует свои настройки.","en":"LOGIN identifies the recorded operator; QUANTITY is placed stock and STOCK the current location quantity. Intelligence offers operators, Overview / Placements / Observations profiles, EAN details and source rows. Where employee data is loaded, open the existing KPI employee card and return to the same place after closing. Matching quantities alone does not prove a single operator; distinct LOGIN values are checked separately. SINSAY excludes MP1 and MP3; MOHITO follows its own settings.","uk":"LOGIN позначає оператора, QUANTITY розміщену кількість, STOCK поточний залишок локації. Intelligence містить операторів, профілі «Огляд / Розміщення / Спостереження», EAN і вихідні рядки. За наявності даних можна перейти до картки працівника KPI й повернутися на те саме місце. Збіг кількостей не доводить одного оператора: різні LOGIN перевіряються окремо. SINSAY виключає MP1 і MP3, MOHITO використовує власні налаштування."},"source":"js/app.js","related":[]},{"id":"kons","title":{"pl":"Konsolidacja · możliwości EAN","ru":"Konsolidacja · возможности EAN","en":"Konsolidacja · EAN opportunities","uk":"Konsolidacja · можливості EAN"},"basic":{"pl":"Przeglądaj kandydatów EAN, progi i powtórzone adresy.","ru":"Изучай кандидатов EAN, пороги и повторяющиеся адреса.","en":"Explore EAN candidates, thresholds and repeated locations.","uk":"Досліджуй кандидатів EAN, пороги й повторні адреси."},"tech":{"pl":"Intelligence wskazuje EAN blisko progu, pokazuje alternatywne wartości procentowe i priorytety do przeglądu. Symulacje nie zmieniają faktycznych filtrów, listy lokalizacji ani eksportu.","ru":"Intelligence показывает EAN рядом с порогом, альтернативные процентные сценарии и приоритеты проверки. Симуляции не меняют реальные фильтры, список локаций и экспорт.","en":"Intelligence highlights near-threshold EANs, alternate percentage scenarios and review priorities. Simulations do not alter actual filters, selected locations or exports.","uk":"Intelligence показує EAN поблизу порогу, альтернативні відсоткові сценарії та пріоритети. Симуляції не змінюють фільтри, вибір локацій або експорт."},"source":"js/app.js","related":[]},{"id":"other","title":{"pl":"KPI, AUDYT GEEK, STOCK i Przestoje","ru":"KPI, AUDYT GEEK, STOCK и Przestoje","en":"KPI, AUDYT GEEK, STOCK and Przestoje","uk":"KPI, AUDYT GEEK, STOCK і Przestoje"},"basic":{"pl":"Sposób otwierania i zakres wyjaśnień zależą od modułu.","ru":"Способ открытия и глубина объяснений зависят от модуля.","en":"Availability and depth of explanations vary by module.","uk":"Спосіб відкриття та глибина пояснень залежать від модуля."},"tech":{"pl":"KPI: kliknij obsługiwany ITEMS PER HOUR, aby zobaczyć sztuki, czas i normę. AUDYT GEEK: kliknij obsługiwany wskaźnik Tabeli 1 lub RET Tabeli 2, aby zobaczyć wiersze, filtry i decyzje. STOCK i Przestoje zachowują własne wyjaśnienia wyników.\n\nPo wybraniu ITEMS PER HOUR pokazane są login, proces, ilość, czas, norma i odchylenie; zaokrąglony czas nie służy do ponownego liczenia wydajności. Przestoje: liczba przerw, pary wpisów, suma, maksimum, średnia i ustawiony próg 8–300 minut.","ru":"KPI: нажми поддерживаемый показатель ITEMS PER HOUR для количества, времени и нормы. AUDYT GEEK: выбери показатель таблицы 1 или RET таблицы 2, чтобы увидеть исходные строки, фильтры и решения. STOCK и Przestoje сохраняют собственные объяснения результатов.\n\nПри выборе ITEMS PER HOUR отображаются LOGIN, процесс, количество, время, норма и отклонение; производительность не пересчитывается из округлённого времени. Przestoje: число простоев, пары записей, сумма, максимум, среднее и порог 8–300 минут.","en":"KPI: select a supported ITEMS PER HOUR metric for items, time and threshold. AUDYT GEEK: select a supported Table 1 or RET Table 2 metric to inspect source rows, filters and inclusion decisions. STOCK and Przestoje retain their own result explanations.\n\nSelecting ITEMS PER HOUR shows login, process, items, time, threshold and deviation; performance is not recalculated from rounded time. Przestoje: downtime count, entry pairs, total, maximum, average and the selected 8–300 minute threshold.","uk":"KPI: обери підтримуваний ITEMS PER HOUR для кількості, часу та норми. AUDYT GEEK: натисни показник таблиці 1 або RET таблиці 2 для рядків, фільтрів і рішень. STOCK і Przestoje зберігають власні пояснення.\n\nПри виборі ITEMS PER HOUR показано LOGIN, процес, кількість, час, норму й відхилення; продуктивність не перераховується за округленим часом. Przestoje: кількість простоїв, пари записів, сума, максимум, середнє й поріг 8–300 хвилин."},"source":"js/mrbot-intelligence.js","related":[]},{"id":"stock","title":{"pl":"STOCK · zamknięcia i powtórzenia","ru":"STOCK · закрытия и повторы","en":"STOCK · closures and repeats","uk":"STOCK · закриття і повтори"},"basic":{"pl":"Dwie zakładki Intelligence: Przegląd zamknięć według MP1/MP2/MP3 oraz powtarzające się zamknięcia tych samych lokalizacji.","ru":"Две вкладки Intelligence: обзор закрытий по MP1/MP2/MP3 и повторные закрытия тех же локаций.","en":"Two Intelligence tabs: closure overview by MP1/MP2/MP3 and repeated closures of the same location.","uk":"Дві вкладки Intelligence: огляд закриттів за MP1/MP2/MP3 та повторні закриття тих самих локацій."},"tech":{"pl":"W MP → Audyt → STOCK wczytaj ECM_PICK_Lacks_during_picking i otwórz ✧ Intelligence przy wyborze okresów. Przegląd zamknięć liczy osobno wiersze (zdarzenia) oraz unikatowe lokalizacje dla MP1, MP2, MP3 i pozostałych. Wybierz cały plik lub godziny zaznaczone w standardowym STOCK. Przełącz niezależnie wykluczenia loginów PKECOM i rozpoczynających się od S. Liczniki wykluczeń uwzględniają wybrane godziny i obszar MP. W Powtórzeniach widzisz lokalizacje z co najmniej dwoma zdarzeniami, ten sam/różne EAN i historię TIME, LOGIN, QUANTITY, LACK, DEFICIENCY, KOMNAM. Domyślnie analizowane są wybrane godziny STOCK; ostatnie ustawienia analizy są zapamiętywane lokalnie. Możesz przywrócić ustawienia domyślne. Powtórzenia rozwijają historię zdarzeń na osi czasu. Powtórzenie nie dowodzi błędu operatora ani fizycznej obecności towaru. Inteligencja nie modyfikuje standardowego generowania listy, filtrów audytu ani eksportu.","ru":"Открой MP → Audyt → STOCK, загрузи ECM_PICK_Lacks_during_picking и нажми ✧ Intelligence рядом с выбором часов. «Обзор закрытий» отдельно считает строки (события) и уникальные локации для MP1, MP2, MP3 и остальных. Можно анализировать весь файл или выбранные часы STOCK, независимо исключать PKECOM и логины на S. Счётчики исключений учитывают выбранные часы и область MP. Во вкладке «Повторы» показаны локации с двумя или более закрытиями, одинаковые/разные EAN и история TIME, LOGIN, QUANTITY, LACK, DEFICIENCY, KOMNAM. По умолчанию анализируются выбранные часы STOCK; последние фильтры сохраняются локально. Настройки можно сбросить. В «Повторах» история раскрывается в хронологическом порядке. Повтор не доказывает ошибку сотрудника или наличие товара при аудите. Стандартные фильтры STOCK, список для проверки и экспорт не изменяются.","en":"Open MP → Audyt → STOCK, load ECM_PICK_Lacks_during_picking, and select ✧ Intelligence next to hour selection. Closure overview distinguishes event rows from unique locations for MP1, MP2, MP3 and other locations. Analyze the entire workbook or the hours selected in STOCK; toggle PKECOM and S-login exclusions independently. Exclusion counts reflect the selected hours and MP area. Repeats shows locations with two or more closure events, same/different EANs and event history: TIME, LOGIN, QUANTITY, LACK, DEFICIENCY, KOMNAM. Selected STOCK hours are the default; the latest analysis preferences are remembered locally and can be reset. Repeats expands the event timeline. Repeat closures are not proof of an operator mistake or physical stock. Normal STOCK filtering, audit lists and exports are unchanged.","uk":"Відкрий MP → Audyt → STOCK, завантаж ECM_PICK_Lacks_during_picking та натисни ✧ Intelligence біля вибору годин. «Огляд закриттів» окремо підраховує події та унікальні локації MP1, MP2, MP3 й інших. Обери весь файл або вибрані години STOCK; перемикай виключення PKECOM і логінів на S незалежно. Лічильники виключень враховують вибрані години та область MP. «Повтори» показують локації з двома чи більше закриттями, однакові/різні EAN та історію TIME, LOGIN, QUANTITY, LACK, DEFICIENCY, KOMNAM. Типово аналізуються вибрані години STOCK, останні фільтри зберігаються локально та можуть бути скинуті. У «Повторах» події показуються за часом. Повтор не доводить помилку працівника або наявність товару. Стандартні фільтри, списки та експорт STOCK не змінюються."},"source":"js/stock-intelligence.js; js/workers/stock.js; js/app.js","related":[]}]},{"id":"openreports","emoji":"🔌","title":{"pl":"OpenReports Bridge","ru":"OpenReports Bridge","en":"OpenReports Bridge","uk":"OpenReports Bridge"},"featured":true,"topics":[{"id":"overview","title":{"pl":"Do czego służy Bridge?","ru":"Для чего нужен Bridge?","en":"What does Bridge do?","uk":"Для чого потрібен Bridge?"},"basic":{"pl":"Bridge łączy moduły Mr. Robot z otwartą sesją OpenReports przez rozszerzenie przeglądarki.","ru":"Bridge связывает модули Mr. Robot с уже открытой сессией OpenReports через расширение браузера.","en":"Bridge connects Mr. Robot modules to an already open OpenReports session through a browser extension.","uk":"Bridge з’єднує модулі Mr. Robot із вже відкритою сесією OpenReports через розширення браузера."},"tech":{"pl":"To dodatkowa funkcja pobierania raportów. Korzysta z sesji użytkownika już zalogowanego w OpenReports: nie wpisuj hasła w Mr. Robot. Bridge nie zastępuje ręcznego wczytywania plików i nie zmienia obliczeń modułów.","ru":"Это дополнительный способ получать отчёты. Используется уже авторизованная вкладка OpenReports: вводить пароль в Mr. Robot не нужно. Bridge не отменяет ручную загрузку файлов и не меняет расчёты модулей.","en":"This optional report workflow uses your existing authenticated OpenReports tab. No password entry in Mr. Robot is required. Manual file upload remains available and module calculations are unchanged.","uk":"Це додатковий спосіб отримувати звіти через уже авторизовану вкладку OpenReports. Пароль у Mr. Robot вводити не потрібно. Ручне завантаження файлів доступне, обчислення незмінні."},"source":"js/bridge-setup.js","related":[{"category":"openreports","topic":"sharepoint"}]},{"id":"install","title":{"pl":"Instalacja w Edge i Chrome","ru":"Установка в Edge и Chrome","en":"Install in Edge and Chrome","uk":"Встановлення в Edge та Chrome"},"basic":{"pl":"Obsługiwane przeglądarki to Microsoft Edge i Google Chrome.","ru":"Поддерживаются Microsoft Edge и Google Chrome.","en":"Supported browsers are Microsoft Edge and Google Chrome.","uk":"Підтримуються Microsoft Edge та Google Chrome."},"tech":{"pl":"Otwórz Ustawienia → OpenReports Bridge. Zobaczysz instrukcję instalacji odpowiednią dla wykrytej przeglądarki, link lub kroki konfiguracji oraz oznaczenie wersji rozszerzenia. Po instalacji odśwież Mr. Robot i sprawdź połączenie. Nie korzystaj z instrukcji dla Firefox ani Yandex.\n\nRozpakuj ZIP rozszerzenia w stałym folderze, otwórz edge://extensions lub chrome://extensions, włącz tryb dewelopera i użyj „Załaduj rozpakowane”. Następnie odśwież Mr. Robot.","ru":"Открой Настройки → OpenReports Bridge. Там находятся инструкции для обнаруженного браузера, установка расширения и информация о его версии. После установки обнови Mr. Robot и проверь соединение. Инструкции для Firefox и Yandex не поддерживаются.\n\nРаспакуй ZIP расширения в постоянную папку. Открой edge://extensions или chrome://extensions, включи режим разработчика и выбери «Загрузить распакованное». Затем обнови Mr. Robot.","en":"Open Settings → OpenReports Bridge for browser-specific installation instructions, extension link or setup steps, and its version. Refresh Mr. Robot after installation and check the connection. Firefox and Yandex are not supported.\n\nUnpack the extension ZIP into a permanent folder. Visit edge://extensions or chrome://extensions, enable Developer mode and choose Load unpacked, then refresh Mr. Robot.","uk":"Відкрий Налаштування → OpenReports Bridge для інструкцій свого браузера, встановлення розширення та відомостей про його версію. Після встановлення онови Mr. Robot і перевір з’єднання. Firefox і Yandex не підтримуються.\n\nРозпакуй ZIP розширення до постійної папки. Відкрий edge://extensions або chrome://extensions, увімкни режим розробника та обери «Завантажити розпаковане». Потім онови Mr. Robot."},"source":"js/bridge-setup.js; index.html","related":[]},{"id":"use","title":{"pl":"Pobieranie raportu","ru":"Как получить отчёт","en":"Retrieve a report","uk":"Як отримати звіт"},"basic":{"pl":"Raport wybiera się z modułu, w którym ma być użyty.","ru":"Отчёт выбирается из модуля, в котором будет использоваться.","en":"Choose the report in the module that needs it.","uk":"Обирай звіт у модулі, де його використаєш."},"tech":{"pl":"Otwórz kartę OpenReports i zaloguj się samodzielnie. W Mr. Robot uruchom pobieranie odpowiedniego raportu, gdy moduł udostępnia Bridge. Rozszerzenie pracuje na otwartej karcie; ścieżka na stronie zaczyna się od Reports → ECM_Warehouse. Dla GODZINY MDT używany jest ECM_STOCK_Items_after_receiving. Zaczekaj na zakończenie pobierania dużych plików i sprawdź, czy wybrano właściwy raport.\n\nObsługiwane raporty: MP: ECM_AI_Audit (AL_AUDYT / FORMATKA_59), ECM_STOCK_Items_after_receiving (GODZINY MDT), ECM_PICK_Lacks_during_picking (STOCK), ECM_STOCK_MP_and_on_the_floor (Baza MP/RS). KPI: Audit_ECM_KPI, Pick_ECM_KPI (Scalanie, Pick type = Pick Scal), Storage_RSORT_ECM_KPI, NADWE_VAS_ECM_KPI. Dla KPI ustaw daty From / To i czas; moduły mają osobne parametry. Właściwy plik trafia do odpowiedniego modułu.","ru":"Открой вкладку OpenReports и авторизуйся самостоятельно. В модуле Mr. Robot запусти получение нужного отчёта, если доступен Bridge. Расширение работает с открытой вкладкой; навигация начинается Reports → ECM_Warehouse. Для GODZINY MDT нужен ECM_STOCK_Items_after_receiving. Дождись завершения большой загрузки и проверь, что выбран правильный отчёт.\n\nПоддерживаемые отчёты: MP: ECM_AI_Audit (AL_AUDYT / FORMATKA_59), ECM_STOCK_Items_after_receiving (GODZINY MDT), ECM_PICK_Lacks_during_picking (STOCK), ECM_STOCK_MP_and_on_the_floor (Baza MP/RS). KPI: Audit_ECM_KPI, Pick_ECM_KPI (Scalanie, Pick type = Pick Scal), Storage_RSORT_ECM_KPI, NADWE_VAS_ECM_KPI. Для KPI укажи даты From / To и время; отдельные отчёты имеют свои параметры. Файл должен попадать в соответствующий модуль.","en":"Open and sign in to an OpenReports tab yourself. In a supported Mr. Robot module, request its report via Bridge. The extension uses the open tab and navigates from Reports → ECM_Warehouse. GODZINY MDT uses ECM_STOCK_Items_after_receiving. Allow large downloads to finish and verify that the correct report was selected.\n\nSupported reports: MP: ECM_AI_Audit (AL_AUDYT / FORMATKA_59), ECM_STOCK_Items_after_receiving (GODZINY MDT), ECM_PICK_Lacks_during_picking (STOCK), ECM_STOCK_MP_and_on_the_floor (shared MP/RS base). KPI: Audit_ECM_KPI, Pick_ECM_KPI (Scalanie, Pick type = Pick Scal), Storage_RSORT_ECM_KPI, NADWE_VAS_ECM_KPI. KPI report requests require From / To dates and times; individual reports have their own parameters. Each workbook must be delivered to its matching module.","uk":"Відкрий вкладку OpenReports й увійди самостійно. У підтримуваному модулі Mr. Robot запусти запит звіту через Bridge. Розширення працює з відкритою вкладкою, починаючи Reports → ECM_Warehouse. GODZINY MDT використовує ECM_STOCK_Items_after_receiving. Дочекайся завершення завантаження й перевір вибір звіту.\n\nПідтримувані звіти: MP: ECM_AI_Audit (AL_AUDYT / FORMATKA_59), ECM_STOCK_Items_after_receiving (GODZINY MDT), ECM_PICK_Lacks_during_picking (STOCK), ECM_STOCK_MP_and_on_the_floor (база MP/RS). KPI: Audit_ECM_KPI, Pick_ECM_KPI (Scalanie, Pick type = Pick Scal), Storage_RSORT_ECM_KPI, NADWE_VAS_ECM_KPI. Для KPI вкажи дати From / To і час; звіти мають власні параметри. Кожен файл має потрапляти до відповідного модуля."},"source":"js/app.js; js/bridge-setup.js","related":[]},{"id":"troubleshoot","title":{"pl":"Gdy Bridge nie działa","ru":"Если Bridge не работает","en":"Troubleshooting Bridge","uk":"Якщо Bridge не працює"},"basic":{"pl":"Najpierw sprawdź kartę OpenReports, rozszerzenie i przeglądarkę.","ru":"Сначала проверь вкладку OpenReports, расширение и браузер.","en":"First check the OpenReports tab, extension and browser.","uk":"Спершу перевір вкладку OpenReports, розширення й браузер."},"tech":{"pl":"Sprawdź: 1) używasz Edge lub Chrome; 2) rozszerzenie jest zainstalowane i aktywne; 3) karta OpenReports jest otwarta i użytkownik zalogowany; 4) raport ma poprawny typ; 5) duży plik zakończył pobieranie. Jeśli połączenie nie jest dostępne, skorzystaj ze zwykłego wczytania Excel i ponownie przejdź przez instrukcję w ustawieniach.\n\nPo zmianie rozszerzenia przeładuj je na stronie zarządzania dodatkami i odśwież kartę aplikacji. Przy automatycznym imporcie udziel dostępu do Downloads/MrRobot/OpenReports. Numerowane kopie (1), (2) muszą nadal odpowiadać wybranemu raportowi.","ru":"Проверь: 1) Edge или Chrome; 2) расширение установлено и включено; 3) OpenReports открыт и ты авторизован; 4) выбрана нужная разновидность отчёта; 5) загрузка большого файла завершена. Если соединения нет, используй обычную загрузку Excel и повторно открой инструкцию в настройках.\n\nПосле изменения расширения перезагрузи его на странице управления расширениями и обнови приложение. Для автоимпорта предоставь доступ к Downloads/MrRobot/OpenReports. Копии файлов с (1), (2) должны соответствовать выбранному типу отчёта.","en":"Check: 1) Edge or Chrome; 2) installed and enabled extension; 3) an open signed-in OpenReports tab; 4) correct report type; 5) completed download, especially for large files. If unavailable, use normal Excel upload and revisit Settings instructions.\n\nAfter updating the extension, reload it on the extensions page and refresh the app. For automatic import, authorize Downloads/MrRobot/OpenReports. Numbered copies such as (1) and (2) must still match the selected report.","uk":"Перевір: 1) Edge або Chrome; 2) розширення встановлене й увімкнене; 3) вкладка OpenReports відкрита й авторизована; 4) обрано правильний звіт; 5) велике завантаження завершилося. За відсутності з’єднання скористайся звичайним Excel і повторно відкрий інструкцію в налаштуваннях.\n\nПісля зміни розширення перезавантаж його на сторінці керування та онови застосунок. Для автоімпорту надай доступ до Downloads/MrRobot/OpenReports. Копії з (1), (2) також мають відповідати обраному звіту."},"source":"js/bridge-setup.js","related":[]},{"id":"sharepoint","title":{"pl":"SharePoint w Obsada: odświeżanie i ograniczenia","ru":"SharePoint в Obsada: обновление и ограничения","en":"SharePoint in Obsada: refresh and limits","uk":"SharePoint в Obsada: оновлення й межі"},"basic":{"pl":"Bridge może odświeżyć uprawniony plik Excel używany jako źródło STAN; nie zmienia go w edytowalną bazę Planowanie.","ru":"Bridge может обновить разрешённый Excel-источник STAN, но не превращает его в редактируемую базу Planowanie.","en":"Bridge can refresh an authorized Excel source for STAN; it does not turn it into the editable planning database.","uk":"Bridge може оновити дозволене джерело Excel для STAN, але це не редагована база Planowanie."},"tech":{"pl":"W Obsada wybierz konfigurację przy Grafik procesowy, podaj obsługiwany link i przyznaj wymagane uprawnienia. Możliwy jest także ręczny import XLSX. Odświeżenie nie uruchamia stałej synchronizacji i nie wprowadza zmian do pliku online. Importowaną Historię i lokalny Planowanie należy rozróżniać.","ru":"В Obsada открой настройки возле Grafik procesowy, укажи поддерживаемую ссылку и предоставь нужные разрешения. Возможна ручная загрузка XLSX. Обновление не включает постоянную синхронизацию и не правит файл онлайн. Не путай импорт Historia и локальную Planowanie.","en":"Configure the source by Grafik procesowy in Obsada, enter a supported link and grant required permissions. Manual XLSX import is also possible. Refresh does not enable continuous synchronization or edit the online workbook. Distinguish imported Historia from local Planowanie.","uk":"В Obsada налаштуй джерело біля Grafik procesowy, введи підтримуване посилання й надай дозволи. Можна імпортувати XLSX вручну. Оновлення не є постійною синхронізацією та не змінює онлайн-файл. Розрізняй імпорт Historia й локальний Planowanie."},"related":[{"category":"obsada","topic":"source"},{"category":"obsada","topic":"database"}],"sources":["index.html","README.md"]},{"id":"offline","title":{"pl":"Bridge i PWA: kiedy potrzebny internet","ru":"Bridge и PWA: когда нужен интернет","en":"Bridge and PWA: when internet is needed","uk":"Bridge та PWA: коли потрібен інтернет"},"basic":{"pl":"Po pierwszym wczytaniu aplikacja może działać offline z zapisanymi lokalnymi danymi. Nowe raporty WMS i SharePoint wymagają połączenia i uprawnień.","ru":"После первой загрузки PWA может работать офлайн с локально сохранёнными данными. Для новых отчётов WMS и SharePoint нужны сеть и права доступа.","en":"After first load, cached PWA functions may work offline with local data. Fresh WMS and SharePoint reports require network access and permissions.","uk":"Після першого завантаження PWA може працювати офлайн з локальними даними. Для нових звітів WMS та SharePoint потрібні мережа й дозволи."},"tech":{"pl":"Instalacja PWA i instalacja rozszerzenia Bridge to różne operacje. Pierwsze otwarcie lub aktualizacja PWA wymaga internetu. OpenReports Bridge działa w obsługiwanej przeglądarce jako osobno instalowane rozszerzenie; nie przejmuje loginów ani nie nadaje dodatkowych uprawnień do WMS.","ru":"Установка PWA и установка расширения Bridge независимы. Первый запуск и обновления PWA требуют интернета. OpenReports Bridge устанавливается отдельно в поддерживаемом браузере и не выдаёт новые права WMS.","en":"PWA installation and Bridge extension installation are separate. The first app load and updates need internet. OpenReports Bridge is a separately installed browser extension and does not grant WMS permissions.","uk":"Встановлення PWA та розширення Bridge окремі. Перший запуск і оновлення PWA потребують інтернету. OpenReports Bridge встановлюється як розширення браузера й не надає додаткових прав WMS."},"related":[{"category":"system","topic":"offline"},{"category":"openreports","topic":"install"}],"sources":["README.md","extension/openreports-bridge/README_INSTALL.md"]}]},{"id":"obsada","emoji":"👥","title":{"pl":"Obsada · planowanie i historia","ru":"Obsada · планирование и история","en":"Obsada · planning and history","uk":"Obsada · планування та історія"},"topics":[{"id":"overview","title":{"pl":"Pięć widoków Obsada","ru":"Пять вкладок Obsada","en":"Five Obsada tabs","uk":"П’ять вкладок Obsada"},"basic":{"pl":"Obsada obejmuje: Obsada, Planowanie, Plan na jutro, Historia i Analiza. Źródłowy STAN oraz lokalna baza planowania pełnią różne role.","ru":"В Obsada пять вкладок: Obsada, Planowanie, Plan na jutro, Historia и Analiza. Источник STAN и локальная база планирования выполняют разные задачи.","en":"Obsada has five tabs: Obsada, Planowanie, Plan na jutro, Historia and Analiza. Source STAN and the local planning database serve different purposes.","uk":"В Obsada п’ять вкладок: Obsada, Planowanie, Plan na jutro, Historia та Analiza. STAN і локальна база планування мають різні ролі."},"tech":{"pl":"Obsada pokazuje stan obsady według daty i godziny. Planowanie tworzy przydziały godzinowe. Plan na jutro przygotowuje zestawienie na kolejny dzień. Historia łączy lokalne przydziały z importowanymi zapisami i wskazuje rozbieżności. Analiza podsumowuje godziny, dni i procesy. Zapis lokalny nie zmienia źródłowego pliku SharePoint.","ru":"Obsada показывает расстановку по выбранным дате и часу. Planowanie записывает почасовые назначения. Plan na jutro готовит списки следующего дня. Historia объединяет локальные назначения и импортированную историю, показывая расхождения. Analiza суммирует часы, рабочие дни и процессы. Локальные изменения не редактируют исходный файл SharePoint.","en":"Obsada shows staffing at a chosen date and hour. Planowanie stores hourly assignments. Plan na jutro prepares the next-day roster. Historia reconciles local and imported history and shows discrepancies. Analiza summarizes hours, working days and processes. Local edits do not edit the source SharePoint workbook.","uk":"Obsada показує розстановку на дату й годину. Planowanie зберігає погодинні призначення. Plan na jutro готує завтрашній список. Historia поєднує локальні та імпортовані записи й показує розбіжності. Analiza підсумовує години, дні та процеси. Локальні зміни не редагують SharePoint."},"sources":["index.html","js/obsada-planner.js"],"related":[{"category":"kpi","topic":"processes"}]},{"id":"source","title":{"pl":"Grafik procesowy i źródłowy STAN","ru":"Grafik procesowy и STAN","en":"Grafik procesowy and source STAN","uk":"Grafik procesowy та STAN"},"basic":{"pl":"Źródło grafikowe można odświeżyć przez uprawnione połączenie SharePoint albo wczytać plik XLSX ręcznie. Nie jest to baza do edycji przydziałów.","ru":"Исходный график можно обновить через разрешённое подключение SharePoint или загрузить XLSX вручную. Это не база для редактирования назначений.","en":"Refresh the source schedule using authorized SharePoint access, or manually load an XLSX. It is not the editable assignment database.","uk":"Вихідний графік можна оновити через дозволений SharePoint або завантажити XLSX вручну. Це не редагована база призначень."},"tech":{"pl":"Konfigurację łącza znajdziesz obok „Grafik procesowy”. Odświeżanie jest działaniem użytkownika, nie stałą synchronizacją na żywo. Porównanie STAN pokazuje różnice; wybór danych wymaga sprawdzenia przed zastosowaniem. Dostęp do SharePoint wymaga własnych uprawnień.","ru":"Настройки ссылки находятся возле «Grafik procesowy». Обновление выполняется пользователем, это не постоянная живая синхронизация. Сверка STAN показывает различия, выбор нужно проверить перед применением. Требуются собственные права доступа к SharePoint.","en":"The source-link configuration is next to “Grafik procesowy”. Refresh is user-initiated, not continuous live sync. STAN comparison displays differences for review before applying choices. SharePoint requires existing permissions.","uk":"Налаштування джерела поруч із «Grafik procesowy». Оновлення запускає користувач, це не постійна синхронізація. Звірка STAN показує різниці для перевірки. Потрібен власний доступ до SharePoint."},"related":[{"category":"openreports","topic":"overview"}],"sources":["index.html","js/obsada-planner.js"]},{"id":"planning","title":{"pl":"Planowanie: godziny, zmiany i procesy","ru":"Планирование: часы, смены, процессы","en":"Planowanie: hours, shifts and processes","uk":"Planowanie: години, зміни й процеси"},"basic":{"pl":"Wybierz dzień, zmianę i godzinę, następnie przypisz pracownika do procesu. Jedna osoba może zmieniać proces w ciągu zmiany.","ru":"Выбери день, смену и час, затем назначь человека на процесс. В течение смены сотрудник может переходить между процессами.","en":"Choose the day, shift and hour, then assign a person to a process. A worker can change processes during one shift.","uk":"Обери день, зміну та годину, тоді признач працівника до процесу. Протягом зміни процес може змінюватися."},"tech":{"pl":"Dostępne kody zmian w logice planowania: 06–18, 18–06, 06–16, 16–02, 06–14, 14–22. Godzinowe sloty zapisują datę zmiany, kod zmiany, login, proces i godzinę. Zmiany nocne przechodzą przez północ; data zmiany to data rozpoczęcia. Zmiana procesu nadpisuje przydziały w wybranym zakresie pracownika, nie całą bazę.","ru":"Логика планирования поддерживает смены 06–18, 18–06, 06–16, 16–02, 06–14, 14–22. Каждая часовая запись содержит дату смены, смену, логин и процесс. Ночные смены переходят через полночь, дата смены относится к началу. Переназначение меняет выбранный временной интервал человека, а не всю базу.","en":"Supported shift codes: 06–18, 18–06, 06–16, 16–02, 06–14 and 14–22. Hourly slots store shift date, shift code, login and process. Overnight shifts cross midnight; the shift date is the starting date. Reassignment replaces the worker’s selected hourly range, not the entire database.","uk":"Підтримувані зміни: 06–18, 18–06, 06–16, 16–02, 06–14, 14–22. Погодинний запис містить дату зміни, зміну, логін і процес. Нічні зміни переходять через північ, а дата належить початку зміни. Перепризначення змінює вибрані години працівника."},"sources":["js/obsada-planner.js","index.html"],"related":[{"category":"kpi","topic":"processes"}]},{"id":"teams","title":{"pl":"Zespoły i osoby funkcyjne","ru":"Команды и функциональные сотрудники","en":"Teams and functional staff","uk":"Команди та функціональні працівники"},"basic":{"pl":"Zespoły i osoby funkcyjne są oddzielone od indywidualnych przydziałów godzinowych. Osoby funkcyjne nie powinny być liczone jako inny dział.","ru":"Команды и функциональные сотрудники учитываются отдельно от почасовых назначений. Функциональный сотрудник не должен автоматически попадать в «другие отделы».","en":"Teams and functional roles are managed separately from hourly assignments. Functional staff should not automatically count as other departments.","uk":"Команди та функціональні ролі ведуться окремо від погодинних призначень. Функціональних працівників не слід автоматично відносити до інших відділів."},"tech":{"pl":"W widoku obsady można rozdzielić lokalne procesy, osoby funkcyjne i osoby z innych działów. Zapisane zespoły oraz szablony zespołów mogą być ponownie użyte. Podział na te grupy wpływa na prezentację stanów, ale nie jest tym samym co historia pracy.","ru":"В расстановке отдельно отображаются локальные процессы, функциональные сотрудники и другие отделы. Сохранённые команды и шаблоны используются повторно. Группировка влияет на отображение, но не заменяет историю выполненной работы.","en":"Staffing can separate local processes, functional staff and other departments. Saved teams and team templates can be reused. These display groups are not the same as verified work history.","uk":"У розстановці можна розділити локальні процеси, функціональних працівників та інші відділи. Збережені команди й шаблони можна повторно використовувати. Це групування не замінює історію роботи."},"sources":["js/obsada-planner.js","index.html"],"related":[]},{"id":"attendance","title":{"pl":"Spóźnienie, wcześniejsze wyjście i nieobecność","ru":"Опоздание, ранний уход и отсутствие","en":"Late arrival, early departure and absence","uk":"Запізнення, ранній вихід і відсутність"},"basic":{"pl":"Planowanie obsługuje spóźnienia, wcześniejsze wyjścia oraz statusy WOLNY i URLOP. Zmiana statusu może wpłynąć na godzinowe przydziały.","ru":"В Planowanie доступны опоздание, ранний уход, а также WOLNY и URLOP. Изменение статуса может повлиять на почасовые назначения.","en":"Planowanie supports late arrival, early departure, WOLNY and URLOP. A status change may affect hourly assignments.","uk":"Planowanie підтримує запізнення, ранній вихід, WOLNY та URLOP. Зміна статусу може впливати на погодинні призначення."},"tech":{"pl":"Zdarzenia spóźnienia i wcześniejszego wyjścia dotyczą konkretnej zmiany i czasu. Przy konfliktach z zapisanymi godzinami pojawia się potwierdzenie. Status nieobecności WOLNY / URLOP w lokalnym planie ma pierwszeństwo przy liczeniu efektywnej historii danego dnia; importowanych oryginalnych danych SharePoint nie usuwa automatycznie.","ru":"Опоздание и ранний уход задаются для конкретной смены и времени. При конфликте с сохранёнными часами приложение запрашивает подтверждение. Локальные WOLNY / URLOP имеют приоритет при расчёте эффективной истории дня, но не удаляют исходные записи SharePoint.","en":"Late-arrival and early-departure events belong to a specific shift and time. Conflicts with recorded hours trigger confirmation. Local WOLNY / URLOP status takes priority in effective history for that day, without deleting the original imported SharePoint records.","uk":"Запізнення й ранній вихід належать до конкретної зміни та часу. Конфлікти зі збереженими годинами потребують підтвердження. Локальні WOLNY / URLOP мають пріоритет в ефективній історії дня, але не видаляють джерельні записи SharePoint."},"sources":["js/obsada-planner.js","js/obsada-unified-history.js"],"related":[]},{"id":"automatic","title":{"pl":"Automatyczne potwierdzanie godzin","ru":"Автоматическое подтверждение часов","en":"Automatic completion of elapsed hours","uk":"Автоматичне підтвердження годин"},"basic":{"pl":"Godzina zaplanowana w lokalnej bazie otrzymuje status POTWIERDZONE_AUTO po upływie jej końca; nie wymaga ręcznego potwierdzenia.","ru":"Запланированный локальный час получает статус POTWIERDZONE_AUTO после окончания интервала. Ручное подтверждение не требуется.","en":"A locally planned hourly slot becomes POTWIERDZONE_AUTO after its end time; no manual confirmation is required.","uk":"Локальна запланована година отримує POTWIERDZONE_AUTO після завершення. Ручне підтвердження не потрібне."},"tech":{"pl":"To reguła oparta na czasie, nie niezależny dowód fizycznej obecności pracownika. Można korygować minione lokalne przydziały. W efektywnej Historii przyszłe godziny są planem, a zakończone mogą uczestniczyć w rozliczeniu zgodnie z regułami scalania. Zachowuj ostrożność przy porównaniu ze źródłowym SharePoint.","ru":"Это статус по времени, а не доказательство фактического присутствия человека. Прошедшие локальные назначения можно исправлять. В Historia будущие часы остаются планом, а завершённые участвуют в расчёте по правилам объединения. Сверяй с SharePoint при расхождениях.","en":"This time-based state is not independent proof of physical attendance. Elapsed local assignments can be corrected. Effective Historia treats future hours as plans and elapsed hours according to reconciliation rules. Compare discrepancies against SharePoint.","uk":"Це статус за часом, а не доказ фактичної присутності. Минулі локальні призначення можна виправляти. У Historia майбутні години є планом, завершені враховуються за правилами поєднання. Звіряй відмінності з SharePoint."},"sources":["js/obsada-planner.js","js/obsada-unified-history.js"],"related":[{"category":"kpi","topic":"processes"}]},{"id":"tomorrow","title":{"pl":"Plan na jutro: podgląd, Excel i druk","ru":"План на завтра: просмотр, Excel и печать","en":"Tomorrow plan: preview, Excel and print","uk":"План на завтра: перегляд, Excel і друк"},"basic":{"pl":"Widok Plan na jutro przygotowuje wybrany skład na następny dzień i zmianę; można go wydrukować albo wyeksportować do Excel.","ru":"Plan na jutro формирует список на завтрашний день и выбранную смену. Его можно распечатать или выгрузить в Excel.","en":"Plan na jutro prepares a roster for the following day and chosen shift, with print and Excel export.","uk":"Plan na jutro готує склад на наступний день і вибрану зміну, із друком та експортом Excel."},"tech":{"pl":"Przed eksportem sprawdź dzień, zmianę, wybrane procesy i osoby. Można uwzględnić grupy WOLNY / URLOP jako oddzielną sekcję, poza liczbą pracujących. Wybrane zespoły decydują o układzie eksportu. Nazwa i układ dokumentu zależą od wybranej daty i zmiany.","ru":"Перед экспортом проверь дату, смену, процессы и отмеченных людей. WOLNY / URLOP могут идти отдельным блоком вне количества работающих. Выбранные команды определяют колонки и раскладку экспорта. Название документа зависит от даты и смены.","en":"Before exporting, verify the date, shift, processes and selected people. WOLNY / URLOP may appear in a separate absence section rather than the working headcount. Selected teams determine the output layout; the document uses the chosen date and shift.","uk":"Перед експортом перевір дату, зміну, процеси й людей. WOLNY / URLOP можуть бути окремим блоком поза кількістю працюючих. Обрані команди визначають макет, дата й зміна використовуються у назві документа."},"sources":["js/obsada-planner.js","index.html"],"related":[]},{"id":"database","title":{"pl":"Baza lokalna: zapis, kopia i przywracanie","ru":"Локальная база: сохранение, копии, восстановление","en":"Local database: saving, backups and recovery","uk":"Локальна база: збереження, копії та відновлення"},"basic":{"pl":"Główna baza Planowanie jest lokalna. Dane pozostają w przeglądarce, a autoryzowany folder pozwala zapisywać plik Excel.","ru":"Основная база Planowanie локальная. Данные хранятся в браузере, а разрешённая папка позволяет сохранять Excel-файл.","en":"The main planning database is local. Records persist in browser storage, while an authorized folder enables XLSX file saving.","uk":"Основна база планування локальна. Дані залишаються у браузері, дозволена тека забезпечує запис Excel."},"tech":{"pl":"Wybierz folder do zapisu, obserwuj status Excel zapisany / błąd / wymagane uprawnienia. Po utracie dostępu do folderu podłącz go ponownie. Nie myl pamięci przeglądarki z plikiem na dysku: mogą się różnić. Przed scaleniem lub przenoszeniem danych wykonaj kopię bezpieczeństwa; aplikacja wykrywa zewnętrzne zmiany i oferuje rozwiązywanie konfliktów.","ru":"Выбери папку и следи за статусом сохранения Excel или ошибкой разрешений. Если доступ к папке потерян, разреши его снова. Хранилище браузера и файл на диске не всегда совпадают. Перед объединением сделай резервную копию. При внешних изменениях база обнаруживает конфликты.","en":"Choose an authorized folder and watch the Excel saved / error / permission-required status. Reconnect lost folder permissions. Browser storage and the disk workbook can diverge. Back up before merging. External changes can be detected and reconciled.","uk":"Обери дозволену теку й перевіряй статус збереження Excel та дозволів. Після втрати доступу підключи теку знову. Пам’ять браузера й файл на диску можуть відрізнятися. Перед злиттям зроби копію; зовнішні зміни виявляються як конфлікти."},"sources":["js/obsada-planner.js","index.html"],"related":[]},{"id":"exchange","title":{"pl":"Przekaż koledze / Odbierz od kolegi","ru":"Передать коллеге / Получить от коллеги","en":"Send to colleague / Receive from colleague","uk":"Передати колезі / Отримати від колеги"},"basic":{"pl":"Dwie osoby mogą wymienić się plikami lokalnej bazy XLSX. Scalanie pokazuje nowe dane i konflikty; nie jest to synchronizacja online w czasie rzeczywistym.","ru":"Два сотрудника могут обмениваться XLSX-файлами локальной базы. При объединении показываются новые записи и конфликты. Это не онлайн-синхронизация в реальном времени.","en":"Colleagues exchange local XLSX database files. Merge preview shows incoming records and conflicts; this is not live online synchronization.","uk":"Колеги обмінюються XLSX локальної бази. Попередній перегляд показує нові записи й конфлікти. Це не онлайн-синхронізація."},"tech":{"pl":"Użyj Przekaż koledze do wydania pliku, Odbierz od kolegi do analizy obcego pliku. W konfliktach zachowaj lokalny wpis lub wybierz dane kolegi, pojedynczo albo „Dane kolegi dla wszystkich”, a potem popraw wyjątki. Przy uprawnionym folderze aplikacja próbuje zachować kopie w Backup i Import. Nie zastępuj pliku bez sprawdzenia podglądu.","ru":"Используй Przekaż koledze для передачи базы и Odbierz od kolegi для загрузки чужой. В конфликтах можно оставить свою запись или выбрать коллеги, отдельно либо через «Dane kolegi dla wszystkich» с последующей корректировкой исключений. При доступной папке приложение пытается сохранять копии Backup и Import. Не сливай вслепую.","en":"Use Przekaż koledze to send your database, Odbierz od kolegi to preview a received file. For each conflict keep your record or choose the colleague’s, or apply “Dane kolegi dla wszystkich” and fine-tune exceptions. With folder permissions the app attempts backups in Backup and Import. Always review before merging.","uk":"Przekaż koledze передає базу, Odbierz od kolegi переглядає отриманий файл. Для конфліктів залиш свій запис або вибери запис колеги, окремо чи через «Dane kolegi dla wszystkich» з уточненням винятків. За доступної теки застосунок намагається зберегти Backup та Import. Перевір попередній перегляд."},"sources":["js/obsada-merge.js","js/obsada-planner.js","README.md"],"related":[]},{"id":"history","title":{"pl":"Historia: źródła, korekty i rozbieżności","ru":"История: источники, правки и расхождения","en":"Historia: sources, corrections and differences","uk":"Historia: джерела, виправлення й розбіжності"},"basic":{"pl":"Historia łączy wpisy importowane z lokalnymi godzinami i statusami. Pokazuje rozbieżności bez ukrywania oryginalnego importu.","ru":"Historia объединяет импортированные записи с локальными часами и статусами. Различия видны, исходный импорт не теряется.","en":"Historia reconciles imported records, local hours and absence statuses; discrepancies remain visible without silently destroying imported source data.","uk":"Historia поєднує імпортовані записи, локальні години та статуси. Розбіжності видно без непомітного видалення оригінальних даних."},"tech":{"pl":"Lokalne zakończone godziny mogą zastąpić importowane sumy w efektywnym widoku dla tego pracownika i dnia; oryginalne importy nadal służą do kontroli. Korekty historii mogą usuwać przydziały lokalne, a wpisy SharePoint oznaczać jako lokalnie wykluczone. Przy zbiorczych zmianach wyświetlane jest potwierdzenie. Nie utożsamiaj importu z ręcznie potwierdzoną obecnością.","ru":"Завершённые локальные часы могут иметь приоритет над импортированной суммой за сотрудника и день в эффективной истории, но исходный импорт доступен для проверки. При корректировке локальные назначения можно удалить, записи SharePoint локально исключить без изменения источника. Массовые операции требуют подтверждения.","en":"Elapsed local hours may supersede imported totals in effective history for a worker/day while originals remain for review. History corrections can remove local assignments or mark SharePoint imports as locally excluded without editing the source. Bulk changes require confirmation.","uk":"Завершені локальні години можуть мати пріоритет над імпортованими підсумками за день, а оригінал лишається для перевірки. Виправлення можуть видалити локальні призначення або локально виключити SharePoint-записи без зміни джерела. Масові зміни потребують підтвердження."},"sources":["js/obsada-unified-history.js","js/obsada-planner.js"],"related":[{"category":"kpi","topic":"processes"}]},{"id":"analysis","title":{"pl":"Analiza: godziny, dni i filtry","ru":"Анализ: часы, дни и фильтры","en":"Analiza: hours, days and filters","uk":"Analiza: години, дні та фільтри"},"basic":{"pl":"Analiza pokazuje efektywne godziny i dni pracy. Możesz wybrać tydzień, miesiąc lub zakres dat, pracownika albo zapisany zespół i jeden lub kilka procesów.","ru":"Analiza показывает рабочие часы и дни. Можно выбрать неделю, месяц или диапазон, сотрудника либо команду и один или несколько процессов.","en":"Analiza shows effective hours and workdays. Select week, month or date range, workers or saved teams, and one or multiple processes.","uk":"Analiza показує години та робочі дні. Обери тиждень, місяць чи діапазон, працівників або команди, один чи кілька процесів."},"tech":{"pl":"Karty liczą godziny tylko dla wybranych procesów; dzień z pracą na dwóch zaznaczonych procesach liczy się jako jeden dzień pracy. Ostatnia / Poprzednia przedstawiają dwa ostatnie ukończone dni pracy ze wszystkich procesów, niezależnie od filtra analizy. Nieobecności pokazuje się oddzielnie. Wynik opiera się na efektywnej Historii, nie na samych planach przyszłości.","ru":"Карточки суммируют часы только выбранных процессов; день с двумя выбранными процессами считается одним рабочим днём. «Ostatnia / Poprzednia» показывают два последних завершённых рабочих дня по всем процессам независимо от фильтра. Отсутствия отображаются отдельно. Анализ использует эффективную Historia, а не будущие планы.","en":"Cards sum hours only for selected processes; a day on two selected processes counts as one workday. “Ostatnia / Poprzednia” show the two last completed workdays across all processes regardless of the analysis filter. Absence days remain separate. Results use effective Historia, not future plans alone.","uk":"Картки підсумовують години вибраних процесів; день із двома вибраними процесами рахується як один робочий день. «Ostatnia / Poprzednia» показують два останні завершені робочі дні за всіма процесами незалежно від фільтра. Відсутності окремо. Дані з ефективної Historia."},"sources":["js/obsada-team-intelligence.js","README.md"],"related":[]}]},{"id":"rights","emoji":"🛡","title":{"pl":"Licencja i bezpieczeństwo","ru":"Лицензия и безопасность","en":"License and safety","uk":"Ліцензія та безпека"},"topics":[{"id":"license","title":{"pl":"Licencja: co wolno, a czego nie","ru":"Лицензия: что можно и нельзя","en":"License: permitted and restricted use","uk":"Ліцензія: що дозволено і заборонено"},"basic":{"pl":"Mr. Robot można bezpłatnie uruchamiać do celów osobistych i wewnętrznych zadań służbowych, również w innych organizacjach. Nie oznacza to prawa do modyfikowania kodu.","ru":"Mr. Robot можно бесплатно использовать для личной и внутренней рабочей деятельности, в том числе в других компаниях. Это не разрешает изменять код.","en":"Mr. Robot can be run free of charge for personal and internal workplace use, including other organizations. This does not grant permission to modify the code.","uk":"Mr. Robot можна безкоштовно використовувати особисто та для внутрішніх робочих задач, також в інших організаціях. Це не дозвіл змінювати код."},"tech":{"pl":"Bez osobnej zgody uprawnionego nie wolno modyfikować oryginalnego kodu, rozpowszechniać ani sprzedawać kopii, publikować własnych wersji, usuwać atrybucji ani wydawać oryginału za własny. Obowiązujące prawo, warunki GitHub i licencje komponentów zewnętrznych mogą przewidywać niezależne uprawnienia. Szczegóły: LICENSE (angielski), LICENSE.pl.md, LICENSE.ru.md, LICENSE.uk.md; nie myl licencji projektu z licencjami bibliotek.","ru":"Без отдельного разрешения правообладателя нельзя модифицировать оригинальный код, распространять или продавать копии, публиковать свои версии, удалять авторство или выдавать оригинал за свою разработку. Обязательные нормы закона, условия GitHub и лицензии сторонних компонентов могут предоставлять отдельные права. Полный текст: LICENSE (EN), LICENSE.pl.md, LICENSE.ru.md, LICENSE.uk.md.","en":"Without separate permission from the rights holder, users may not modify original code, redistribute or sell copies, publish their own versions, remove required attribution or claim the original as their own. Mandatory law, GitHub terms and third-party licenses may provide independent rights. Full terms: LICENSE (EN), LICENSE.pl.md, LICENSE.ru.md and LICENSE.uk.md.","uk":"Без окремого дозволу правовласника не можна змінювати оригінальний код, поширювати чи продавати копії, публікувати свої версії, прибирати авторство чи видавати оригінал за власний. Обов’язкове право, умови GitHub та ліцензії сторонніх бібліотек можуть надавати окремі права. Повний текст: LICENSE (EN), LICENSE.pl.md, LICENSE.ru.md, LICENSE.uk.md."},"related":[{"category":"about","topic":"purpose"}],"sources":["LICENSE","LICENSE.pl.md","LICENSE.ru.md","LICENSE.uk.md"]},{"id":"attribution","title":{"pl":"Autor, repozytorium i źródło","ru":"Автор, репозиторий и источник","en":"Author, repository and provenance","uk":"Автор, репозиторій та походження"},"basic":{"pl":"Autorem wskazanym w projekcie jest Raman Horki. Oficjalne repozytorium i profil autora są podlinkowane w Ustawienia → O projekcie.","ru":"В проекте автором указан Raman Horki. Официальный репозиторий и профиль автора находятся в Ustawienia → O projekcie.","en":"The project identifies Raman Horki as author. The official repository and author profile are linked from Settings → O projekcie.","uk":"У проєкті автором зазначено Raman Horki. Офіційний репозиторій і профіль автора доступні в Ustawienia → O projekcie."},"tech":{"pl":"Repozytorium: github.com/horkiroman4408-cyber/Mr.-Robot-App. Profil: github.com/horkiroman4408-cyber. Publiczny dostęp do kodu nie oznacza automatycznie otwartej licencji na zmiany i redystrybucję; prawa innych uprawnionych pozostają nienaruszone.","ru":"Репозиторий: github.com/horkiroman4408-cyber/Mr.-Robot-App. Профиль: github.com/horkiroman4408-cyber. Публичный доступ к исходникам сам по себе не даёт разрешения изменять и распространять их; права иных правообладателей сохраняются.","en":"Repository: github.com/horkiroman4408-cyber/Mr.-Robot-App. Profile: github.com/horkiroman4408-cyber. Public source visibility is not an automatic open-source grant for modifications and redistribution; third-party rights remain intact.","uk":"Репозиторій: github.com/horkiroman4408-cyber/Mr.-Robot-App. Профіль: github.com/horkiroman4408-cyber. Публічний доступ до коду не є автоматичним дозволом на зміни та поширення; сторонні права зберігаються."},"sources":["index.html","LICENSE"],"related":[]},{"id":"privacy","title":{"pl":"Dane pracowników i uprawnienia","ru":"Данные сотрудников и разрешения","en":"Employee data and permissions","uk":"Дані працівників і дозволи"},"basic":{"pl":"Przetwarzanie lokalne nie daje uprawnienia do ujawniania danych pracowników ani raportów służbowych. Korzystaj wyłącznie z danych, do których masz dostęp.","ru":"Локальная обработка не даёт права раскрывать данные сотрудников или служебные отчёты. Используй только сведения, к которым есть разрешённый доступ.","en":"Local processing does not authorize disclosure of employee data or workplace reports. Use only data you are permitted to access.","uk":"Локальна обробка не дозволяє розкривати дані працівників чи службові звіти. Використовуй лише дані, до яких маєш дозвіл."},"tech":{"pl":"Nie umieszczaj rzeczywistych danych osobowych i poufnych XLSX w publicznych zgłoszeniach GitHub. Bridge nie zwiększa uprawnień WMS / SharePoint. Eksporty, kopie, foldery lokalne i dane wysyłane kolegom wymagają zgodnego z polityką firmy postępowania.","ru":"Не выкладывай реальные персональные данные и конфиденциальные XLSX в публичные GitHub Issues. Bridge не повышает права WMS / SharePoint. Экспорт, резервные копии, папки и файлы коллегам должны соответствовать правилам компании.","en":"Never attach real personal data or confidential XLSX files to public GitHub issues. Bridge does not expand WMS / SharePoint permissions. Exports, backups, local folders and colleague file exchange must respect workplace policies.","uk":"Не публікуй персональні дані чи конфіденційні XLSX у GitHub Issues. Bridge не розширює права WMS / SharePoint. Експорти, резервні копії, теки та обмін файлами мають відповідати політикам організації."},"related":[{"category":"about","topic":"privacy"},{"category":"obsada","topic":"exchange"}],"sources":["README.md","LICENSE"]}]}];
